css:
/* Loam: the album that is playing re-tints the app. --apv-music-tint is a
   registered <color>, so the whole palette derived from it interpolates. */
@property --apv-music-tint { syntax: '<color>'; inherits: true; initial-value: oklch(0.6 0.17 40); }
@property --apv-music-spin { syntax: '<angle>'; inherits: true; initial-value: 0deg; }

.apv-music {
  /* re-theme: paper, ink, accent */
  --apv-music-paper: oklch(0.972 0.009 85);
  --apv-music-ink: oklch(0.24 0.02 55);
  --apv-music-accent: oklch(0.6 0.18 38);
  --apv-music-tint: var(--apv-music-accent);
  --apv-music-card: color-mix(in oklch, var(--apv-music-paper) 55%, white);
  --apv-music-line: color-mix(in oklch, var(--apv-music-ink) 9%, transparent);
  --apv-music-line2: color-mix(in oklch, var(--apv-music-ink) 16%, transparent);
  --apv-music-mute: color-mix(in oklch, var(--apv-music-ink) 62%, var(--apv-music-paper));
  --apv-music-faint: color-mix(in oklch, var(--apv-music-ink) 40%, var(--apv-music-paper));
  --apv-music-wash: color-mix(in oklch, var(--apv-music-tint) 14%, var(--apv-music-paper));
  --apv-music-deep: color-mix(in oklch, var(--apv-music-tint) 78%, var(--apv-music-ink));
  --apv-music-ease: cubic-bezier(.2, .8, .2, 1);
  --apv-music-spring: linear(0, 0.1 4%, 0.38 10%, 0.74 17%, 0.96 24%, 1.04 30%, 1.05 35%, 1.02 44%, 1 55%, 1);

  position: relative; width: 100%; height: var(--apv-music-h, 680px);
  container-type: inline-size; overflow: clip; isolation: isolate; box-sizing: border-box;
  background: var(--apv-music-paper); color: var(--apv-music-ink); color-scheme: light;
  accent-color: var(--apv-music-tint); border-radius: 14px;
  font: 13px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-tap-highlight-color: transparent;
  transition: --apv-music-tint 1.2s var(--apv-music-ease);

  & *, & *::before, & *::after { box-sizing: border-box; }
  &:focus { outline: none; }
  & :focus-visible { outline: 2px solid var(--apv-music-deep); outline-offset: 2px; border-radius: 6px; }
  & button, & input { font: inherit; color: inherit; }
  & button { cursor: pointer; background: none; border: 0; padding: 0; }
  & h2, & h3, & p, & ol, & ul, & dl, & dd { margin: 0; padding: 0; }
  & ol, & ul { list-style: none; }
  & svg { width: 18px; height: 18px; fill: none; stroke: currentColor; stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; flex: none; }
  & .apv-music-fill { fill: currentColor; stroke: none; }
  & mark { background: color-mix(in oklch, var(--apv-music-tint) 26%, transparent); color: inherit; border-radius: 3px; }
  & kbd { font: 600 10px/1 ui-monospace, Menlo, monospace; padding: 2px 5px; min-width: 18px; display: inline-block; text-align: center; border: 1px solid var(--apv-music-line2); border-bottom-width: 2px; border-radius: 4px; color: var(--apv-music-mute); background: var(--apv-music-card); }
}

.apv-music .apv-music-app {
  height: 100%; display: grid;
  grid-template-columns: 212px minmax(0, 1fr) 296px;
  grid-template-rows: minmax(0, 1fr) auto;
  grid-template-areas: "side main queue" "bar bar bar";
  transition: grid-template-columns .5s var(--apv-music-ease);
}
.apv-music[data-queue="closed"] .apv-music-app { grid-template-columns: 212px minmax(0, 1fr) 0px; }

/* ── side ── */
.apv-music .apv-music-side {
  grid-area: side; min-height: 0; display: flex; flex-direction: column; gap: 18px; padding: 18px 12px 14px;
  border-right: 1px solid var(--apv-music-line); overflow: hidden auto; scrollbar-width: none;
}
.apv-music .apv-music-brand {
  display: flex; align-items: center; gap: 8px; padding: 0 8px;
  & svg { width: 22px; height: 22px; color: var(--apv-music-deep); stroke-width: 2; }
  & b { font-size: 17px; font-weight: 780; letter-spacing: -.04em; }
  & small { margin-left: auto; font-size: 10px; font-weight: 650; letter-spacing: .12em; text-transform: uppercase; color: var(--apv-music-faint); }
}
.apv-music .apv-music-nav {
  display: grid; gap: 1px;
  & h4 { margin: 14px 10px 6px; font-size: 10px; font-weight: 700; letter-spacing: .13em; text-transform: uppercase; color: var(--apv-music-faint); }
  & h4:first-child { margin-top: 0; }
  & button {
    display: flex; align-items: center; gap: 10px; width: 100%; padding: 7px 10px; border-radius: 8px; text-align: left;
    font-size: 13px; font-weight: 550; color: var(--apv-music-mute); transition: background .2s, color .2s;
    & svg { width: 17px; height: 17px; }
    & .apv-music-cover, & .apv-music-mosaic { width: 22px; border-radius: 4px; flex: none; }
    & .apv-music-mosaic .apv-music-cover { width: auto; border-radius: 0; }
    & span { flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
    & output { font: 500 11px ui-monospace, Menlo, monospace; font-variant-numeric: tabular-nums; color: var(--apv-music-faint); }
    &:hover { background: var(--apv-music-line); color: var(--apv-music-ink); }
    &[aria-current="page"] { background: var(--apv-music-card); color: var(--apv-music-ink); box-shadow: 0 0 0 1px var(--apv-music-line), 0 1px 2px var(--apv-music-line); }
    &[aria-current="page"] svg { color: var(--apv-music-deep); }
    &.is-live span::after { content: ""; display: inline-block; width: 6px; height: 6px; margin-left: 7px; border-radius: 50%; background: var(--apv-music-tint); vertical-align: 1px; }
  }
}
.apv-music .apv-music-keybtn {
  margin-top: auto; display: flex; align-items: center; gap: 9px; padding: 8px 10px; border-radius: 8px; color: var(--apv-music-mute); font-size: 12.5px;
  & span { flex: 1; text-align: left; }
  &:hover { background: var(--apv-music-line); color: var(--apv-music-ink); }
}

/* ── main ── */
.apv-music .apv-music-main { grid-area: main; min-height: 0; min-width: 0; display: grid; grid-template-rows: auto minmax(0, 1fr); }
.apv-music .apv-music-top { display: flex; align-items: center; gap: 10px; padding: 14px 24px 10px; }
.apv-music .apv-music-back {
  display: grid; place-items: center; width: 32px; height: 32px; border-radius: 50%; border: 1px solid var(--apv-music-line2);
  transition: opacity .25s, transform .35s var(--apv-music-spring), background .2s;
  &:hover { background: var(--apv-music-card); }
}
.apv-music:not([data-back="true"]) .apv-music-back { opacity: 0; transform: translateX(-6px); pointer-events: none; }
.apv-music .apv-music-search {
  flex: 1; max-width: 360px; margin-left: auto; display: flex; align-items: center; gap: 8px; height: 34px; padding: 0 7px 0 11px;
  border-radius: 999px; background: var(--apv-music-card); box-shadow: inset 0 0 0 1px var(--apv-music-line2); transition: box-shadow .2s;
  & svg { width: 16px; height: 16px; color: var(--apv-music-faint); }
  & input { flex: 1; min-width: 0; border: 0; outline: 0; background: none; font-size: 13px; }
  & input::placeholder { color: var(--apv-music-faint); }
  & input::-webkit-search-cancel-button { display: none; }
  &:focus-within { box-shadow: inset 0 0 0 1.5px var(--apv-music-deep), 0 0 0 4px color-mix(in oklch, var(--apv-music-tint) 15%, transparent); }
  &:focus-within kbd { opacity: 0; }
}
.apv-music .apv-music-scroll { min-height: 0; overflow: auto; overscroll-behavior: contain; scrollbar-width: thin; scrollbar-color: var(--apv-music-line2) transparent; padding: 4px 24px 28px; }
.apv-music .apv-music-view {
  animation: apv-music-in .45s var(--apv-music-ease) both;
}
.apv-music .apv-music-head {
  display: flex; align-items: end; gap: 22px; padding: 6px 0 22px;
  & .apv-music-cover { width: clamp(116px, 15cqi, 184px); flex: none; box-shadow: 0 18px 40px -18px color-mix(in oklch, var(--apv-music-ink) 55%, transparent), 0 0 0 1px var(--apv-music-line); }
  & .apv-music-htxt { min-width: 0; display: grid; gap: 4px; }
  & small { font-size: 10.5px; font-weight: 700; letter-spacing: .14em; text-transform: uppercase; color: var(--apv-music-deep); }
  & h2 { font-size: clamp(24px, 3.2cqi, 40px); line-height: 1.02; font-weight: 800; letter-spacing: -.045em; text-wrap: balance; }
  & p { color: var(--apv-music-mute); font-variant-numeric: tabular-nums; text-wrap: pretty; }
  & p b { color: var(--apv-music-ink); font-weight: 650; }
}
.apv-music .apv-music-acts { display: flex; gap: 8px; margin-top: 10px; flex-wrap: wrap; }
.apv-music .apv-music-btn {
  display: inline-flex; align-items: center; gap: 7px; height: 34px; padding: 0 15px 0 12px; border-radius: 999px; font-weight: 650; font-size: 13px;
  border: 1px solid var(--apv-music-line2); background: var(--apv-music-card);
  transition: transform .3s var(--apv-music-spring), background .2s, box-shadow .2s;
  & svg { width: 16px; height: 16px; }
  &:hover { transform: translateY(-1px); box-shadow: 0 6px 16px -10px var(--apv-music-ink); }
  &:active { transform: scale(.97); }
  &.is-pri { background: var(--apv-music-deep); color: var(--apv-music-paper); border-color: transparent; }
}

/* album grid */
.apv-music .apv-music-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(clamp(128px, 17cqi, 172px), 1fr)); gap: 22px 18px; }
.apv-music .apv-music-alb {
  display: grid; gap: 9px; text-align: left; border-radius: 8px;
  animation: apv-music-rise .5s var(--apv-music-ease) both; animation-delay: calc(var(--i, 0) * 40ms);
  & .apv-music-cover { box-shadow: 0 0 0 1px var(--apv-music-line), 0 10px 22px -16px var(--apv-music-ink); transition: transform .45s var(--apv-music-spring), box-shadow .3s; }
  & b { display: block; font-size: 13px; font-weight: 650; letter-spacing: -.01em; line-height: 1.25; text-wrap: balance; }
  & small { display: block; font-size: 12px; color: var(--apv-music-mute); }
  &:hover .apv-music-cover, &:focus-visible .apv-music-cover { transform: translateY(-3px) rotate(-.6deg); box-shadow: 0 0 0 1px var(--apv-music-line), 0 20px 30px -18px var(--apv-music-ink); }
  &:focus-visible { outline-offset: 5px; }
}
.apv-music .apv-music-sec { margin: 4px 0 12px; font-size: 10.5px; font-weight: 700; letter-spacing: .14em; text-transform: uppercase; color: var(--apv-music-faint); }
.apv-music .apv-music-h2 { font-size: clamp(22px, 2.6cqi, 30px); font-weight: 800; letter-spacing: -.04em; margin: 6px 0 2px; }
.apv-music .apv-music-sub { color: var(--apv-music-mute); font-variant-numeric: tabular-nums; margin-bottom: 20px; }

/* track list: one grid, rows are subgrids so columns line up */
.apv-music .apv-music-list {
  display: grid; grid-template-columns: 34px minmax(0, 2.2fr) minmax(0, 1.4fr) 52px 34px; column-gap: 12px;
  &.no-album { grid-template-columns: 34px minmax(0, 1fr) 52px 34px; }
}
.apv-music .apv-music-lh {
  grid-column: 1 / -1; display: grid; grid-template-columns: subgrid; padding: 0 8px 8px; border-bottom: 1px solid var(--apv-music-line); margin-bottom: 4px;
  & button, & span { font-size: 10.5px; font-weight: 700; letter-spacing: .1em; text-transform: uppercase; color: var(--apv-music-faint); text-align: left; display: flex; align-items: center; gap: 4px; }
  & button:hover { color: var(--apv-music-ink); }
  & button svg { width: 12px; height: 12px; opacity: 0; transition: transform .3s var(--apv-music-ease), opacity .2s; }
  & [aria-sort="ascending"] svg { opacity: 1; }
  & [aria-sort="descending"] svg { opacity: 1; transform: rotate(180deg); }
  & .r { justify-content: end; }
}
.apv-music .apv-music-row {
  grid-column: 1 / -1; display: grid; grid-template-columns: subgrid; align-items: center; border-radius: 8px; position: relative;
  animation: apv-music-rise .42s var(--apv-music-ease) both; animation-delay: calc(min(var(--i, 0), 14) * 22ms);
  transition: background .18s;
  &:hover, &:has(:focus-visible) { background: var(--apv-music-card); box-shadow: 0 0 0 1px var(--apv-music-line); }
  &:has(:focus-visible) :focus-visible { outline: none; }
  & .apv-music-rowbtn {
    grid-column: 1 / -2; display: grid; grid-template-columns: subgrid; align-items: center; padding: 7px 0 7px 8px; text-align: left; min-width: 0;
  }
  & .apv-music-num { display: grid; place-items: center; width: 22px; height: 22px; font: 500 12px ui-monospace, Menlo, monospace; font-variant-numeric: tabular-nums; color: var(--apv-music-faint); position: relative; }
  & .apv-music-num > svg { position: absolute; width: 14px; height: 14px; opacity: 0; color: var(--apv-music-ink); }
  &:hover .apv-music-n, & .apv-music-rowbtn:focus-visible .apv-music-n { opacity: 0; }
  &:hover .apv-music-num > svg, & .apv-music-rowbtn:focus-visible .apv-music-num > svg { opacity: 1; }
  & .apv-music-tt { display: flex; align-items: center; gap: 10px; min-width: 0; }
  & .apv-music-tt .apv-music-cover { width: 34px; border-radius: 4px; flex: none; }
  & .apv-music-tt span { display: grid; min-width: 0; }
  & b { font-weight: 560; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
  & small { font-size: 12px; color: var(--apv-music-mute); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
  & .apv-music-al { color: var(--apv-music-mute); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-size: 12.5px; }
  & .apv-music-dur { text-align: right; font: 500 12px ui-monospace, Menlo, monospace; font-variant-numeric: tabular-nums; color: var(--apv-music-mute); }
  &.is-cur b { color: var(--apv-music-deep); font-weight: 700; }
  &.is-cur .apv-music-n { opacity: 0; }
}
.apv-music .apv-music-eq {
  position: absolute; inset: 0; display: none; align-items: end; justify-content: center; gap: 2px; padding: 5px 4px;
  & i { width: 3px; height: 100%; border-radius: 2px; background: var(--apv-music-deep); transform-origin: bottom; transform: scaleY(.3);
        animation: apv-music-eq .9s var(--apv-music-ease) infinite alternate paused; animation-delay: calc(var(--i) * -310ms); }
}
.apv-music .apv-music-row.is-cur .apv-music-eq { display: flex; }
.apv-music .apv-music-row.is-cur:hover .apv-music-eq { display: none; }
.apv-music[data-playing="true"] .apv-music-eq i { animation-play-state: running; }

.apv-music .apv-music-heart {
  display: grid; place-items: center; width: 30px; height: 30px; border-radius: 50%; color: var(--apv-music-faint); transition: color .2s, transform .4s var(--apv-music-spring);
  & svg { width: 17px; height: 17px; transition: fill .2s; }
  &:hover { color: var(--apv-music-ink); }
  &[aria-pressed="true"] { color: var(--apv-music-deep); }
  &[aria-pressed="true"] svg { fill: currentColor; animation: apv-music-pop .5s var(--apv-music-spring); }
}
.apv-music .apv-music-row .apv-music-heart { opacity: 0; }
.apv-music .apv-music-row:hover .apv-music-heart, .apv-music .apv-music-row .apv-music-heart[aria-pressed="true"], .apv-music .apv-music-row .apv-music-heart:focus-visible { opacity: 1; }

.apv-music .apv-music-empty { padding: 48px 0; text-align: center; color: var(--apv-music-mute); text-wrap: balance;
  & b { display: block; color: var(--apv-music-ink); font-size: 15px; margin-bottom: 4px; }
}
.apv-music .apv-music-chips { display: flex; flex-wrap: wrap; gap: 8px; margin-bottom: 26px;
  & button { padding: 7px 13px; border-radius: 999px; border: 1px solid var(--apv-music-line2); font-weight: 600; font-size: 12.5px; background: var(--apv-music-card); transition: transform .3s var(--apv-music-spring), background .2s; }
  & button:hover { transform: translateY(-1px); background: var(--apv-music-wash); }
}
.apv-music .apv-music-top1 {
  display: flex; align-items: center; gap: 16px; padding: 14px; border-radius: 12px; background: var(--apv-music-card); box-shadow: 0 0 0 1px var(--apv-music-line); margin-bottom: 24px; text-align: left; width: 100%;
  & .apv-music-cover { width: 76px; flex: none; }
  & b { display: block; font-size: 19px; font-weight: 780; letter-spacing: -.03em; }
  & small { color: var(--apv-music-mute); }
  &:hover { background: var(--apv-music-wash); }
}

/* ── covers: pure gradients, coloured by --c1..--c3 ── */
.apv-music .apv-music-cover {
  position: relative; display: block; aspect-ratio: 1; border-radius: 6px; overflow: hidden; background: var(--c1);
  container-type: inline-size;
  & > span { position: absolute; inset: auto 9% 8% 9%; display: grid; gap: 2px; color: var(--c4, var(--c3)); line-height: 1; pointer-events: none; }
  & > span b { font-size: 10.5cqi; font-weight: 800; letter-spacing: -.04em; text-transform: none; text-wrap: balance; }
  & > span i { font-style: normal; font-size: 5.6cqi; font-weight: 650; letter-spacing: .16em; text-transform: uppercase; opacity: .85; }
  &.is-sm > span { display: none; }
  &[data-art="sun"] > span { inset: 8% 9% auto 9%; }
  &[data-art="sun"] {
    background:
      repeating-linear-gradient(180deg, var(--c2) 0 2.2%, transparent 2.2% 5.4%) bottom / 100% 38% no-repeat,
      radial-gradient(circle at 50% 63%, var(--c3) 0 19%, transparent 19.6%),
      linear-gradient(var(--c1) 30%, color-mix(in oklch, var(--c1), var(--c3) 30%));
  }
  &[data-art="orbit"] {
    background:
      radial-gradient(circle at 72% 30%, var(--c3) 0 9%, transparent 9.6%),
      repeating-radial-gradient(circle at 72% 30%, transparent 0 6%, color-mix(in oklch, var(--c2) 70%, transparent) 6% 6.8%),
      radial-gradient(circle at 72% 30%, var(--c2) 0, var(--c1) 70%);
  }
  &[data-art="split"] {
    background:
      radial-gradient(circle at 74% 24%, var(--c3) 0 7.5%, transparent 8%),
      linear-gradient(176deg, transparent 0 58%, var(--c3) 58% 58.8%, transparent 58.8%),
      linear-gradient(176deg, var(--c1) 0 58%, var(--c2) 58% 100%);
  }
  &[data-art="conic"] {
    background:
      radial-gradient(circle at 34% 40%, var(--c1) 0 8%, transparent 8.5%),
      conic-gradient(from var(--apv-music-spin) at 34% 40%, var(--c1), var(--c2) 25%, var(--c3) 50%, var(--c2) 75%, var(--c1));
  }
  &[data-art="grid"] {
    background:
      linear-gradient(90deg, color-mix(in oklch, var(--c3) 60%, transparent) 0 1px, transparent 1px) 0 0 / 20% 100%,
      repeating-radial-gradient(ellipse 120% 80% at 30% 38%, transparent 0 4.6%, var(--c2) 4.6% 5.3%),
      var(--c1);
  }
  &[data-art="wave"] {
    background:
      radial-gradient(ellipse 80% 40% at 50% 110%, var(--c3), transparent 70%),
      repeating-linear-gradient(98deg, var(--c1) 0 3.2%, var(--c2) 3.2% 3.8%);
  }
}
.apv-music .apv-music-mosaic { display: grid; grid-template-columns: 1fr 1fr; aspect-ratio: 1; border-radius: 6px; overflow: hidden;
  & .apv-music-cover { border-radius: 0; }
}

/* ── queue / now playing ── */
.apv-music .apv-music-queue {
  grid-area: queue; min-height: 0; min-width: 0; display: grid; grid-template-rows: auto auto minmax(0, 1fr) auto; overflow: hidden;
  background: linear-gradient(180deg, var(--apv-music-wash), var(--apv-music-paper) 70%);
  border-left: 1px solid var(--apv-music-line);
}
.apv-music .apv-music-np { padding: 18px 18px 10px; min-width: 260px; }
.apv-music .apv-music-art {
  position: relative; border-radius: 8px; width: min(100%, 212px); margin: 0 auto;
  box-shadow: 0 26px 46px -24px color-mix(in oklch, var(--apv-music-tint) 70%, var(--apv-music-ink)), 0 0 0 1px var(--apv-music-line);
  animation: apv-music-beat var(--apv-music-beat, .5s) linear infinite paused;
  & .apv-music-cover { border-radius: 8px; animation: apv-music-spin 28s linear infinite paused; }
  & .apv-music-cover::after {
    content: ""; position: absolute; inset: 0; mix-blend-mode: soft-light; pointer-events: none;
    background: conic-gradient(from calc(var(--apv-music-spin) * 3) at 50% 50%, transparent 0 18%, oklch(1 0 0 / .5) 24%, transparent 31% 68%, oklch(1 0 0 / .35) 74%, transparent 81%);
  }
}
.apv-music[data-playing="true"] .apv-music-art, .apv-music[data-playing="true"] .apv-music-art .apv-music-cover { animation-play-state: running; }
.apv-music .apv-music-npm {
  display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 2px 8px; margin-top: 14px; align-items: center;
  & small { grid-column: 1 / -1; font-size: 10px; font-weight: 700; letter-spacing: .14em; text-transform: uppercase; color: var(--apv-music-deep); font-variant-numeric: tabular-nums; }
  & b { font-size: 17px; font-weight: 780; letter-spacing: -.03em; line-height: 1.15; text-wrap: balance; }
  & button.apv-music-link { grid-column: 1; text-align: left; color: var(--apv-music-mute); font-size: 13px; }
  & button.apv-music-link:hover { color: var(--apv-music-ink); text-decoration: underline; text-underline-offset: 3px; }
  & .apv-music-heart { grid-row: 2 / 4; grid-column: 2; }
}
.apv-music .apv-music-npseek { display: none; }
.apv-music .apv-music-qhead {
  display: flex; align-items: baseline; gap: 8px; padding: 10px 18px 6px; min-width: 260px;
  & h3 { font-size: 10.5px; font-weight: 750; letter-spacing: .14em; text-transform: uppercase; }
  & span { font-size: 11.5px; color: var(--apv-music-mute); font-variant-numeric: tabular-nums; }
  & button { margin-left: auto; font-size: 12px; font-weight: 600; color: var(--apv-music-mute); padding: 2px 6px; border-radius: 6px; }
  & button:hover { color: var(--apv-music-ink); background: var(--apv-music-line); }
  & button:disabled { opacity: .4; pointer-events: none; }
}
.apv-music .apv-music-qlist { min-height: 0; overflow: auto; padding: 2px 10px 10px; scrollbar-width: thin; scrollbar-color: var(--apv-music-line2) transparent; min-width: 260px; overscroll-behavior: contain; }
.apv-music .apv-music-q {
  display: grid; grid-template-columns: 18px 36px minmax(0, 1fr) auto 26px; align-items: center; gap: 9px; padding: 6px 6px; border-radius: 8px; position: relative; touch-action: none;
  background: transparent; transition: background .18s, box-shadow .2s;
  & .apv-music-grip { color: var(--apv-music-faint); cursor: grab; display: grid; place-items: center; height: 30px; }
  & .apv-music-grip svg { width: 14px; height: 14px; }
  & .apv-music-cover { width: 36px; border-radius: 4px; }
  & span { display: grid; min-width: 0; }
  & b { font-weight: 600; font-size: 12.5px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
  & small { font-size: 11.5px; color: var(--apv-music-mute); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
  & time { font: 500 11px ui-monospace, Menlo, monospace; font-variant-numeric: tabular-nums; color: var(--apv-music-faint); }
  & .apv-music-rm { display: grid; place-items: center; width: 26px; height: 26px; border-radius: 50%; color: var(--apv-music-faint); opacity: 0; transition: opacity .15s, background .15s; }
  & .apv-music-rm svg { width: 14px; height: 14px; }
  & .apv-music-rm:hover { background: var(--apv-music-line); color: var(--apv-music-ink); }
  &:hover, &:focus-visible { background: color-mix(in oklch, var(--apv-music-card) 80%, transparent); box-shadow: 0 0 0 1px var(--apv-music-line); }
  &:hover .apv-music-rm, &:focus-within .apv-music-rm { opacity: 1; }
  &:focus-visible { outline-offset: 0; }
  &.is-drag { z-index: 2; background: var(--apv-music-card); box-shadow: 0 14px 30px -12px color-mix(in oklch, var(--apv-music-ink) 50%, transparent), 0 0 0 1px var(--apv-music-line2); cursor: grabbing; }
  &.is-drag .apv-music-grip { cursor: grabbing; color: var(--apv-music-deep); }
}
.apv-music .apv-music-qempty { padding: 20px 10px; color: var(--apv-music-mute); text-align: center; font-size: 12.5px; text-wrap: balance; }
.apv-music .apv-music-qhint { padding: 8px 18px 12px; font-size: 11px; color: var(--apv-music-faint); min-width: 260px; border-top: 1px solid var(--apv-music-line);
  & kbd { font-size: 9px; padding: 1px 4px; min-width: 0; }
}

/* ── player bar ── */
.apv-music .apv-music-bar {
  grid-area: bar; position: relative; display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1.5fr) minmax(0, 1fr); align-items: center; gap: 16px;
  padding: 10px 18px; border-top: 1px solid var(--apv-music-line); background: color-mix(in oklch, var(--apv-music-card) 85%, var(--apv-music-wash));
}
.apv-music .apv-music-now { display: flex; align-items: center; gap: 6px; min-width: 0; }
.apv-music .apv-music-nowopen {
  display: flex; align-items: center; gap: 11px; min-width: 0; text-align: left; border-radius: 8px; padding: 2px;
  & .apv-music-cover { width: 46px; border-radius: 5px; box-shadow: 0 0 0 1px var(--apv-music-line); }
  & .apv-music-nowtxt { display: grid; min-width: 0; }
  & b { font-weight: 650; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
  & small { color: var(--apv-music-mute); font-size: 12px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
}
.apv-music .apv-music-transport { display: grid; gap: 4px; justify-items: center; }
.apv-music .apv-music-btns {
  display: flex; align-items: center; gap: 6px;
  & > button { position: relative; display: grid; place-items: center; width: 34px; height: 34px; border-radius: 50%; color: var(--apv-music-mute); transition: color .2s, background .2s, transform .35s var(--apv-music-spring); }
  & > button:hover { color: var(--apv-music-ink); background: var(--apv-music-line); }
  & > button:active { transform: scale(.9); }
  & .apv-music-tog[aria-pressed="true"] { color: var(--apv-music-deep); }
  & .apv-music-tog[aria-pressed="true"]::after { content: ""; position: absolute; bottom: 2px; width: 4px; height: 4px; border-radius: 50%; background: currentColor; }
  & .apv-music-tog i { position: absolute; top: 6px; right: 5px; font: 800 8px/1 system-ui; font-style: normal; opacity: 0; transform: scale(.4); transition: opacity .2s, transform .35s var(--apv-music-spring); }
  & .apv-music-tog[data-mode="one"] i { opacity: 1; transform: none; }
}
.apv-music .apv-music-btns > .apv-music-play {
  width: 40px; height: 40px; background: var(--apv-music-ink); color: var(--apv-music-paper);
  & svg { position: absolute; width: 20px; height: 20px; transition: opacity .2s, transform .4s var(--apv-music-spring); }
  & .apv-music-ipa { opacity: 0; transform: scale(.5) rotate(-30deg); }
  &:hover { transform: scale(1.06); background: var(--apv-music-deep); color: var(--apv-music-paper); }
}
.apv-music[data-playing="true"] .apv-music-play {
  & .apv-music-ip { opacity: 0; transform: scale(.5) rotate(30deg); }
  & .apv-music-ipa { opacity: 1; transform: none; }
}
.apv-music .apv-music-seek {
  display: grid; grid-template-columns: 40px minmax(0, 1fr) 44px; align-items: center; gap: 8px; width: 100%; max-width: 520px;
  & output { font: 500 11px ui-monospace, Menlo, monospace; font-variant-numeric: tabular-nums; color: var(--apv-music-mute); }
  & output:first-child { text-align: right; }
}
.apv-music input[type="range"] {
  --p: 0%;
  -webkit-appearance: none; appearance: none; width: 100%; height: 16px; margin: 0; background: transparent; cursor: pointer;
  &::-webkit-slider-runnable-track { height: 4px; border-radius: 4px; background: linear-gradient(90deg, var(--apv-music-deep) var(--p), var(--apv-music-line2) var(--p)); }
  &::-moz-range-track { height: 4px; border-radius: 4px; background: linear-gradient(90deg, var(--apv-music-deep) var(--p), var(--apv-music-line2) var(--p)); }
  &::-webkit-slider-thumb { -webkit-appearance: none; width: 12px; height: 12px; margin-top: -4px; border-radius: 50%; background: var(--apv-music-deep); border: 2px solid var(--apv-music-paper); box-shadow: 0 1px 3px var(--apv-music-line2); transform: scale(0); transition: transform .25s var(--apv-music-spring); }
  &::-moz-range-thumb { width: 12px; height: 12px; border-radius: 50%; background: var(--apv-music-deep); border: 2px solid var(--apv-music-paper); transform: scale(0); transition: transform .25s var(--apv-music-spring); }
  &:hover::-webkit-slider-thumb, &:focus-visible::-webkit-slider-thumb, &:active::-webkit-slider-thumb { transform: scale(1); }
  &:hover::-moz-range-thumb, &:focus-visible::-moz-range-thumb { transform: scale(1); }
  &:focus-visible { outline: none; }
  &:focus-visible::-webkit-slider-runnable-track { box-shadow: 0 0 0 3px color-mix(in oklch, var(--apv-music-tint) 30%, transparent); }
}
.apv-music .apv-music-extra {
  display: flex; align-items: center; justify-content: end; gap: 6px;
  & input { width: min(110px, 9cqi); }
  & button { display: grid; place-items: center; width: 34px; height: 34px; border-radius: 50%; color: var(--apv-music-mute); position: relative; transition: color .2s, background .2s; }
  & button:hover { color: var(--apv-music-ink); background: var(--apv-music-line); }
  & .apv-music-tog[aria-pressed="true"] { color: var(--apv-music-deep); }
  & .apv-music-x { display: none; }
  & [aria-pressed="true"] .apv-music-x { display: inline; }
  & [aria-pressed="true"] .apv-music-w1, & [aria-pressed="true"] .apv-music-w2, & .apv-music-quiet .apv-music-w2 { display: none; }
}
.apv-music .apv-music-tabs { display: none; }

/* ── toast & sheet ── */
.apv-music .apv-music-toast {
  position: absolute; left: 50%; bottom: 92px; z-index: 30; display: flex; align-items: center; gap: 14px; padding: 9px 9px 9px 16px; border-radius: 12px;
  background: var(--apv-music-ink); color: var(--apv-music-paper); box-shadow: 0 16px 40px -14px var(--apv-music-ink); font-size: 12.5px;
  translate: -50% 0; opacity: 0; transform: translateY(14px) scale(.96); pointer-events: none;
  transition: opacity .25s, transform .45s var(--apv-music-spring);
  & button { padding: 5px 10px; border-radius: 7px; font-weight: 700; color: color-mix(in oklch, var(--apv-music-tint) 55%, white); background: color-mix(in oklch, var(--apv-music-paper) 10%, transparent); display: flex; align-items: center; gap: 6px; }
  & kbd { background: transparent; color: inherit; border-color: color-mix(in oklch, var(--apv-music-paper) 30%, transparent); }
  &.is-on { opacity: 1; transform: none; pointer-events: auto; }
}
.apv-music .apv-music-sheet {
  position: absolute; inset: 0; z-index: 40; display: grid; place-items: center; padding: 16px; background: color-mix(in oklch, var(--apv-music-ink) 30%, transparent);
  opacity: 1; transition: opacity .25s, display .25s allow-discrete;
  @starting-style { opacity: 0; }
  &[hidden] { display: none; opacity: 0; }
}
.apv-music .apv-music-sheetbox {
  width: min(380px, 100%); border-radius: 14px; background: var(--apv-music-card); box-shadow: 0 30px 70px -20px var(--apv-music-ink); padding: 16px 18px 18px;
  transition: transform .45s var(--apv-music-spring);
  @starting-style { transform: translateY(12px) scale(.96); }
  & header { display: flex; align-items: center; margin-bottom: 10px; }
  & h3 { flex: 1; font-size: 15px; font-weight: 750; letter-spacing: -.02em; }
  & header button { display: grid; place-items: center; width: 30px; height: 30px; border-radius: 50%; }
  & header button:hover { background: var(--apv-music-line); }
  & dl { display: grid; gap: 2px; }
  & dl div { display: grid; grid-template-columns: 96px 1fr; align-items: center; padding: 6px 0; border-top: 1px solid var(--apv-music-line); }
  & dd { color: var(--apv-music-mute); }
}

/* ── mid width: queue becomes a drawer ── */
@container (max-width: 959px) {
  .apv-music .apv-music-app, .apv-music[data-queue="closed"] .apv-music-app { grid-template-columns: 188px minmax(0, 1fr); grid-template-areas: "side main" "bar bar"; }
  .apv-music .apv-music-queue {
    position: absolute; z-index: 20; top: 10px; right: 10px; bottom: 86px; width: min(320px, 70cqi); border: 0; border-radius: 14px;
    box-shadow: 0 30px 60px -20px color-mix(in oklch, var(--apv-music-ink) 60%, transparent), 0 0 0 1px var(--apv-music-line2);
    background: linear-gradient(180deg, var(--apv-music-wash), var(--apv-music-paper) 60%);
    transition: transform .5s var(--apv-music-spring), opacity .25s, visibility 0s;
  }
  .apv-music[data-queue="closed"] .apv-music-queue { transform: translateX(30px); opacity: 0; visibility: hidden; transition: transform .3s var(--apv-music-ease), opacity .2s, visibility 0s .3s; }
  .apv-music .apv-music-art { width: 160px; }
  .apv-music .apv-music-extra input { display: none; }
  .apv-music .apv-music-bar { grid-template-columns: minmax(0, 1fr) auto minmax(0, .5fr); }
}

/* ── narrow: one pane at a time, tab bar, mini player ── */
@container (max-width: 759px) {
  .apv-music .apv-music-app, .apv-music[data-queue="closed"] .apv-music-app {
    grid-template-columns: minmax(0, 1fr); grid-template-rows: auto minmax(0, 1fr) auto auto;
    grid-template-areas: "side" "main" "bar" "tabs";
  }
  .apv-music .apv-music-side { flex-direction: row; align-items: center; gap: 4px; padding: 10px 12px 6px; border: 0; overflow-x: auto; }
  .apv-music .apv-music-brand, .apv-music .apv-music-keybtn, .apv-music .apv-music-nav h4 { display: none; }
  .apv-music .apv-music-nav { display: flex; gap: 6px; }
  .apv-music .apv-music-nav button { width: auto; flex: none; padding: 6px 12px; border-radius: 999px; border: 1px solid var(--apv-music-line2); font-size: 12.5px; }
  .apv-music .apv-music-nav button svg, .apv-music .apv-music-nav button .apv-music-cover, .apv-music .apv-music-nav button output { display: none; }
  .apv-music .apv-music-nav button[aria-current="page"] { background: var(--apv-music-ink); color: var(--apv-music-paper); box-shadow: none; border-color: transparent; }
  .apv-music .apv-music-top { padding: 6px 14px 8px; }
  .apv-music .apv-music-search { max-width: none; }
  .apv-music .apv-music-search kbd { display: none; }
  .apv-music .apv-music-scroll { padding: 2px 14px 20px; }
  .apv-music .apv-music-head { flex-direction: column; align-items: start; gap: 14px; }
  .apv-music .apv-music-list, .apv-music .apv-music-list.no-album { grid-template-columns: 24px minmax(0, 1fr) 44px 30px; column-gap: 8px; }
  .apv-music .apv-music-list .apv-music-al, .apv-music .apv-music-lh .apv-music-alh { display: none; }
  .apv-music .apv-music-grid { grid-template-columns: repeat(auto-fill, minmax(124px, 1fr)); gap: 16px 12px; }

  .apv-music[data-queue] .apv-music-queue {
    position: static; grid-area: side / side / main / main; width: auto; border-radius: 0; box-shadow: none; transform: none; opacity: 1; visibility: visible;
    grid-template-rows: auto auto minmax(0, 1fr) auto; display: none;
  }
  .apv-music[data-pane="queue"] .apv-music-queue { display: grid; animation: apv-music-up .5s var(--apv-music-spring) both; }
  .apv-music[data-pane="queue"] .apv-music-side, .apv-music[data-pane="queue"] .apv-music-main { display: none; }
  .apv-music .apv-music-np { display: grid; gap: 12px; padding: 16px 18px 6px; }
  .apv-music .apv-music-art { width: min(64cqi, 260px); }
  .apv-music .apv-music-npm { margin-top: 0; }
  .apv-music .apv-music-qhint { display: none; }
  .apv-music .apv-music-q .apv-music-rm { opacity: 1; }

  .apv-music .apv-music-bar { grid-template-columns: minmax(0, 1fr) auto; gap: 8px; padding: 8px 10px 8px 12px; }
  .apv-music .apv-music-bar::before { content: ""; position: absolute; left: 0; top: -1px; height: 2px; width: var(--p, 0%); background: var(--apv-music-deep); }
  .apv-music .apv-music-nowopen .apv-music-cover { width: 40px; }
  .apv-music .apv-music-now .apv-music-heart { display: none; }
  .apv-music .apv-music-seek, .apv-music .apv-music-extra, .apv-music .apv-music-btns .apv-music-tog, .apv-music .apv-music-btns [data-act="prev"] { display: none; }
  .apv-music[data-pane="queue"] .apv-music-bar { grid-template-columns: minmax(0, 1fr); padding: 4px 14px 10px; }
  .apv-music[data-pane="queue"] .apv-music-bar::before, .apv-music[data-pane="queue"] .apv-music-now { display: none; }
  .apv-music[data-pane="queue"] .apv-music-seek, .apv-music[data-pane="queue"] .apv-music-btns .apv-music-tog, .apv-music[data-pane="queue"] .apv-music-btns [data-act="prev"] { display: grid; }
  .apv-music .apv-music-tabs {
    grid-area: tabs; display: grid; grid-template-columns: repeat(3, 1fr); border-top: 1px solid var(--apv-music-line); background: var(--apv-music-card);
    & button { display: grid; justify-items: center; gap: 2px; padding: 7px 0 9px; font-size: 10.5px; font-weight: 650; color: var(--apv-music-faint); }
    & button[aria-current="page"] { color: var(--apv-music-deep); }
    & svg { width: 20px; height: 20px; }
  }
  .apv-music .apv-music-toast { bottom: 128px; max-width: calc(100% - 24px); }
}

@keyframes apv-music-in { from { opacity: 0; transform: translateY(8px); } }
@keyframes apv-music-rise { from { opacity: 0; transform: translateY(10px); } }
@keyframes apv-music-up { from { opacity: 0; transform: translateY(24px); } }
@keyframes apv-music-spin { to { --apv-music-spin: 360deg; } }
@keyframes apv-music-beat { 0% { transform: scale(1.016); } 22%, 100% { transform: scale(1); } }
@keyframes apv-music-eq { 0% { transform: scaleY(.25); } 100% { transform: scaleY(1); } }
@keyframes apv-music-pop { 0% { transform: scale(1); } 40% { transform: scale(1.35); } 100% { transform: scale(1); } }

@media (prefers-reduced-motion: reduce) {
  .apv-music, .apv-music .apv-music-app { transition: none; }
  .apv-music .apv-music-view, .apv-music .apv-music-alb, .apv-music .apv-music-row, .apv-music[data-pane="queue"] .apv-music-queue { animation: none; }
  .apv-music .apv-music-art, .apv-music .apv-music-art .apv-music-cover { animation: none; }
  .apv-music .apv-music-eq i { animation: none; transform: scaleY(.6); }
  .apv-music .apv-music-eq i:nth-child(2) { transform: scaleY(1); }
  .apv-music .apv-music-heart[aria-pressed="true"] svg { animation: none; }
  .apv-music .apv-music-toast, .apv-music .apv-music-queue, .apv-music .apv-music-sheetbox { transition: opacity .2s; transform: none; }
  .apv-music .apv-music-toast:not(.is-on) { transform: none; }
}

