/* Loam music. State lives in S; render*() rebuilds a region from it.
   The playback clock is a rAF loop that only runs while playing, on screen
   and in a visible tab; it measures real elapsed time, so coming back to a
   hidden tab lands exactly where real audio would be. */
const doc = root.ownerDocument;
const $ = (s, el = root) => el.querySelector(s);
const $$ = (s, el = root) => [...el.querySelectorAll(s)];
const RM = matchMedia('(prefers-reduced-motion: reduce)');
const SPRING = 'linear(0, 0.1 4%, 0.38 10%, 0.74 17%, 0.96 24%, 1.04 30%, 1.05 35%, 1.02 44%, 1 55%, 1)';
const EASE = 'cubic-bezier(.2,.8,.2,1)';
const esc = s => String(s == null ? '' : s).replace(/[&<>"']/g, c => '&#' + c.charCodeAt(0) + ';');
const clamp = (v, a, b) => Math.min(b, Math.max(a, v));
const fmt = s => { s = Math.max(0, Math.floor(s)); return Math.floor(s / 60) + ':' + String(s % 60).padStart(2, '0'); };
const long = s => { const t = Math.round(s / 60), h = Math.floor(t / 60), m = t % 60; return h ? h + ' hr ' + m + ' min' : m + ' min'; };
const plural = (n, w) => n + ' ' + w + (n === 1 ? '' : 's');

const ICON = {
  play: '<path class="apv-music-fill" d="M8.5 5.8v12.4L18.6 12z"/>',
  shuffle: '<path d="M4 7h3.5c4.5 0 4.5 10 9 10H20M4 17h3.5c1.6 0 2.5-1.3 3.3-3M14.2 10c.8-1.7 1.7-3 3.3-3H20M17.5 4.5 20 7l-2.5 2.5M17.5 14.5 20 17l-2.5 2.5"/>',
  heart: '<path d="M12 19.5s-7.5-4.4-7.5-10A4.2 4.2 0 0 1 12 7.3a4.2 4.2 0 0 1 7.5 2.2c0 5.6-7.5 10-7.5 10Z"/>',
  albums: '<rect x="4" y="4" width="16" height="16" rx="2.5"/><circle cx="12" cy="12" r="4"/><circle cx="12" cy="12" r=".6"/>',
  songs: '<path d="M9 18V6l10-2v12"/><circle cx="6.5" cy="18" r="2.5"/><circle cx="16.5" cy="16" r="2.5"/>',
  grip: '<path d="M9 6h.01M15 6h.01M9 12h.01M15 12h.01M9 18h.01M15 18h.01" stroke-width="2.6"/>',
  x: '<path d="M6 6l12 12M18 6 6 18"/>',
  sort: '<path d="m6 14 6-6 6 6"/>',
