const svg = k => '<svg viewBox="0 0 24 24" aria-hidden="true">' + ICON[k] + '</svg>';

/* ── catalogue: album totals are always summed from their tracks ── */
const ALBUMS = [
  { id: 'salt', title: 'Salt Year', artist: 'Wren Halloway', year: 2024, genre: 'Folk', bpm: 92, art: 'sun',
    c: ['oklch(0.9 0.05 82)', 'oklch(0.42 0.07 235)', 'oklch(0.66 0.17 42)', 'oklch(0.3 0.06 240)'], tint: 'oklch(0.62 0.16 42)',
    tracks: [['Tidewater', 214], ['A Coat for March', 187], ['Salt Year', 246], ['Lanterns on the Weir', 201], ['Kittiwake', 158], ['Gorse Fire', 233], ['The Long Field', 312]] },
  { id: 'orbit', title: 'Low Orbit Choir', artist: 'Teodor Vass', year: 2025, genre: 'Ambient', bpm: 64, art: 'orbit',
    c: ['oklch(0.26 0.05 255)', 'oklch(0.5 0.09 230)', 'oklch(0.9 0.08 95)', 'oklch(0.93 0.03 95)'], tint: 'oklch(0.5 0.1 240)',
    tracks: [['Perigee', 402], ['Cloud Chamber', 356], ['Slow Telemetry', 488], ['Apogee', 371], ['Re-entry Hymn', 529]] },
