    case 'play': setPlaying(!S.playing); break;
    case 'next': next(false); break;
    case 'prev': prev(); break;
    case 'shuffle': toggleShuffle(); break;
    case 'repeat': cycleRepeat(); break;
    case 'mute': S.muted = !S.muted; renderBar(); break;
    case 'queue': setQueueOpen(root.dataset.queue !== 'open'); break;
    case 'like-cur': like(S.cur); break;
    case 'clear': { const old = S.queue.slice(); S.queue = []; renderQueue(true); toast('Cleared ' + plural(old.length, 'song') + ' from up next', () => { S.queue = old; renderQueue(true); }); break; }
