root.addEventListener('dblclick', e => { const r = e.target.closest('.apv-music-q'); if (r) { const id = r.dataset.key, i = S.queue.indexOf(id); S.history.push(S.cur, ...S.queue.slice(0, i)); S.queue = S.queue.slice(i + 1); S.cur = id; S.pos = 0; setPlaying(true); trackChanged(true); } });

const seek = $('[data-seek]');
seek.addEventListener('input', () => { scrubbing = true; S.pos = +seek.value; seek.style.setProperty('--p', (S.pos / TR[S.cur].dur * 100) + '%'); progress(true); });
seek.addEventListener('change', () => { scrubbing = false; S.pos = +seek.value; last = performance.now(); progress(true); });
