css:
/* Northlight: a 10-foot UI that also works at a desk. Spatial focus moves
   between native scrollers; the backdrop is the focused title's own key art. */
.apv-stream {
  /* re-theme: bg, ink, accent */
  --apv-stream-bg: oklch(0.155 0.01 55);
  --apv-stream-ink: oklch(0.95 0.012 80);
  --apv-stream-accent: oklch(0.73 0.16 50);
  --apv-stream-panel: color-mix(in oklch, var(--apv-stream-bg) 90%, var(--apv-stream-ink));
  --apv-stream-raise: color-mix(in oklch, var(--apv-stream-bg) 82%, var(--apv-stream-ink));
  --apv-stream-line: color-mix(in oklch, var(--apv-stream-ink) 12%, transparent);
  --apv-stream-mute: color-mix(in oklch, var(--apv-stream-ink) 66%, var(--apv-stream-bg));
  --apv-stream-faint: color-mix(in oklch, var(--apv-stream-ink) 42%, var(--apv-stream-bg));
  --apv-stream-ease: cubic-bezier(.22, .9, .24, 1);
  --apv-stream-spring: linear(0, 0.12 4%, 0.42 10%, 0.79 17%, 1 24%, 1.06 30%, 1.05 36%, 1.01 46%, 0.998 58%, 1);
  --apv-stream-pad: clamp(16px, 2.6cqi, 32px);

  position: relative; width: 100%; height: var(--apv-stream-h, 680px);
  container-type: inline-size; overflow: clip; isolation: isolate; box-sizing: border-box;
  background: var(--apv-stream-bg); color: var(--apv-stream-ink); color-scheme: dark; accent-color: var(--apv-stream-accent);
  border-radius: 14px; font: 13px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-tap-highlight-color: transparent;

  & *, & *::before, & *::after { box-sizing: border-box; }
  &:focus { outline: none; }
  & :focus-visible { outline: 2px solid var(--apv-stream-ink); outline-offset: 3px; }
  & button, & input, & select { font: inherit; color: inherit; }
  & button { cursor: pointer; background: none; border: 0; padding: 0; }
  & h2, & h3, & p, & ol, & ul { margin: 0; padding: 0; }
  & ol, & ul { list-style: none; }
  & svg { width: 20px; height: 20px; fill: none; stroke: currentColor; stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; flex: none; }
  & svg text { fill: currentColor; stroke: none; font: 700 6.5px system-ui; }
  & .apv-stream-fill { fill: currentColor; stroke: none; }
  & kbd { font: 600 10px/1 ui-monospace, Menlo, monospace; padding: 3px 5px; min-width: 18px; display: inline-block; text-align: center; border-radius: 4px; background: color-mix(in oklch, var(--apv-stream-ink) 14%, transparent); color: var(--apv-stream-ink); }
  & mark { background: color-mix(in oklch, var(--apv-stream-accent) 40%, transparent); color: inherit; border-radius: 2px; }
}

.apv-stream .apv-stream-app {
  height: 100%; display: grid; grid-template-columns: 72px minmax(0, 1fr); grid-template-rows: minmax(0, 1fr);
  grid-template-areas: "rail main";
}

/* ── rail ── */
.apv-stream .apv-stream-rail {
  grid-area: rail; z-index: 3; display: flex; flex-direction: column; align-items: center; gap: 6px; padding: 18px 0 16px;
  background: linear-gradient(90deg, color-mix(in oklch, var(--apv-stream-bg) 92%, transparent), transparent);
  & .apv-stream-logo { display: grid; place-items: center; width: 40px; height: 40px; margin-bottom: 18px; border-radius: 11px; background: var(--apv-stream-accent); color: var(--apv-stream-bg); }
  & .apv-stream-logo svg { width: 20px; height: 20px; stroke-width: 2.6; }
  & button { position: relative; display: grid; justify-items: center; gap: 3px; width: 60px; padding: 8px 0; border-radius: 10px; color: var(--apv-stream-faint); font-size: 10px; font-weight: 600; letter-spacing: .02em; transition: color .2s, background .2s; }
  & button:hover { color: var(--apv-stream-ink); background: var(--apv-stream-line); }
  & button[aria-current="page"] { color: var(--apv-stream-ink); }
  & button[aria-current="page"]::before { content: ""; position: absolute; left: -6px; top: 12px; bottom: 12px; width: 3px; border-radius: 3px; background: var(--apv-stream-accent); }
  & .apv-stream-me { margin-top: auto; display: grid; place-items: center; width: 34px; height: 34px; border-radius: 9px; font-size: 11px; font-weight: 800; background: oklch(0.6 0.1 160); color: oklch(0.18 0.03 160); }
}

/* ── main ── */
.apv-stream .apv-stream-main {
  grid-area: main; position: relative; min-width: 0; min-height: 0; display: grid;
  grid-template-rows: minmax(0, 48%) auto minmax(0, 1fr); grid-template-areas: "hero" "search" "rows";
  transition: grid-template-rows .55s var(--apv-stream-ease);
}
.apv-stream:not([data-view="home"]) .apv-stream-main { grid-template-rows: 0fr auto minmax(0, 1fr); }
.apv-stream .apv-stream-backdrop {
  position: absolute; inset: 0 0 auto 0; height: 86%; z-index: 0; pointer-events: none; transition: opacity .6s, filter .6s;
  & canvas { position: absolute; inset: 0; width: 100%; height: 100%; display: block; opacity: 0; transition: opacity .9s var(--apv-stream-ease); }
  & canvas.is-on { opacity: 1; }
}
.apv-stream:not([data-view="home"]) .apv-stream-backdrop { opacity: .35; filter: blur(18px) saturate(1.2); }
.apv-stream .apv-stream-shade {
  position: absolute; inset: 0;
  background:
    linear-gradient(90deg, var(--apv-stream-bg) 0, color-mix(in oklch, var(--apv-stream-bg) 72%, transparent) 30%, transparent 62%),
    linear-gradient(180deg, transparent 38%, color-mix(in oklch, var(--apv-stream-bg) 70%, transparent) 62%, var(--apv-stream-bg) 92%);
}
.apv-stream .apv-stream-hero { grid-area: hero; position: relative; z-index: 1; min-height: 0; overflow: hidden; display: grid; align-content: end; padding: 0 var(--apv-stream-pad) 6px; }
.apv-stream .apv-stream-info {
  max-width: min(520px, 62cqi); display: grid; gap: 9px; transition: opacity .3s, transform .45s var(--apv-stream-ease), filter .3s;
  &.is-out { opacity: 0; transform: translateY(8px); filter: blur(5px); }
  & p.apv-stream-syn { color: color-mix(in oklch, var(--apv-stream-ink) 82%, transparent); text-wrap: pretty; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; max-width: 54ch; font-size: 13.5px; }
}
.apv-stream .apv-stream-eye {
  display: flex; align-items: center; gap: 8px; font-size: 10.5px; font-weight: 750; letter-spacing: .18em; text-transform: uppercase; color: var(--apv-stream-mute);
  & b { display: grid; place-items: center; width: 18px; height: 18px; border-radius: 5px; background: var(--apv-stream-accent); color: var(--apv-stream-bg); font-size: 11px; letter-spacing: 0; }
}
.apv-stream .apv-stream-logo-t {
  display: block; font-size: clamp(30px, 4.6cqi, 54px); line-height: .95; text-wrap: balance; text-shadow: 0 2px 30px color-mix(in oklch, var(--apv-stream-bg) 60%, transparent);
  &[data-logo="wide"] { font-weight: 300; text-transform: uppercase; letter-spacing: .3em; font-size: clamp(22px, 3.2cqi, 38px); line-height: 1.15; }
  &[data-logo="heavy"] { font-weight: 900; letter-spacing: -.055em; }
  &[data-logo="serif"] { font-family: ui-serif, "New York", Georgia, serif; font-style: italic; font-weight: 500; letter-spacing: -.02em; }
  &[data-logo="mono"] { font-family: ui-monospace, Menlo, monospace; font-weight: 700; text-transform: uppercase; letter-spacing: .06em; font-size: clamp(22px, 3.4cqi, 40px); }
  &[data-logo="lower"] { font-weight: 250; text-transform: lowercase; letter-spacing: -.04em; }
