  &.is-round { width: 38px; padding: 0; justify-content: center; border-radius: 50%; border: 1.5px solid color-mix(in oklch, var(--apv-stream-ink) 45%, transparent); background: color-mix(in oklch, var(--apv-stream-bg) 40%, transparent); }
