  & label { display: flex; align-items: center; gap: 10px; height: 46px; padding: 0 14px; border-radius: 10px; background: color-mix(in oklch, var(--apv-stream-ink) 9%, transparent); box-shadow: inset 0 0 0 1px var(--apv-stream-line); }
  & label:focus-within { box-shadow: inset 0 0 0 2px var(--apv-stream-ink); }
  & input { flex: 1; min-width: 0; border: 0; outline: 0; background: none; font-size: 17px; font-weight: 600; letter-spacing: -.01em; }
