}
.apv-stream:not([data-view="home"]) .apv-stream-search { display: grid; }
.apv-stream:not([data-view="search"]) .apv-stream-search label { display: none; }
.apv-stream .apv-stream-chips {
  display: flex; gap: 6px; overflow-x: auto; scrollbar-width: none; padding: 2px;
  & button { flex: none; padding: 6px 13px; border-radius: 999px; font-size: 12px; font-weight: 650; color: var(--apv-stream-mute); box-shadow: inset 0 0 0 1px var(--apv-stream-line); transition: background .2s, color .2s; }
  & button:hover { color: var(--apv-stream-ink); background: var(--apv-stream-line); }
  & button[aria-checked="true"] { background: var(--apv-stream-ink); color: var(--apv-stream-bg); box-shadow: none; }
}

/* ── rows ── */
.apv-stream .apv-stream-rows {
  grid-area: rows; position: relative; z-index: 1; min-height: 0; overflow-y: auto; overflow-x: hidden; overscroll-behavior: contain; scrollbar-width: none;
  scroll-behavior: smooth; padding-bottom: 20px;
  mask-image: linear-gradient(180deg, transparent 0, #000 14px);
}
.apv-stream .apv-stream-row {
  position: relative; padding-top: 4px;
  animation: apv-stream-rise .6s var(--apv-stream-ease) both; animation-delay: calc(var(--i, 0) * 70ms);
  & h3 { display: flex; align-items: baseline; gap: 10px; padding: 0 var(--apv-stream-pad); font-size: 15px; font-weight: 750; letter-spacing: -.015em; }
  & h3 small { font-size: 11.5px; font-weight: 550; color: var(--apv-stream-faint); letter-spacing: 0; font-variant-numeric: tabular-nums; }
}
.apv-stream .apv-stream-track {
  position: relative; display: flex; gap: 10px; overflow-x: auto; overflow-y: hidden; scrollbar-width: none; scroll-behavior: smooth; overscroll-behavior-x: contain;
  padding: 12px var(--apv-stream-pad) 16px; scroll-padding-inline: var(--apv-stream-pad);
  &::-webkit-scrollbar { display: none; }
}
.apv-stream .apv-stream-page {
  position: absolute; top: 34px; bottom: 16px; width: var(--apv-stream-pad); z-index: 3; display: grid; place-items: center; opacity: 0; transition: opacity .2s, background .2s;
