}
.apv-stream .apv-stream-row:hover .apv-stream-page { opacity: 1; }

.apv-stream .apv-stream-card {
  --w: clamp(150px, 19cqi, 230px);
  position: relative; flex: none; width: var(--w); aspect-ratio: 16 / 9; border-radius: 7px; overflow: hidden; background: var(--apv-stream-panel); text-align: left;
