  transition: transform .5s var(--apv-stream-spring), box-shadow .3s;
  & canvas { position: absolute; inset: 0; width: 100%; height: 100%; display: block; }
  & .apv-stream-cl { position: absolute; left: 10px; right: 10px; bottom: 9px; font-size: clamp(13px, 1.5cqi, 17px); line-height: 1; text-shadow: 0 1px 12px oklch(0 0 0 / .6); pointer-events: none; }
  & .apv-stream-cl.apv-stream-logo-t[data-logo="wide"] { font-size: clamp(10px, 1cqi, 12px); }
  & .apv-stream-cl.apv-stream-logo-t[data-logo="mono"] { font-size: clamp(11px, 1.15cqi, 13px); }
  & .apv-stream-tag { position: absolute; top: 8px; left: 8px; padding: 2px 6px; border-radius: 4px; font-size: 9.5px; font-weight: 800; letter-spacing: .08em; text-transform: uppercase; background: var(--apv-stream-accent); color: var(--apv-stream-bg); }
  & .apv-stream-prog { position: absolute; left: 0; right: 0; bottom: 0; height: 3px; background: color-mix(in oklch, var(--apv-stream-ink) 22%, transparent); }
  & .apv-stream-prog i { display: block; height: 100%; width: var(--p); background: var(--apv-stream-accent); transition: width .6s var(--apv-stream-ease); }
  &:has(.apv-stream-prog) .apv-stream-cl { bottom: 26px; }
  & .apv-stream-left { position: absolute; left: 10px; bottom: 9px; font-size: 10.5px; font-weight: 650; color: color-mix(in oklch, var(--apv-stream-ink) 82%, transparent); font-variant-numeric: tabular-nums; text-shadow: 0 1px 8px oklch(0 0 0 / .7); }
  &:hover, &:focus-visible { transform: scale(1.06); z-index: 2; box-shadow: 0 0 0 2px var(--apv-stream-ink), 0 18px 34px -14px oklch(0 0 0 / .9); outline: none; }
  &.is-hero:not(:hover):not(:focus-visible)::after { content: ""; position: absolute; inset: 0; border-radius: inherit; box-shadow: inset 0 0 0 1.5px color-mix(in oklch, var(--apv-stream-ink) 40%, transparent); }
  &.is-p { --w: clamp(108px, 12.5cqi, 150px); aspect-ratio: 2 / 3; }
}
.apv-stream .apv-stream-top { display: flex; align-items: end; flex: none; scroll-snap-align: start;
  & > b { font-size: clamp(84px, 11cqi, 132px); line-height: .78; font-weight: 900; letter-spacing: -.09em; color: var(--apv-stream-bg); -webkit-text-stroke: 2px color-mix(in oklch, var(--apv-stream-ink) 55%, transparent); margin-right: -10px; font-variant-numeric: tabular-nums; }
}
.apv-stream .apv-stream-grid {
  display: grid; grid-template-columns: repeat(auto-fill, minmax(clamp(150px, 18cqi, 220px), 1fr)); gap: 18px 12px; padding: 12px var(--apv-stream-pad) 24px;
  & .apv-stream-card { width: auto; animation: apv-stream-rise .5s var(--apv-stream-ease) both; animation-delay: calc(min(var(--i, 0), 16) * 30ms); }
}
.apv-stream .apv-stream-empty { padding: 40px var(--apv-stream-pad); color: var(--apv-stream-mute); text-wrap: balance; max-width: 44ch;
  & b { display: block; color: var(--apv-stream-ink); font-size: 16px; margin-bottom: 4px; }
}

/* ── detail ── */
.apv-stream .apv-stream-detail {
  grid-area: main; z-index: 6; position: relative; min-height: 0; overflow-y: auto; overscroll-behavior: contain; scrollbar-width: thin; scrollbar-color: var(--apv-stream-line) transparent;
  background: var(--apv-stream-bg); opacity: 1; transform: none;
  transition: opacity .35s, transform .55s var(--apv-stream-ease), display .55s allow-discrete;
