  &[hidden] { display: none; opacity: 0; transform: translateY(10px); }
}
.apv-stream .apv-stream-dhero {
  position: relative; height: clamp(250px, 56%, 380px); display: grid; align-content: end; padding: 0 var(--apv-stream-pad) 18px;
  & canvas { position: absolute; inset: 0; width: 100%; height: 100%; display: block; }
  &::after { content: ""; position: absolute; inset: 0; background: linear-gradient(180deg, transparent 30%, var(--apv-stream-bg)), linear-gradient(90deg, color-mix(in oklch, var(--apv-stream-bg) 70%, transparent), transparent 60%); }
  & > div { position: relative; z-index: 1; display: grid; gap: 10px; max-width: 600px; }
  & .apv-stream-x { position: absolute; z-index: 2; top: 14px; right: 14px; display: flex; align-items: center; gap: 8px; height: 34px; padding: 0 8px 0 10px; border-radius: 999px; background: color-mix(in oklch, var(--apv-stream-bg) 60%, transparent); backdrop-filter: blur(8px); font-size: 12px; color: var(--apv-stream-mute); }
