}
.apv-stream .apv-stream-dbody { display: grid; grid-template-columns: minmax(0, 1.7fr) minmax(0, 1fr); gap: 28px; padding: 6px var(--apv-stream-pad) 30px;
  & .apv-stream-syn2 { font-size: 14px; line-height: 1.55; text-wrap: pretty; color: color-mix(in oklch, var(--apv-stream-ink) 88%, transparent); margin-bottom: 18px; }
  & dl { margin: 0; display: grid; gap: 8px; font-size: 12.5px; }
  & dt { display: inline; color: var(--apv-stream-faint); }
