.apv-stream .apv-stream-eps {
  & header { display: flex; align-items: center; gap: 12px; margin-bottom: 10px; }
  & h3 { font-size: 17px; font-weight: 750; letter-spacing: -.02em; flex: 1; }
  & select { appearance: none; padding: 7px 30px 7px 12px; border-radius: 7px; font-weight: 650; font-size: 12.5px; background-color: var(--apv-stream-panel); background-repeat: no-repeat; border: 1px solid var(--apv-stream-line); cursor: pointer;
    background-image: linear-gradient(45deg, transparent 50%, currentColor 50%), linear-gradient(135deg, currentColor 50%, transparent 50%);
    background-position: right 14px top 50%, right 9px top 50%; background-size: 5px 5px; }
}
.apv-stream .apv-stream-ep {
  display: grid; grid-template-columns: 28px 132px minmax(0, 1fr) auto; align-items: center; gap: 14px; width: 100%; padding: 12px 10px; border-radius: 8px; text-align: left; border-bottom: 1px solid var(--apv-stream-line);
  animation: apv-stream-rise .45s var(--apv-stream-ease) both; animation-delay: calc(var(--i, 0) * 40ms);
  transition: background .2s;
  & > b { font-size: 18px; font-weight: 300; color: var(--apv-stream-mute); text-align: center; font-variant-numeric: tabular-nums; }
  & .apv-stream-thumb { position: relative; aspect-ratio: 16 / 9; border-radius: 5px; overflow: hidden; background: var(--apv-stream-panel); }
  & .apv-stream-thumb canvas { position: absolute; inset: 0; width: 100%; height: 100%; }
  & .apv-stream-thumb svg { position: absolute; inset: 0; margin: auto; width: 26px; height: 26px; opacity: 0; transform: scale(.7); transition: opacity .2s, transform .35s var(--apv-stream-spring); filter: drop-shadow(0 1px 6px oklch(0 0 0 / .6)); }
  & .apv-stream-prog { position: absolute; left: 0; right: 0; bottom: 0; height: 3px; background: color-mix(in oklch, var(--apv-stream-ink) 25%, transparent); }
  & .apv-stream-prog i { display: block; height: 100%; width: var(--p); background: var(--apv-stream-accent); }
  & span b { display: block; font-weight: 650; }
  & span small { color: var(--apv-stream-mute); font-size: 12px; }
  & time { font-size: 12px; color: var(--apv-stream-mute); font-variant-numeric: tabular-nums; }
  &:hover, &:focus-visible { background: var(--apv-stream-panel); outline: none; }
  &:hover .apv-stream-thumb svg, &:focus-visible .apv-stream-thumb svg { opacity: 1; transform: none; }
  &[aria-current="true"] > b { color: var(--apv-stream-accent); font-weight: 700; }
}
.apv-stream .apv-stream-like { display: grid; grid-template-columns: repeat(auto-fill, minmax(150px, 1fr)); gap: 12px; margin-top: 10px;
  & .apv-stream-card { width: auto; }
}
.apv-stream .apv-stream-tags { display: flex; flex-wrap: wrap; gap: 6px; margin-top: 4px;
  & span { padding: 3px 9px; border-radius: 999px; font-size: 11.5px; box-shadow: inset 0 0 0 1px var(--apv-stream-line); color: var(--apv-stream-mute); }
}

/* ── player ── */
.apv-stream .apv-stream-player {
  grid-area: 1 / 1 / -1 / -1; z-index: 10; position: relative; overflow: hidden; background: oklch(0.06 0 0); cursor: none;
  opacity: 1; transition: opacity .4s, display .4s allow-discrete;
  @starting-style { opacity: 0; }
  &[hidden] { display: none; opacity: 0; }
  &.is-ui { cursor: default; }
  & canvas { position: absolute; inset: 0; width: 100%; height: 100%; display: block; }
}
.apv-stream .apv-stream-ptop, .apv-stream .apv-stream-pbar, .apv-stream .apv-stream-skip {
  transition: opacity .35s, transform .45s var(--apv-stream-ease);
}
.apv-stream .apv-stream-player:not(.is-ui) {
  & .apv-stream-ptop { opacity: 0; transform: translateY(-10px); }
  & .apv-stream-pbar { opacity: 0; transform: translateY(12px); }
}
.apv-stream .apv-stream-ptop {
  position: absolute; inset: 0 0 auto 0; display: flex; align-items: center; gap: 14px; padding: 16px 20px 40px;
  background: linear-gradient(oklch(0 0 0 / .7), transparent);
  & button { display: grid; place-items: center; width: 38px; height: 38px; border-radius: 50%; }
  & button:hover { background: oklch(1 0 0 / .14); }
  & div { display: grid; }
  & b { font-size: 15px; font-weight: 750; letter-spacing: -.01em; }
  & small { font-size: 12px; color: var(--apv-stream-mute); }
}
.apv-stream .apv-stream-pbar {
  position: absolute; inset: auto 0 0 0; display: grid; gap: 6px; padding: 40px 20px 14px; background: linear-gradient(transparent, oklch(0 0 0 / .78));
}
.apv-stream .apv-stream-scrub {
  display: grid; grid-template-columns: minmax(0, 1fr) auto; align-items: center; gap: 12px;
  & output { font: 600 12px ui-monospace, Menlo, monospace; font-variant-numeric: tabular-nums; color: var(--apv-stream-mute); }
  & input {
    --p: 0%; --b: 0%;
    -webkit-appearance: none; appearance: none; width: 100%; height: 18px; margin: 0; background: transparent; cursor: pointer;
    &::-webkit-slider-runnable-track { height: 4px; border-radius: 4px; background: linear-gradient(90deg, var(--apv-stream-accent) var(--p), oklch(1 0 0 / .4) var(--p) var(--b), oklch(1 0 0 / .18) var(--b)); transition: height .2s; }
    &::-moz-range-track { height: 4px; border-radius: 4px; background: linear-gradient(90deg, var(--apv-stream-accent) var(--p), oklch(1 0 0 / .4) var(--p) var(--b), oklch(1 0 0 / .18) var(--b)); }
    &::-webkit-slider-thumb { -webkit-appearance: none; width: 14px; height: 14px; margin-top: -5px; border-radius: 50%; background: var(--apv-stream-accent); border: 0; transition: transform .3s var(--apv-stream-spring); }
    &::-moz-range-thumb { width: 14px; height: 14px; border-radius: 50%; background: var(--apv-stream-accent); border: 0; }
    &:hover::-webkit-slider-thumb { transform: scale(1.25); }
    &:focus-visible { outline: none; }
    &:focus-visible::-webkit-slider-thumb { box-shadow: 0 0 0 4px oklch(1 0 0 / .3); }
  }
}
.apv-stream .apv-stream-pctl {
  display: flex; align-items: center; gap: 6px;
  & > button { display: grid; place-items: center; width: 40px; height: 40px; border-radius: 50%; transition: background .2s, transform .3s var(--apv-stream-spring); position: relative; }
  & > button:hover { background: oklch(1 0 0 / .14); transform: scale(1.08); }
  & > button svg { width: 24px; height: 24px; }
  & [data-act="pplay"] svg { position: absolute; transition: opacity .2s, transform .35s var(--apv-stream-spring); }
  & .apv-stream-ipl { opacity: 0; transform: scale(.6); }
  & [aria-pressed="true"] .apv-stream-won, & [aria-pressed="false"] .apv-stream-woff { display: none; }
  & [data-act="cc"][aria-pressed="false"] { opacity: .5; }
  & > button[aria-disabled="true"] { opacity: .35; cursor: not-allowed; }
  & > button[aria-disabled="true"]:hover { background: none; transform: none; }
  & .apv-stream-pname { flex: 1; text-align: center; font-size: 12.5px; color: var(--apv-stream-mute); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
}
.apv-stream .apv-stream-player.is-paused {
  & .apv-stream-ipl { opacity: 1; transform: none; }
  & .apv-stream-ipa { opacity: 0; transform: scale(.6); }
}
.apv-stream .apv-stream-pcap {
  position: absolute; left: 50%; bottom: 14%; translate: -50% 0; max-width: 80%; text-align: center; font-size: clamp(14px, 2cqi, 22px); font-weight: 600; text-wrap: balance;
  color: oklch(0.98 0 0); text-shadow: 0 0 6px oklch(0 0 0), 0 2px 2px oklch(0 0 0); transition: bottom .45s var(--apv-stream-ease), opacity .3s;
  &:empty { opacity: 0; }
}
.apv-stream .apv-stream-player.is-ui .apv-stream-pcap { bottom: 26%; }
.apv-stream .apv-stream-skip {
  position: absolute; right: 24px; bottom: 120px; display: flex; align-items: center; gap: 10px; padding: 10px 14px 10px 18px; border-radius: 6px;
  background: oklch(0.98 0 0 / .92); color: oklch(0.15 0 0); font-weight: 750; font-size: 14px; opacity: 0; transform: translateX(20px); pointer-events: none;
  & kbd { background: oklch(0 0 0 / .1); color: inherit; }
  &.is-on { opacity: 1; transform: none; pointer-events: auto; }
}

/* ── tabs + toast ── */
.apv-stream .apv-stream-tabs { display: none; }
.apv-stream .apv-stream-toast {
  position: absolute; left: 50%; bottom: 20px; z-index: 30; display: flex; align-items: center; gap: 12px; padding: 9px 9px 9px 15px; border-radius: 10px;
  background: var(--apv-stream-ink); color: var(--apv-stream-bg); font-weight: 600; font-size: 12.5px; box-shadow: 0 16px 40px -12px oklch(0 0 0 / .8);
  translate: -50% 0; opacity: 0; transform: translateY(14px); pointer-events: none; transition: opacity .25s, transform .45s var(--apv-stream-spring);
  & button { padding: 5px 10px; border-radius: 6px; font-weight: 800; background: color-mix(in oklch, var(--apv-stream-bg) 12%, transparent); }
  &.is-on { opacity: 1; transform: none; pointer-events: auto; }
