/* ── narrower ── */
@container (max-width: 959px) {
  .apv-stream .apv-stream-legend { display: none; }
  .apv-stream .apv-stream-dbody { grid-template-columns: minmax(0, 1fr); gap: 18px; }
  .apv-stream .apv-stream-info { max-width: 72cqi; }
}
@container (max-width: 759px) {
  .apv-stream .apv-stream-app { grid-template-columns: minmax(0, 1fr); grid-template-rows: minmax(0, 1fr) auto; grid-template-areas: "main" "tabs"; }
  .apv-stream .apv-stream-rail { display: none; }
  .apv-stream .apv-stream-main { grid-template-rows: minmax(0, 52%) auto minmax(0, 1fr); }
  .apv-stream .apv-stream-backdrop { height: 70%; }
  .apv-stream .apv-stream-shade { background: linear-gradient(180deg, color-mix(in oklch, var(--apv-stream-bg) 30%, transparent), transparent 30%, color-mix(in oklch, var(--apv-stream-bg) 75%, transparent) 62%, var(--apv-stream-bg) 96%); }
  .apv-stream .apv-stream-info { max-width: none; gap: 7px; }
  .apv-stream .apv-stream-info p.apv-stream-syn { display: none; }
  .apv-stream .apv-stream-btn { height: 34px; padding: 0 14px 0 11px; font-size: 12.5px; }
  .apv-stream .apv-stream-btn.is-round { width: 34px; }
  .apv-stream .apv-stream-card { --w: clamp(132px, 38cqi, 200px); }
  .apv-stream .apv-stream-card.is-p { --w: clamp(96px, 27cqi, 140px); }
  .apv-stream .apv-stream-page { display: none; }
  .apv-stream .apv-stream-grid { grid-template-columns: repeat(auto-fill, minmax(140px, 1fr)); }
  .apv-stream .apv-stream-ep { grid-template-columns: 104px minmax(0, 1fr); gap: 4px 12px; padding: 10px 4px;
    & > b { display: none; }
    & time { grid-column: 2; }
  }
  .apv-stream .apv-stream-tabs {
    grid-area: tabs; display: grid; grid-template-columns: repeat(5, 1fr); background: color-mix(in oklch, var(--apv-stream-bg) 94%, var(--apv-stream-ink)); border-top: 1px solid var(--apv-stream-line); z-index: 7;
    & button { display: grid; justify-items: center; gap: 2px; padding: 7px 0 9px; font-size: 10px; font-weight: 650; color: var(--apv-stream-faint); }
    & button[aria-current="page"] { color: var(--apv-stream-ink); }
    & svg { width: 20px; height: 20px; }
  }
  .apv-stream .apv-stream-player { grid-area: 1 / 1 / -1 / -1; }
  .apv-stream .apv-stream-pctl .apv-stream-pname { visibility: hidden; }
  .apv-stream .apv-stream-skip { bottom: 110px; right: 14px; }
  .apv-stream .apv-stream-toast { bottom: 70px; }
}
@container (max-width: 420px) {
  .apv-stream .apv-stream-pctl [data-act="pmute"] { display: none; }
  .apv-stream .apv-stream-meta .apv-stream-hd { display: none; }
}

@keyframes apv-stream-rise { from { opacity: 0; transform: translateY(14px); } }
@keyframes apv-stream-pop { 0% { transform: scale(.4) rotate(-20deg); } 100% { transform: none; } }

@media (prefers-reduced-motion: reduce) {
  .apv-stream .apv-stream-main, .apv-stream .apv-stream-rows, .apv-stream .apv-stream-track { transition: none; scroll-behavior: auto; }
  .apv-stream .apv-stream-row, .apv-stream .apv-stream-grid .apv-stream-card, .apv-stream .apv-stream-ep { animation: none; }
  .apv-stream .apv-stream-card, .apv-stream .apv-stream-btn { transition: box-shadow .2s; }
  .apv-stream .apv-stream-card:hover, .apv-stream .apv-stream-card:focus-visible { transform: none; }
  .apv-stream .apv-stream-info { transition: opacity .2s; }
  .apv-stream .apv-stream-info.is-out { transform: none; filter: none; }
  .apv-stream .apv-stream-detail { transition: opacity .2s, display .2s allow-discrete; }
  .apv-stream .apv-stream-detail, .apv-stream .apv-stream-detail[hidden] { transform: none; }
  .apv-stream .apv-stream-btn[aria-pressed="true"] .apv-stream-chk { animation: none; }
  .apv-stream .apv-stream-toast, .apv-stream .apv-stream-toast.is-on { transform: none; transition: opacity .2s; }
}

