  /* re-theme: paper, ink, accent, marker */
  --apv-pod-paper: oklch(0.973 0.008 150);
  --apv-pod-ink: oklch(0.25 0.035 165);
  --apv-pod-accent: oklch(0.5 0.11 168);
  --apv-pod-marker: oklch(0.92 0.14 102);
  --apv-pod-card: color-mix(in oklch, var(--apv-pod-paper) 50%, white);
  --apv-pod-sunk: color-mix(in oklch, var(--apv-pod-paper) 94%, var(--apv-pod-ink));
  --apv-pod-line: color-mix(in oklch, var(--apv-pod-ink) 10%, transparent);
  --apv-pod-line2: color-mix(in oklch, var(--apv-pod-ink) 18%, transparent);
  --apv-pod-mute: color-mix(in oklch, var(--apv-pod-ink) 60%, var(--apv-pod-paper));
  --apv-pod-faint: color-mix(in oklch, var(--apv-pod-ink) 38%, var(--apv-pod-paper));
  --apv-pod-tint: color-mix(in oklch, var(--apv-pod-accent) 12%, var(--apv-pod-paper));
  --apv-pod-ease: cubic-bezier(.2, .8, .2, 1);
  --apv-pod-spring: linear(0, 0.1 4%, 0.38 10%, 0.74 17%, 0.96 24%, 1.04 30%, 1.05 35%, 1.02 44%, 1 55%, 1);

  position: relative; width: 100%; height: var(--apv-pod-h, 680px);
  container-type: inline-size; overflow: clip; isolation: isolate; box-sizing: border-box;
  background: var(--apv-pod-paper); color: var(--apv-pod-ink); color-scheme: light; accent-color: var(--apv-pod-accent);
  border-radius: 14px; font: 13px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-tap-highlight-color: transparent;

  & *, & *::before, & *::after { box-sizing: border-box; }
  &:focus { outline: none; }
  & :focus-visible { outline: 2px solid var(--apv-pod-accent); outline-offset: 2px; border-radius: 6px; }
  & button, & input { font: inherit; color: inherit; }
  & button { cursor: pointer; background: none; border: 0; padding: 0; }
  & h2, & h3, & p, & ol, & ul { margin: 0; padding: 0; }
  & ol, & ul { list-style: none; }
  & svg { width: 18px; height: 18px; fill: none; stroke: currentColor; stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; flex: none; }
  & svg text { fill: currentColor; stroke: none; font: 700 6.4px system-ui; }
  & .apv-pod-fill { fill: currentColor; stroke: none; }
  & kbd { font: 600 10px/1 ui-monospace, Menlo, monospace; padding: 2px 5px; min-width: 18px; display: inline-block; text-align: center; border: 1px solid var(--apv-pod-line2); border-bottom-width: 2px; border-radius: 4px; color: var(--apv-pod-mute); background: var(--apv-pod-card); }
  & mark { background: var(--apv-pod-marker); color: inherit; border-radius: 3px; padding: 0 1px; }
}
.apv-pod .apv-pod-app {
  height: 100%; display: grid; grid-template-columns: 220px minmax(290px, 340px) minmax(0, 1fr); grid-template-rows: minmax(0, 1fr) auto;
  grid-template-areas: "side list player" "side list player";
}

/* ── covers: typographic, one recipe per show ── */
.apv-pod .apv-pod-cov {
  position: relative; display: grid; aspect-ratio: 1; border-radius: 8px; overflow: hidden; container-type: inline-size; flex: none;
  background: var(--b); color: var(--f); box-shadow: inset 0 0 0 1px oklch(0 0 0 / .06);
  & b { position: absolute; left: 9%; right: 9%; bottom: 8%; font-size: 15cqi; line-height: .92; font-weight: 800; letter-spacing: -.04em; text-wrap: balance; }
  &.is-sm b { display: none; }
  &[data-k="small"] { background: radial-gradient(circle at 70% 30%, var(--f) 0 16%, transparent 16.5%), radial-gradient(circle at 76% 25%, var(--b) 0 15%, transparent 15.5%), var(--b); }
  &[data-k="small"] b { font-weight: 300; text-transform: lowercase; letter-spacing: -.03em; }
  &[data-k="table"] { background: linear-gradient(var(--b) 0 0) 0 0 / 100% 100%, var(--b); }
  &[data-k="table"]::before { content: ""; position: absolute; left: 9%; right: 9%; top: 34%; height: 9%; border-radius: 2px; background: var(--f); }
  &[data-k="table"]::after { content: ""; position: absolute; left: 20%; right: 20%; top: 43%; height: 18%; background: linear-gradient(90deg, var(--f) 0 6%, transparent 6% 94%, var(--f) 94%); }
  &[data-k="signal"] { background: repeating-linear-gradient(90deg, transparent 0 7%, color-mix(in oklch, var(--f) 22%, transparent) 7% 7.6%), var(--b); }
  &[data-k="signal"]::before { content: ""; position: absolute; left: 0; right: 0; top: 22%; height: 34%; background: radial-gradient(ellipse 12% 50% at 20% 100%, transparent 70%, var(--f) 72% 82%, transparent 84%) 0 0 / 33.3% 100%; }
  &[data-k="signal"] b { font-family: ui-monospace, Menlo, monospace; font-size: 11cqi; font-weight: 700; letter-spacing: 0; text-transform: uppercase; }
  &[data-k="cold"] { background: repeating-radial-gradient(ellipse 140% 60% at 50% 120%, var(--b) 0 5%, color-mix(in oklch, var(--f) 30%, var(--b)) 5% 5.8%); }
  &[data-k="cold"] b { text-transform: uppercase; letter-spacing: .12em; font-size: 11cqi; font-weight: 700; }
  &[data-k="margins"] { background: linear-gradient(90deg, transparent 0 22%, var(--f) 22% 23%, transparent 23%), var(--b); }
  &[data-k="margins"] b { font-family: ui-serif, Georgia, serif; font-style: italic; font-weight: 500; left: 28%; letter-spacing: -.02em; }
}

/* ── side ── */
.apv-pod .apv-pod-side { grid-area: side; min-height: 0; display: flex; flex-direction: column; gap: 14px; padding: 18px 12px; border-right: 1px solid var(--apv-pod-line); overflow: auto; scrollbar-width: none; }
.apv-pod .apv-pod-brand {
  display: flex; align-items: center; gap: 8px; padding: 0 8px;
  & svg { width: 22px; height: 22px; color: var(--apv-pod-accent); stroke-width: 2; }
  & b { font-size: 17px; font-weight: 800; letter-spacing: -.04em; }
}
.apv-pod .apv-pod-find {
  display: flex; align-items: center; gap: 7px; height: 34px; padding: 0 7px 0 10px; border-radius: 9px; background: var(--apv-pod-card); box-shadow: inset 0 0 0 1px var(--apv-pod-line2);
  & svg { width: 15px; height: 15px; color: var(--apv-pod-faint); }
  & input { flex: 1; min-width: 0; border: 0; outline: 0; background: none; font-size: 12.5px; }
  & input::-webkit-search-cancel-button { display: none; }
  &:focus-within { box-shadow: inset 0 0 0 1.5px var(--apv-pod-accent); }
  &:focus-within kbd { opacity: 0; }
}
.apv-pod .apv-pod-nav {
  display: grid; gap: 2px;
  & h4 { margin: 10px 8px 6px; font-size: 10px; font-weight: 750; letter-spacing: .14em; text-transform: uppercase; color: var(--apv-pod-faint); }
  & button { display: grid; grid-template-columns: 34px minmax(0, 1fr) auto; align-items: center; gap: 10px; width: 100%; padding: 6px 8px; border-radius: 9px; text-align: left; transition: background .2s; }
  & button > svg { justify-self: center; color: var(--apv-pod-mute); }
  & button .apv-pod-cov { width: 34px; border-radius: 6px; }
  & button span { display: grid; min-width: 0; }
  & button b { font-weight: 650; font-size: 12.5px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
  & button small { font-size: 11px; color: var(--apv-pod-mute); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
  & button output { min-width: 20px; padding: 1px 6px; border-radius: 999px; font: 700 10.5px/16px system-ui; font-variant-numeric: tabular-nums; text-align: center; background: var(--apv-pod-accent); color: var(--apv-pod-paper); }
  & button output:empty { display: none; }
  & button:hover { background: var(--apv-pod-line); }
  & button[aria-current="page"] { background: var(--apv-pod-card); box-shadow: 0 0 0 1px var(--apv-pod-line), 0 2px 6px -3px var(--apv-pod-line2); }
}

/* ── episode list ── */
.apv-pod .apv-pod-list { grid-area: list; min-height: 0; overflow: auto; overscroll-behavior: contain; scrollbar-width: thin; scrollbar-color: var(--apv-pod-line2) transparent; border-right: 1px solid var(--apv-pod-line); }
.apv-pod .apv-pod-show {
  display: grid; grid-template-columns: 76px minmax(0, 1fr); gap: 4px 14px; padding: 18px 16px 14px; align-items: end;
  & .apv-pod-cov { grid-row: 1 / 3; width: 76px; box-shadow: 0 10px 20px -12px var(--apv-pod-ink); }
  & small { font-size: 10.5px; font-weight: 700; letter-spacing: .12em; text-transform: uppercase; color: var(--apv-pod-accent); }
  & h2 { font-size: clamp(18px, 1.9cqi, 22px); line-height: 1.1; font-weight: 800; letter-spacing: -.035em; text-wrap: balance; }
  & p { grid-column: 1 / -1; margin-top: 8px; color: var(--apv-pod-mute); text-wrap: pretty; font-size: 12.5px; }
}
.apv-pod .apv-pod-sub {
  grid-column: 1 / -1; display: flex; gap: 8px; align-items: center; margin-top: 8px;
  & button { height: 28px; padding: 0 12px; border-radius: 999px; font-size: 12px; font-weight: 650; box-shadow: inset 0 0 0 1px var(--apv-pod-line2); transition: background .2s, color .2s; display: inline-flex; align-items: center; gap: 6px; }
  & button[aria-pressed="true"] { background: var(--apv-pod-ink); color: var(--apv-pod-paper); box-shadow: none; }
  & button svg { width: 14px; height: 14px; }
}
.apv-pod .apv-pod-filter {
  position: sticky; top: 0; z-index: 2; display: flex; gap: 4px; padding: 8px 16px; background: color-mix(in oklch, var(--apv-pod-paper) 88%, transparent); backdrop-filter: blur(8px); border-bottom: 1px solid var(--apv-pod-line);
  & button { padding: 4px 10px; border-radius: 7px; font-size: 12px; font-weight: 600; color: var(--apv-pod-mute); }
  & button:hover { color: var(--apv-pod-ink); }
  & button[aria-checked="true"] { background: var(--apv-pod-card); color: var(--apv-pod-ink); box-shadow: 0 0 0 1px var(--apv-pod-line2); }
  & h3 { font-size: 15px; font-weight: 800; letter-spacing: -.02em; margin-right: auto; align-self: center; }
}
.apv-pod .apv-pod-ep {
  position: relative; display: grid; grid-template-columns: 38px minmax(0, 1fr) 28px; gap: 2px 12px; align-items: center; padding: 12px 12px 12px 16px; border-bottom: 1px solid var(--apv-pod-line);
  animation: apv-pod-rise .45s var(--apv-pod-ease) both; animation-delay: calc(min(var(--i, 0), 12) * 32ms);
  transition: background .2s;
  & .apv-pod-epbody { grid-column: 2; text-align: left; display: grid; gap: 2px; min-width: 0; }
  & small { font-size: 11px; color: var(--apv-pod-faint); font-variant-numeric: tabular-nums; letter-spacing: .02em; }
  & b { font-weight: 650; font-size: 13.5px; line-height: 1.25; letter-spacing: -.01em; text-wrap: pretty; }
  & p { font-size: 12px; color: var(--apv-pod-mute); display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }
  & .apv-pod-cov { width: 38px; border-radius: 6px; grid-row: 1; grid-column: 1; }
  &:hover { background: var(--apv-pod-card); }
  &.is-cur { background: var(--apv-pod-tint); }
  &.is-cur b { color: var(--apv-pod-accent); }
  &.is-played b, &.is-played p { color: var(--apv-pod-faint); }
}
.apv-pod .apv-pod-ring {
  grid-row: 1; grid-column: 1; position: relative; display: grid; place-items: center; width: 38px; height: 38px; border-radius: 50%;
  background: conic-gradient(var(--apv-pod-accent) calc(var(--p, 0) * 1%), var(--apv-pod-line2) 0);
  transition: transform .35s var(--apv-pod-spring);
  &::before { content: ""; position: absolute; inset: 2.5px; border-radius: 50%; background: var(--apv-pod-paper); }
  & svg { position: relative; width: 16px; height: 16px; color: var(--apv-pod-ink); }
  &:hover { transform: scale(1.08); }
  & .apv-pod-ipa { display: none; }
}
.apv-pod .apv-pod-ep.is-cur .apv-pod-ring::before { background: var(--apv-pod-tint); }
.apv-pod[data-playing="true"] .apv-pod-ep.is-cur .apv-pod-ring {
  & .apv-pod-ipa { display: block; }
  & .apv-pod-ipl { display: none; }
}
.apv-pod .apv-pod-ep.is-new .apv-pod-epbody small::before { content: ""; display: inline-block; width: 6px; height: 6px; margin-right: 6px; border-radius: 50%; background: var(--apv-pod-accent); vertical-align: 1px; }
.apv-pod .apv-pod-more { grid-column: 3; grid-row: 1; display: grid; place-items: center; width: 28px; height: 28px; border-radius: 50%; color: var(--apv-pod-faint);
  &:hover, &[aria-expanded="true"] { background: var(--apv-pod-line); color: var(--apv-pod-ink); }
}
.apv-pod .apv-pod-empty { padding: 40px 20px; text-align: center; color: var(--apv-pod-mute); text-wrap: balance;
  & b { display: block; color: var(--apv-pod-ink); font-size: 14px; margin-bottom: 4px; }
}

/* ── player ── */
.apv-pod .apv-pod-player { grid-area: player; position: relative; min-height: 0; min-width: 0; display: grid; grid-template-rows: auto auto auto auto auto auto minmax(0, 1fr); padding: 16px 24px 0; }
.apv-pod .apv-pod-phead {
  display: flex; align-items: center; gap: 14px; margin-bottom: 14px;
  & .apv-pod-cov { width: 52px; box-shadow: 0 8px 16px -10px var(--apv-pod-ink); }
  & .apv-pod-ptitle { display: grid; min-width: 0; }
  & small { font-size: 11px; font-weight: 700; letter-spacing: .1em; text-transform: uppercase; color: var(--apv-pod-accent); }
  & h2 { font-size: clamp(17px, 2cqi, 23px); line-height: 1.12; font-weight: 800; letter-spacing: -.035em; text-wrap: balance; }
}
.apv-pod .apv-pod-back { display: none; place-items: center; width: 32px; height: 32px; border-radius: 50%; border: 1px solid var(--apv-pod-line2); }
.apv-pod .apv-pod-wave {
  position: relative; height: 64px; border-radius: 8px; cursor: pointer; touch-action: none;
  & canvas { position: absolute; inset: 0; width: 100%; height: 100%; display: block; }
  &:focus-visible { outline-offset: 4px; }
}
.apv-pod .apv-pod-tip {
  position: absolute; bottom: calc(100% + 6px); left: 0; translate: -50% 0; padding: 4px 8px; border-radius: 6px; white-space: nowrap; pointer-events: none;
  background: var(--apv-pod-ink); color: var(--apv-pod-paper); font: 600 11px system-ui; font-variant-numeric: tabular-nums; opacity: 0; transition: opacity .15s;
  & span { font: 500 11px ui-monospace, Menlo, monospace; opacity: .7; margin-left: 6px; }
}
.apv-pod .apv-pod-wave:hover .apv-pod-tip, .apv-pod .apv-pod-wave.is-drag .apv-pod-tip { opacity: 1; }
.apv-pod .apv-pod-times {
  display: grid; grid-template-columns: auto minmax(0, 1fr) auto; gap: 12px; margin-top: 6px; font-size: 11.5px; color: var(--apv-pod-mute);
  & output { font: 500 11.5px ui-monospace, Menlo, monospace; font-variant-numeric: tabular-nums; }
  & span { text-align: center; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-weight: 600; color: var(--apv-pod-ink); }
}
.apv-pod .apv-pod-ctl {
  display: flex; align-items: center; justify-content: center; gap: 14px; margin-top: 8px;
  & > button { display: grid; place-items: center; width: 40px; height: 40px; border-radius: 50%; color: var(--apv-pod-ink); transition: background .2s, transform .35s var(--apv-pod-spring); }
  & > button:hover { background: var(--apv-pod-line); }
  & > button:active { transform: scale(.92); }
  & > button svg { width: 24px; height: 24px; }
  & .apv-pod-speed { width: auto; min-width: 48px; height: 30px; padding: 0 10px; border-radius: 999px; font: 700 12px ui-monospace, Menlo, monospace; font-variant-numeric: tabular-nums; box-shadow: inset 0 0 0 1px var(--apv-pod-line2); }
  & .apv-pod-sleep { width: auto; min-width: 48px; height: 30px; padding: 0 10px; border-radius: 999px; display: flex; gap: 5px; box-shadow: inset 0 0 0 1px var(--apv-pod-line2); font: 700 11.5px ui-monospace, Menlo, monospace; font-variant-numeric: tabular-nums; }
  & .apv-pod-sleep svg { width: 15px; height: 15px; }
  & .apv-pod-sleep.is-on { background: var(--apv-pod-ink); color: var(--apv-pod-paper); box-shadow: none; }
}
.apv-pod .apv-pod-play {
  position: relative; background: var(--apv-pod-ink); color: var(--apv-pod-paper);
  & svg { position: absolute; transition: opacity .2s, transform .4s var(--apv-pod-spring); }
  & .apv-pod-ipa { opacity: 0; transform: scale(.5); }
}
.apv-pod .apv-pod-ctl > .apv-pod-play {
  width: 52px; height: 52px; background: var(--apv-pod-ink); color: var(--apv-pod-paper);
  & svg { width: 22px; height: 22px; }
  &:hover { transform: scale(1.05); background: var(--apv-pod-accent); }
}
.apv-pod[data-playing="true"] .apv-pod-play {
  & .apv-pod-ipl { opacity: 0; transform: scale(.5); }
  & .apv-pod-ipa { opacity: 1; transform: none; }
}
.apv-pod .apv-pod-ends { text-align: center; font-size: 11.5px; color: var(--apv-pod-faint); margin-top: 6px; font-variant-numeric: tabular-nums; min-height: 17px; }
.apv-pod .apv-pod-tabs {
  display: flex; align-items: center; gap: 2px; margin-top: 10px; border-bottom: 1px solid var(--apv-pod-line);
  & [role="tab"] { position: relative; padding: 9px 10px; font-size: 12.5px; font-weight: 650; color: var(--apv-pod-mute); }
  & [role="tab"]::after { content: ""; position: absolute; left: 10px; right: 10px; bottom: -1px; height: 2px; border-radius: 2px; background: var(--apv-pod-ink); transform: scaleX(0); transition: transform .35s var(--apv-pod-ease); }
  & [role="tab"][aria-selected="true"] { color: var(--apv-pod-ink); }
  & [role="tab"][aria-selected="true"]::after { transform: none; }
  & .apv-pod-clip { margin-left: auto; display: flex; align-items: center; gap: 6px; padding: 5px 8px; border-radius: 8px; color: var(--apv-pod-mute); }
  & .apv-pod-clip:hover { background: var(--apv-pod-line); color: var(--apv-pod-ink); }
  & .apv-pod-clip svg { width: 16px; height: 16px; }
}
.apv-pod .apv-pod-panel { position: relative; min-height: 0; overflow: auto; overscroll-behavior: contain; scrollbar-width: thin; scrollbar-color: var(--apv-pod-line2) transparent; padding: 12px 0 60px; scroll-behavior: smooth; }
.apv-pod .apv-pod-para {
  display: grid; grid-template-columns: 50px minmax(0, 1fr); gap: 2px 14px; padding: 10px 12px 10px 6px; border-radius: 10px; cursor: pointer; transition: background .25s;
  & time { grid-row: 1 / 3; padding-top: 1px; font: 500 11px ui-monospace, Menlo, monospace; font-variant-numeric: tabular-nums; color: var(--apv-pod-faint); text-align: right; }
  & .apv-pod-spk { font-size: 10px; font-weight: 750; letter-spacing: .14em; text-transform: uppercase; color: var(--apv-pod-faint); }
  & .apv-pod-txt { position: relative; isolation: isolate; font-size: 14.5px; line-height: 1.6; color: var(--apv-pod-faint); text-wrap: pretty; transition: color .3s; }
  &:hover { background: var(--apv-pod-card); }
  &.is-past .apv-pod-txt { color: color-mix(in oklch, var(--apv-pod-ink) 75%, var(--apv-pod-paper)); }
  &.is-now { background: var(--apv-pod-card); box-shadow: 0 0 0 1px var(--apv-pod-line); }
  &.is-now time, &.is-now .apv-pod-spk { color: var(--apv-pod-accent); }
  &.is-now .apv-pod-txt { color: var(--apv-pod-faint); }
}
.apv-pod .apv-pod-w { transition: color .25s; }
.apv-pod .apv-pod-w.is-said { color: var(--apv-pod-ink); }
.apv-pod .apv-pod-mark {
  position: absolute; left: 0; top: 0; z-index: -1; border-radius: 4px; background: var(--apv-pod-marker); pointer-events: none;
  transition: transform .16s cubic-bezier(.3, .7, .3, 1), width .16s cubic-bezier(.3, .7, .3, 1), height .16s; opacity: 0;
}
.apv-pod[data-playing="true"] .apv-pod-mark, .apv-pod .apv-pod-mark.is-on { opacity: 1; }
.apv-pod .apv-pod-now {
  position: absolute; left: 50%; bottom: 16px; translate: -50% 0; z-index: 5; display: flex; align-items: center; gap: 7px; padding: 8px 10px 8px 13px; border-radius: 999px;
  background: var(--apv-pod-ink); color: var(--apv-pod-paper); font-weight: 650; font-size: 12.5px; box-shadow: 0 10px 26px -10px var(--apv-pod-ink);
  transition: opacity .25s, transform .4s var(--apv-pod-spring), display .4s allow-discrete;
  @starting-style { opacity: 0; transform: translateY(10px); }
  & svg { width: 15px; height: 15px; }
  & kbd { background: transparent; color: inherit; border-color: color-mix(in oklch, var(--apv-pod-paper) 30%, transparent); }
  &[hidden] { display: none; opacity: 0; transform: translateY(10px); }
}
.apv-pod .apv-pod-chap {
  position: relative; display: grid; grid-template-columns: 52px minmax(0, 1fr) auto; gap: 12px; align-items: center; width: 100%; padding: 11px 10px; border-radius: 9px; text-align: left; overflow: hidden;
  animation: apv-pod-rise .4s var(--apv-pod-ease) both; animation-delay: calc(var(--i, 0) * 35ms);
  & time { font: 500 11.5px ui-monospace, Menlo, monospace; font-variant-numeric: tabular-nums; color: var(--apv-pod-faint); }
  & b { font-weight: 600; }
  & small { font: 500 11px ui-monospace, Menlo, monospace; color: var(--apv-pod-faint); }
  & i { position: absolute; left: 0; bottom: 0; height: 2px; width: calc(var(--p, 0) * 1%); background: var(--apv-pod-accent); }
  &:hover { background: var(--apv-pod-card); }
  &[aria-current="true"] { background: var(--apv-pod-tint); }
