@keyframes apv-pod-rise { from { opacity: 0; transform: translateY(8px); } }
@keyframes apv-pod-up { from { opacity: 0; transform: translateY(22px); } }

@media (prefers-reduced-motion: reduce) {
  .apv-pod .apv-pod-ep, .apv-pod .apv-pod-chap, .apv-pod .apv-pod-bm, .apv-pod[data-pane="player"] .apv-pod-player { animation: none; }
