/* Overtone. A paragraph's words are timed by their share of its characters,
   so the marker can glide word to word without per-word timestamps. The
   waveform for the transcribed episode is derived from the transcript:
   every dip is a pause between speakers. */
const doc = root.ownerDocument;
const $ = (s, el = root) => el.querySelector(s);
const $$ = (s, el = root) => [...el.querySelectorAll(s)];
const RM = matchMedia('(prefers-reduced-motion: reduce)');
const esc = s => String(s == null ? '' : s).replace(/[&<>"']/g, c => '&#' + c.charCodeAt(0) + ';');
const clamp = (v, a, b) => Math.min(b, Math.max(a, v));
const fmt = s => { s = Math.max(0, Math.floor(s)); const h = Math.floor(s / 3600), m = Math.floor(s % 3600 / 60), x = s % 60; return (h ? h + ':' + String(m).padStart(2, '0') : m) + ':' + String(x).padStart(2, '0'); };
const mins = s => { const m = Math.round(s / 60); return m >= 60 ? Math.floor(m / 60) + ' hr ' + (m % 60) + ' min' : m + ' min'; };
const ICON = {
  play: '<svg class="apv-pod-ipl" viewBox="0 0 24 24" aria-hidden="true"><path class="apv-pod-fill" d="M8.5 5.8v12.4L18.6 12z"/></svg><svg class="apv-pod-ipa" viewBox="0 0 24 24" aria-hidden="true"><path class="apv-pod-fill" d="M7 5.5h3.4v13H7zM13.6 5.5H17v13h-3.4z"/></svg>',
  clock: '<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="8"/><path d="M12 7.5V12l3 2"/></svg>',
  more: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M6 12h.01M12 12h.01M18 12h.01" stroke-width="2.8"/></svg>',
  next: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 7h10M4 12h10M4 17h6M17 14v6M14 17h6"/></svg>',
  last: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 7h16M4 12h16M4 17h9"/></svg>',
  check: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m5 12.5 4.5 4.5L19 7.5"/></svg>',
  queue: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 6.5h11M4 11.5h11M4 16.5h6"/><path class="apv-pod-fill" d="M15 14v6l5-3z"/></svg>',
  x: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M6 6l12 12M18 6 6 18"/></svg>',
  plus: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 5v14M5 12h14"/></svg>',
};

/* ── shows & episodes ── */
const SHOWS = [
  { id: 'small', k: 'small', t: 'Small Hours', host: 'Juno Achterberg', b: 'oklch(0.33 0.06 160)', f: 'oklch(0.92 0.08 100)', sub: true, d: 'A seven-minute daily on how ordinary things work. New episodes every weekday at 6 am.' },
  { id: 'table', k: 'table', t: 'The Long Table', host: 'Marisol Ferro & Kit Amaro', b: 'oklch(0.6 0.16 34)', f: 'oklch(0.97 0.03 80)', sub: true, d: 'Two cooks, one long table, and the stories behind what we eat. Every Tuesday.' },
  { id: 'signal', k: 'signal', t: 'Signal / Noise', host: 'Dev Raman', b: 'oklch(0.23 0.012 95)', f: 'oklch(0.88 0.16 122)', sub: true, d: 'Long conversations with the people who build the tools everyone uses without thinking. Fortnightly.' },
  { id: 'cold', k: 'cold', t: 'Coldwater', host: 'Rhian Talbot', b: 'oklch(0.52 0.05 222)', f: 'oklch(0.95 0.02 220)', sub: true, d: 'Season two. In 1998 a ferry left Port Ellery with forty-one passengers and docked with forty. A documentary in eight parts.' },
  { id: 'margins', k: 'margins', t: 'Margins', host: 'Thea Lindqvist', b: 'oklch(0.93 0.035 85)', f: 'oklch(0.38 0.1 32)', sub: false, d: 'Writers on the books that changed how they write. Monthly.' },
];
const SH = Object.fromEntries(SHOWS.map(s => [s.id, s]));
const E = (id, show, date, t, dur, d, ch) => ({ id, show, date, t, dur, d, ch });
const EPS = [
  E('s1', 'small', 'Thu 1 Oct', 'Why does bread go stale?', 400, 'It isn’t drying out. A cereal chemist on starch crystals, the fridge, and how to bring a loaf back from the dead.', [[0, 'Cold open'], [38, 'It isn’t drying out'], [150, 'Why the fridge is the worst place'], [262, 'Bringing a loaf back'], [352, 'Listener question']]),
  E('s2', 'small', 'Wed 30 Sep', 'How do noise-cancelling headphones cancel?', 432, 'Anti-noise, microphones that listen faster than you do, and why it works on engines but not on voices.', [[0, 'Cold open'], [52, 'Sound is pressure'], [188, 'Making the opposite wave'], [330, 'Why voices get through']]),
  E('s3', 'small', 'Tue 29 Sep', 'Where does the smell of rain come from?', 365, 'Petrichor, a soil bacterium that makes geosmin, and the tiny aerosol burst of a single raindrop.', [[0, 'Cold open'], [44, 'Petrichor'], [170, 'Geosmin'], [290, 'Raindrop bubbles']]),
  E('s4', 'small', 'Mon 28 Sep', 'Why are bridges built with gaps?', 451, 'Expansion joints, the metal fingers you drive over, and how much a long steel bridge grows between January and July.', [[0, 'Cold open'], [60, 'Steel grows'], [214, 'Fingers and rockers'], [372, 'Listener question']]),
  E('s5', 'small', 'Fri 25 Sep', 'What makes a knot hold?', 408, 'Friction does the work. Plus why your shoelace bow is secretly a reef knot, and how to tell when it isn’t.', [[0, 'Cold open'], [50, 'Friction does the work'], [200, 'The reef knot'], [330, 'Granny knots']]),
  E('s6', 'small', 'Thu 24 Sep', 'How do they tune a church bell?', 476, 'Bells are tuned by shaving metal from the inside on a lathe. A bell founder explains the five notes in every strike.', [[0, 'Cold open'], [58, 'Five notes in one strike'], [240, 'The tuning lathe'], [400, 'Listener mail']]),
  E('t1', 'table', 'Tue 29 Sep', 'Burnt toast, a defence', 3256, 'Marisol makes the case for char, Kit brings the chemistry, and a listener sends in a forty-year-old toaster.', [[0, 'Hello'], [205, 'The case for burnt toast'], [1262, 'Maillard, then carbon'], [2340, 'The forty-year-old toaster'], [2980, 'What we ate this week']]),
  E('t2', 'table', 'Tue 22 Sep', 'Fermentation for the impatient', 3612, 'Quick pickles tonight, kimchi by the weekend, and what to do when the jar starts to fizz.', [[0, 'Hello'], [180, 'Quick pickles'], [1400, 'Three-day kimchi'], [2600, 'When it goes wrong'], [3300, 'What we ate this week']]),
  E('t3', 'table', 'Tue 15 Sep', 'The perfect cheap knife', 2894, 'What actually makes a knife good, why most of us sharpen wrong, and the one under twenty we both own.', [[0, 'Hello'], [240, 'What makes a knife good'], [1500, 'Sharpening, honestly'], [2500, 'What we ate this week']]),
  E('n1', 'signal', 'Sat 26 Sep', 'The person who maintains your date picker', 3125, 'Ilse Brandt has kept a calendar library alive for nine years, unpaid for seven of them. Time zones, burnout and funding.', [[0, 'Intro'], [160, 'How it started'], [1210, 'Time zones'], [2200, 'Burnout and funding'], [2900, 'Rapid fire']]),
  E('n2', 'signal', 'Sat 12 Sep', 'Designing for the ten-foot screen', 2678, 'A TV interface designer on focus rings you can see from the sofa, and why every remote has too many buttons.', [[0, 'Intro'], [140, 'Focus is the cursor'], [1100, 'Remotes'], [2050, 'Rapid fire']]),
  E('n3', 'signal', 'Sat 29 Aug', 'Why every app needs an undo', 2310, 'Undo stacks, optimistic updates and the support tickets that disappear when people can take things back.', [[0, 'Intro'], [120, 'The cost of a confirm dialog'], [1180, 'Building the stack'], [1980, 'Rapid fire']]),
  E('c1', 'cold', 'Wed 30 Sep', 'Part 3: The Manifest', 2218, 'The passenger list has forty-one names. The harbourmaster’s log has forty. Rhian finds the clerk who wrote both.', [[0, 'Previously'], [95, 'The manifest'], [930, 'Port Ellery, 1998'], [1700, 'The clerk']]),
  E('c2', 'cold', 'Wed 23 Sep', 'Part 2: Crossing', 2054, 'Four hours across the sound in a storm, reconstructed from the people who were on deck.', [[0, 'Previously'], [80, 'Boarding'], [860, 'The storm'], [1600, 'Arrival']]),
  E('c3', 'cold', 'Wed 16 Sep', 'Part 1: Forty-One', 2160, 'A ferry, a headcount, and a question nobody in Port Ellery has wanted to answer for twenty-eight years.', [[0, 'Cold open'], [240, 'The town'], [1100, 'The count'], [1800, 'Why now']]),
  E('m1', 'margins', 'Sun 20 Sep', 'Ama Serwaa on writing short', 2742, 'The novelist on cutting her second book from 400 pages to 160, and the story collection she reads every winter.', [[0, 'Introduction'], [210, 'Cutting'], [1300, 'The winter book'], [2300, 'What she’s reading now']]),
  E('m2', 'margins', 'Tue 18 Aug', 'Rereading with a pencil', 2496, 'Three writers on marginalia, dog-ears and the books they have read more than ten times.', [[0, 'Introduction'], [180, 'The pencil'], [1200, 'Ten times or more'], [2100, 'Listener margins']]),
];
const EP = Object.fromEntries(EPS.map(e => [e.id, e]));

/* the transcribed episode: [start seconds, speaker, text] */
const TX = { s1: [
  [0, 'Juno', 'It’s Thursday, this is Small Hours, and I’m Juno Achterberg. On Sunday I bought a sourdough loaf the size of a car tyre. By Wednesday it had turned into something closer to a roof tile. And I assumed what everyone assumes: the bread dried out. Today we find out why that’s wrong.'],
  [24, 'Juno', 'My guest is Pell Okonjo, a cereal chemist at the Harrowgate Grain Lab, who has spent eleven years watching loaves go stale on purpose. Pell, welcome.'],
  [38, 'Pell', 'Thanks for having me. And you’re in good company, because almost everyone says stale bread is dry bread. But if you weigh a loaf on Sunday and again on Wednesday, it has barely lost any water. The moisture is still in there. It has just moved.'],
  [62, 'Juno', 'Moved where?'],
  [65, 'Pell', 'Into a different arrangement. Flour is mostly starch, and starch comes in tidy little granules. In the oven those granules soak up water, swell and fall apart into a soft, disordered gel. That gel is the crumb you love. The moment the loaf cools, the starch molecules start drifting back towards order, packing themselves into crystals and squeezing water out as they go.'],
  [98, 'Pell', 'Chemists call it retrogradation. You call it stale. The crumb goes firm and crumbly, the crust goes leathery because it pulls some of that released water towards itself, and the flavour flattens out.'],
  [118, 'Juno', 'So a stale loaf isn’t empty. It’s organised.'],
  [123, 'Pell', 'Exactly. Which is why a cracker can be bone dry and still crisp, while a three-day-old baguette is barely drier than a fresh one and feels like a branch. It’s structure, not water.'],
  [150, 'Juno', 'Here’s the part that annoyed me when you told me before we started recording. I keep my bread in the fridge. I thought I was being clever.'],
  [163, 'Pell', 'A lot of people do, and it’s the fastest way to stale a loaf. Starch recrystallises quickest at cool temperatures just above freezing. In our tests, a loaf kept at fridge temperature firmed up about as much in one day as the same loaf did in three days on the counter.'],
  [192, 'Juno', 'So the fridge is basically a staling machine.'],
  [197, 'Pell', 'For bread, yes. It’s great at slowing mould, which is why people reach for it, but you trade mould for texture. The freezer is a different story. Once the water is frozen the starch can’t move, so staling more or less stops. Slice it before it goes in, and toast it straight from frozen.'],
  [230, 'Pell', 'On the counter, use a paper bag or a bread box. Plastic keeps the crust soft and the mould happy; paper lets the crust stay crisp. For a big sourdough, cut side down on a board works better than either.'],
  [262, 'Juno', 'Okay, so my roof tile. Is it gone for good?'],
  [267, 'Pell', 'Not at all, and this is the fun part. Retrogradation is reversible. Heat the bread past about sixty degrees and those starch crystals melt back into the soft gel. Run the loaf quickly under the tap, put it in a hot oven for eight to ten minutes, and it comes out tasting close to fresh.'],
  [300, 'Juno', 'That sounds like a myth my grandmother told me.'],
  [305, 'Pell', 'Your grandmother was a good food scientist. The catch is that it only lasts until the bread cools again, and the second time it stales faster. So revive what you’re going to eat today, not the whole loaf. Anything past saving becomes breadcrumbs, croutons, or the best bread pudding you’ll ever make.'],
  [352, 'Juno', 'Before you go, a listener question. Tomasz in Gdańsk asks why supermarket sandwich bread stays soft for a week.'],
  [362, 'Pell', 'Two reasons. Those loaves often contain fats and emulsifiers that get between the starch molecules and slow them down, and some use enzymes that snip the starch into pieces too short to crystallise neatly. Same chemistry, just with a few obstacles in the way.'],
  [388, 'Juno', 'Pell Okonjo, thank you. Tomorrow: why your ears pop on a plane. This has been Small Hours.'],
] };
/* per-word timing: each word gets a share of its paragraph proportional to its length */
const WT = {};
Object.entries(TX).forEach(([id, paras]) => {
  WT[id] = paras.map((p, i) => {
    const end = (i + 1 < paras.length ? paras[i + 1][0] : EP[id].dur) - 0.6;
    const words = p[2].split(' '), total = words.reduce((s, w) => s + w.length + 1, 0);
    let acc = 0;
    return words.map(w => { const t = p[0] + (end - p[0]) * (acc / total); acc += w.length + 1; return [w, t]; });
  });
});

const S = {
  view: 'show:small', filter: 'all', q: '',
  cur: 's1', playing: false, speed: 1,
  pos: { s1: 112, t1: 1300, n2: 900 },
  played: ['s3', 's4', 's5', 's6', 't2', 't3', 'c2', 'c3', 'n3', 'm2'],
  upnext: ['t1', 'c1', 'n1'],
  bm: [{ ep: 's1', t: 74, note: 'Flour is mostly starch, and starch comes in tidy little granules' }],
  tab: 'transcript', follow: true, sleep: null,
  subs: Object.fromEntries(SHOWS.map(s => [s.id, s.sub])),
};
const SPEEDS = [0.8, 1, 1.2, 1.5, 1.8, 2];
const posOf = id => S.pos[id] || 0;
const isPlayed = id => S.played.includes(id);
const unplayed = sid => EPS.filter(e => e.show === sid && !isPlayed(e.id)).length;
const chapterAt = (e, t) => { let i = 0; e.ch.forEach((c, k) => { if (t >= c[0]) i = k; }); return i; };
const coverHTML = (sid, sm) => { const s = SH[sid]; return '<span class="apv-pod-cov' + (sm ? ' is-sm' : '') + '" data-k="' + s.k + '" style="--b:' + s.b + ';--f:' + s.f + '" aria-hidden="true"><b>' + esc(s.t) + '</b></span>'; };

/* ── nav ── */
function renderNav() {
  $('[data-nav]').innerHTML =
    '<button type="button" data-view="upnext"' + (S.view === 'upnext' ? ' aria-current="page"' : '') + '>' + ICON.queue + '<span><b>Up Next</b><small>' + S.upnext.length + ' queued &middot; ' + mins(S.upnext.reduce((s, id) => s + EP[id].dur - posOf(id), 0)) + '</small></span><output></output></button>' +
    '<h4>Shows</h4>' + SHOWS.map(s => '<button type="button" data-view="show:' + s.id + '"' + (S.view === 'show:' + s.id ? ' aria-current="page"' : '') + ' aria-label="' + esc(s.t) + ', ' + unplayed(s.id) + ' unplayed">' + coverHTML(s.id, true) + '<span><b>' + esc(s.t) + '</b><small>' + esc(s.host) + '</small></span><output>' + (unplayed(s.id) || '') + '</output></button>').join('');
}

/* ── episode list ── */
