panel.addEventListener('keydown', e => { if (['PageUp', 'PageDown', 'ArrowUp', 'ArrowDown', 'Home', 'End'].includes(e.key) && e.target === panel) userScroll(); });

/* ── events ── */
root.addEventListener('click', e => {
  const b = e.target.closest('button, .apv-pod-w, .apv-pod-para'); if (!b || !root.contains(b)) { closeMenu(); return; }
  if (!b.closest('[data-menu]') && !b.dataset.more && b.dataset.act !== 'sleep') closeMenu();
  if (b.classList.contains('apv-pod-w')) { const k = +b.dataset.w; seek(WT[S.cur][activeP][k][1] + .01); return; }
  if (b.classList.contains('apv-pod-para')) { seek(TX[S.cur][+b.dataset.para][0] + .01); return; }
  if (b.dataset.view) { S.view = b.dataset.view; S.filter = 'all'; if (S.q) { S.q = ''; $('[data-q]').value = ''; } renderNav(); renderList(); $('[data-list]').scrollTop = 0; root.dataset.pane = 'episodes'; return; }
  if (b.dataset.playep) { const id = b.dataset.playep; if (id === S.cur) setPlaying(!S.playing); else loadEp(id, true); return; }
  if (b.dataset.load) { loadEp(b.dataset.load); if (root.dataset.mode === 'narrow') { root.dataset.pane = 'player'; relayout(); } return; }
  if (b.dataset.more) { if (menuBtn === b) closeMenu(true); else epMenu(b, b.dataset.more); return; }
  if (b.dataset.mact) { menuAct(b.dataset.mact); return; }
  if (b.dataset.filter) { S.filter = b.dataset.filter; renderList(); return; }
  if (b.dataset.seek != null) { seek(+b.dataset.seek + .01); if (!S.playing) setPlaying(true); return; }
  if (b.dataset.rmbm != null) { const t = +b.dataset.rmbm, old = S.bm.slice(); S.bm = S.bm.filter(x => !(x.ep === S.cur && x.t === t)); renderPanel(); drawWave(); toast('Clip deleted', () => { S.bm = old; renderPanel(); drawWave(); }); return; }
  if (b.dataset.tab) { S.tab = b.dataset.tab; S.follow = true; renderPanel(); return; }
  switch (b.dataset.act) {
    case 'play': setPlaying(!S.playing); break;
    case 'back': seek(posOf(S.cur) - 15); break;
    case 'fwd': seek(posOf(S.cur) + 30); break;
    case 'speed': setSpeed(1); break;
    case 'sleep': if (menuBtn === b) closeMenu(true); else sleepMenu(b); break;
    case 'clip': bookmark(); break;
    case 'follow': S.follow = true; $('[data-act="follow"]').hidden = true; { const el = $$('.apv-pod-para')[activeP]; if (el) followTo(el); } break;
    case 'undo': if (undoFn) { const f = undoFn; undoFn = null; f(); $('[data-toast]').classList.remove('is-on'); } break;
    case 'sub': { const sid = S.view.split(':')[1]; S.subs[sid] = !S.subs[sid]; renderList(); toast(S.subs[sid] ? 'Following ' + SH[sid].t : 'Unfollowed ' + SH[sid].t); break; }
    case 'clearq': { const old = S.upnext.slice(); S.upnext = []; renderAll(); toast('Cleared Up Next', () => { S.upnext = old; renderAll(); }); break; }
    case 'to-list': root.dataset.pane = 'episodes'; break;
    case 'to-player': root.dataset.pane = 'player'; relayout(); break;
  }
});
function setSpeed(d) {
  const i = SPEEDS.indexOf(S.speed), j = d > 0 ? (i + 1) % SPEEDS.length : Math.max(0, i - 1);
  S.speed = SPEEDS[d < 0 && i === 0 ? 0 : j];
  const b = $('[data-act="speed"]'); b.innerHTML = S.speed + '&times;'; b.setAttribute('aria-label', 'Playback speed ' + S.speed + ' times. Brackets change it');
  tick(true);
}
function bookmark() {
  const e = EP[S.cur], t = Math.floor(posOf(e.id)), tx = TX[e.id];
  let note = e.ch[chapterAt(e, t)][1];
  if (tx) { let i = 0; tx.forEach((p, k) => { if (t >= p[0]) i = k; }); const ws = WT[e.id][i].filter(w => w[1] <= t + 2); note = '“' + ws.slice(-9).map(w => w[0]).join(' ') + '…”'; }
  if (S.bm.some(b => b.ep === e.id && b.t === t)) return;
  S.bm.push({ ep: e.id, t, note });
  drawWave(); if (S.tab === 'notes') renderPanel();
  toast('Clip saved at ' + fmt(t), () => { S.bm = S.bm.filter(b => !(b.ep === e.id && b.t === t)); drawWave(); if (S.tab === 'notes') renderPanel(); });
}
const q = $('[data-q]');
q.addEventListener('input', () => { S.q = q.value.trim(); renderList(); });

/* roving focus in the episode list; ArrowRight reaches the row's menu */
function rove(list, cur, d) {
  const i = list.indexOf(cur), j = clamp(i + d, 0, list.length - 1);
  if (i === j) return;
  list.forEach(x => x.tabIndex = -1); list[j].tabIndex = 0; list[j].focus();
  const L = $('[data-list]'), r = list[j].getBoundingClientRect(), lr = L.getBoundingClientRect();
  if (r.top < lr.top + 44) L.scrollBy({ top: r.top - lr.top - 50 }); else if (r.bottom > lr.bottom) L.scrollBy({ top: r.bottom - lr.bottom + 10 });
}

root.addEventListener('keydown', e => {
  const k = e.key, tg = e.target, M = $('[data-menu]');
  if (!M.hidden) {
    const items = $$('button', M), i = items.indexOf(doc.activeElement);
    if (k === 'Escape') { e.preventDefault(); closeMenu(true); }
    else if (k === 'ArrowDown' || k === 'ArrowUp') { e.preventDefault(); items[(i + (k === 'ArrowDown' ? 1 : -1) + items.length) % items.length].focus(); }
    else if (k === 'Tab') closeMenu();
    return;
  }
  if (tg === q) { if (k === 'Escape') { e.preventDefault(); q.value = ''; S.q = ''; renderList(); q.blur(); root.focus(); } if (k === 'ArrowDown') { const f = $('.apv-pod-epbody'); if (f) { e.preventDefault(); f.focus(); } } return; }
  if (e.metaKey || e.ctrlKey || e.altKey) { if ((k === 'z' || k === 'Z') && undoFn) { e.preventDefault(); $('[data-act="undo"]').click(); } return; }
  if (tg.classList && tg.classList.contains('apv-pod-epbody')) {
    const list = $$('.apv-pod-epbody');
    if (k === 'ArrowDown' || k === 'ArrowUp') { e.preventDefault(); rove(list, tg, k === 'ArrowDown' ? 1 : -1); return; }
    if (k === 'ArrowRight') { e.preventDefault(); tg.parentElement.querySelector('.apv-pod-more').focus(); return; }
    if (k === 'p' || k === 'P') { e.preventDefault(); const id = tg.dataset.load; if (id === S.cur) setPlaying(!S.playing); else loadEp(id, true); return; }
  }
  if (tg.classList && tg.classList.contains('apv-pod-more') && k === 'ArrowLeft') { e.preventDefault(); tg.parentElement.querySelector('.apv-pod-epbody').focus(); return; }
  if (k === 'Escape') { if (root.dataset.pane === 'player' && root.dataset.mode === 'narrow') { root.dataset.pane = 'episodes'; e.preventDefault(); } return; }
  const inWave = tg === wave;
  switch (k) {
    case ' ': if (tg.tagName === 'BUTTON' && !tg.classList.contains('apv-pod-epbody')) return; e.preventDefault(); setPlaying(!S.playing); break;
    case 'ArrowLeft': case 'ArrowRight': {
      if (tg.tagName === 'BUTTON' && !inWave && tg.closest('.apv-pod-tabs')) { const tabs = $$('[role="tab"]'), i = tabs.indexOf(tg); const n = tabs[(i + (k === 'ArrowRight' ? 1 : -1) + tabs.length) % tabs.length]; n.focus(); n.click(); e.preventDefault(); return; }
      e.preventDefault();
      const ev = EP[S.cur], pos = posOf(ev.id);
      if (e.shiftKey) { const ci = chapterAt(ev, pos), tgt = k === 'ArrowRight' ? ev.ch[Math.min(ci + 1, ev.ch.length - 1)][0] : (pos - ev.ch[ci][0] > 3 ? ev.ch[ci][0] : ev.ch[Math.max(0, ci - 1)][0]); seek(tgt + .01); }
      else seek(pos + (k === 'ArrowRight' ? 30 : -15));
      break;
    }
    case '[': setSpeed(-1); break;
    case ']': setSpeed(1); break;
    case 'b': case 'B': bookmark(); break;
    case 'f': case 'F': $('[data-act="follow"]').click(); break;
    case '/': e.preventDefault(); q.focus(); break;
  }
});
root.addEventListener('pointerdown', e => { if (!e.target.closest('[data-menu], [data-more], [data-act="sleep"]')) closeMenu(); });

/* hidden panes have no layout: re-measure the marker and re-follow once the player is visible */
function relayout() {
  requestAnimationFrame(() => {
    if (!root.isConnected) return;
    if (activeP < 0) return;
    const k = activeW; activeW = -1; setWord(Math.max(0, k));
    const el = $$('.apv-pod-para')[activeP]; if (el && S.follow) followTo(el);
  });
}
new ResizeObserver(([en]) => { const w = en.contentRect.width; const m = w < 760 ? 'narrow' : 'wide'; if (m !== root.dataset.mode) { root.dataset.mode = m; if (m !== 'narrow') root.dataset.pane = 'episodes'; } relayout(); }).observe(root);

/* ── boot ── */
renderNav(); renderList(); loadPlayer();

