/* Sunprint: a justified photo grid. Every photo keeps its aspect ratio, so
   when the layout changes each tile moves by a translate and a UNIFORM scale,
   which FLIP can animate without ever distorting a picture. */
.apv-photos {
  /* re-theme: paper, ink, accent */
  --apv-photos-paper: oklch(0.985 0.003 250);
  --apv-photos-ink: oklch(0.22 0.012 260);
  --apv-photos-accent: oklch(0.55 0.19 258);
  --apv-photos-side: oklch(0.962 0.005 250);
  --apv-photos-line: color-mix(in oklch, var(--apv-photos-ink) 9%, transparent);
  --apv-photos-line2: color-mix(in oklch, var(--apv-photos-ink) 16%, transparent);
  --apv-photos-mute: color-mix(in oklch, var(--apv-photos-ink) 60%, var(--apv-photos-paper));
  --apv-photos-faint: color-mix(in oklch, var(--apv-photos-ink) 38%, var(--apv-photos-paper));
  --apv-photos-tint: color-mix(in oklch, var(--apv-photos-accent) 12%, var(--apv-photos-paper));
  --apv-photos-ease: cubic-bezier(.2, .8, .2, 1);
  --apv-photos-spring: linear(0, 0.1 4%, 0.38 10%, 0.74 17%, 0.96 24%, 1.04 30%, 1.05 35%, 1.02 44%, 1 55%, 1);

  position: relative; width: 100%; height: var(--apv-photos-h, 680px);
  container-type: inline-size; overflow: clip; isolation: isolate; box-sizing: border-box;
  background: var(--apv-photos-paper); color: var(--apv-photos-ink); color-scheme: light; accent-color: var(--apv-photos-accent);
  border-radius: 14px; font: 13px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-tap-highlight-color: transparent;

  & *, & *::before, & *::after { box-sizing: border-box; }
  &:focus { outline: none; }
  & :focus-visible { outline: 2px solid var(--apv-photos-accent); outline-offset: 2px; }
  & button, & input { font: inherit; color: inherit; }
  & button { cursor: pointer; background: none; border: 0; padding: 0; }
  & h2, & h3, & p, & dl, & dd { margin: 0; padding: 0; }
  & svg { width: 18px; height: 18px; fill: none; stroke: currentColor; stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; flex: none; }
  & kbd { font: 600 10px/1 ui-monospace, Menlo, monospace; padding: 2px 5px; min-width: 18px; display: inline-block; text-align: center; border: 1px solid var(--apv-photos-line2); border-bottom-width: 2px; border-radius: 4px; color: var(--apv-photos-mute); background: var(--apv-photos-paper); }
}
.apv-photos .apv-photos-app { height: 100%; display: grid; grid-template-columns: 210px minmax(0, 1fr); grid-template-areas: "side main"; }

/* ── side ── */
.apv-photos .apv-photos-side { grid-area: side; min-height: 0; display: flex; flex-direction: column; gap: 16px; padding: 18px 12px 14px; background: var(--apv-photos-side); border-right: 1px solid var(--apv-photos-line); overflow: auto; scrollbar-width: none; }
.apv-photos .apv-photos-brand {
  display: flex; align-items: center; gap: 8px; padding: 0 8px;
  & svg { width: 22px; height: 22px; color: oklch(0.72 0.16 70); stroke-width: 2; }
  & b { font-size: 17px; font-weight: 780; letter-spacing: -.04em; }
}
.apv-photos .apv-photos-nav {
  display: grid; gap: 1px;
  & h4 { margin: 12px 10px 5px; font-size: 10px; font-weight: 750; letter-spacing: .14em; text-transform: uppercase; color: var(--apv-photos-faint); }
  & h4:first-child { margin-top: 0; }
  & button { display: flex; align-items: center; gap: 10px; width: 100%; padding: 6px 10px; border-radius: 8px; text-align: left; font-weight: 550; color: var(--apv-photos-mute); transition: background .18s, color .18s; }
  & button svg { width: 17px; height: 17px; }
  & button span { flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
  & button output { font: 500 11px ui-monospace, Menlo, monospace; font-variant-numeric: tabular-nums; color: var(--apv-photos-faint); }
  & button:hover { background: var(--apv-photos-line); color: var(--apv-photos-ink); }
  & button[aria-current="page"] { background: var(--apv-photos-tint); color: var(--apv-photos-accent); }
  & button[aria-current="page"] output { color: var(--apv-photos-accent); }
  & button.is-drop { background: var(--apv-photos-accent); color: var(--apv-photos-paper); }
}
.apv-photos .apv-photos-store { margin-top: auto; padding: 0 10px; font-size: 11px; color: var(--apv-photos-faint); font-variant-numeric: tabular-nums;
  & i { display: block; height: 4px; margin-top: 6px; border-radius: 4px; background: linear-gradient(90deg, var(--apv-photos-accent) var(--p), var(--apv-photos-line2) var(--p)); }
}

/* ── main ── */
.apv-photos .apv-photos-main { grid-area: main; position: relative; min-width: 0; min-height: 0; display: grid; grid-template-rows: auto auto minmax(0, 1fr); }
.apv-photos .apv-photos-top { display: flex; align-items: center; gap: 14px; padding: 14px 20px 12px; border-bottom: 1px solid var(--apv-photos-line); }
.apv-photos .apv-photos-title {
  flex: 1; min-width: 0;
  & h2 { font-size: clamp(18px, 2.1cqi, 24px); font-weight: 800; letter-spacing: -.035em; line-height: 1.1; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & p { font-size: 12px; color: var(--apv-photos-mute); font-variant-numeric: tabular-nums; }
}
.apv-photos .apv-photos-search {
  display: flex; align-items: center; gap: 7px; height: 32px; width: clamp(150px, 22cqi, 240px); padding: 0 6px 0 10px; border-radius: 8px; background: var(--apv-photos-side); box-shadow: inset 0 0 0 1px var(--apv-photos-line);
  & svg { width: 15px; height: 15px; color: var(--apv-photos-faint); }
  & input { flex: 1; min-width: 0; border: 0; outline: 0; background: none; font-size: 12.5px; }
  & input::-webkit-search-cancel-button { display: none; }
  &:focus-within { box-shadow: inset 0 0 0 1.5px var(--apv-photos-accent); background: var(--apv-photos-paper); }
  &:focus-within kbd { opacity: 0; }
}
.apv-photos .apv-photos-zoom { display: flex; align-items: center; gap: 6px; color: var(--apv-photos-faint);
  & svg { width: 14px; height: 14px; }
  & input { width: 96px; }
}
.apv-photos .apv-photos-selbtn { height: 32px; padding: 0 14px; border-radius: 8px; font-weight: 650; font-size: 12.5px; box-shadow: inset 0 0 0 1px var(--apv-photos-line2); transition: background .2s, color .2s;
  &[aria-pressed="true"] { background: var(--apv-photos-accent); color: var(--apv-photos-paper); box-shadow: none; }
}
.apv-photos .apv-photos-selbar {
  display: flex; align-items: center; gap: 10px; padding: 0 20px; height: 0; overflow: hidden; background: var(--apv-photos-tint); transition: height .4s var(--apv-photos-ease);
  & b { font-size: 13px; font-weight: 750; color: var(--apv-photos-accent); font-variant-numeric: tabular-nums; min-width: 92px; }
  & .apv-photos-selhint { font-size: 11.5px; color: var(--apv-photos-mute); margin-right: auto; }
  & button { display: inline-flex; align-items: center; gap: 6px; height: 30px; padding: 0 11px; border-radius: 7px; font-size: 12.5px; font-weight: 600; transition: background .15s; }
  & button:hover { background: color-mix(in oklch, var(--apv-photos-accent) 14%, transparent); }
  & button:disabled { opacity: .4; pointer-events: none; }
  & button[data-act="clear-sel"] { width: 30px; padding: 0; justify-content: center; }
  & .is-danger { color: oklch(0.55 0.19 25); }
  & svg { width: 16px; height: 16px; }
}
.apv-photos[data-selecting="true"] .apv-photos-selbar { height: 46px; border-bottom: 1px solid var(--apv-photos-line); }
.apv-photos .apv-photos-scroll { position: relative; min-height: 0; overflow-y: auto; overflow-x: hidden; overscroll-behavior: contain; scrollbar-width: thin; scrollbar-color: var(--apv-photos-line2) transparent; padding: 0 20px 28px; }
.apv-photos .apv-photos-sec { position: relative; }
.apv-photos .apv-photos-sh {
  position: sticky; top: 0; z-index: 3; display: flex; align-items: baseline; gap: 10px; padding: 14px 0 10px; margin: 0 -20px; padding-inline: 20px;
  background: linear-gradient(var(--apv-photos-paper) 70%, color-mix(in oklch, var(--apv-photos-paper) 0%, transparent));
  flex-wrap: wrap;
  & h3 { font-size: clamp(16px, 1.8cqi, 20px); font-weight: 800; letter-spacing: -.03em; white-space: nowrap; }
  & small { flex: 1 1 auto; min-width: 0; font-size: 12px; color: var(--apv-photos-mute); font-variant-numeric: tabular-nums; }
  & button { margin-left: auto; white-space: nowrap; font-size: 12px; font-weight: 650; color: var(--apv-photos-accent); opacity: 0; transition: opacity .2s; }
}
.apv-photos .apv-photos-sec:hover .apv-photos-sh button, .apv-photos[data-selecting="true"] .apv-photos-sh button, .apv-photos .apv-photos-sh button:focus-visible { opacity: 1; }
.apv-photos .apv-photos-rows { position: relative; }

.apv-photos .apv-photos-ph {
  position: absolute; border-radius: 3px; overflow: hidden; padding: 0; cursor: zoom-in; transform-origin: 0 0;
  background: linear-gradient(110deg, var(--apv-photos-side) 30%, color-mix(in oklch, var(--apv-photos-side) 60%, white) 50%, var(--apv-photos-side) 70%) 0 0 / 300% 100%;
  animation: apv-photos-shimmer 1.4s linear infinite;
  & canvas { position: absolute; inset: 0; width: 100%; height: 100%; display: block; opacity: 0; filter: blur(8px) saturate(.4); transition: opacity .5s, filter .8s var(--apv-photos-ease), scale .35s var(--apv-photos-spring), border-radius .35s; }
  &.is-dev { animation: none; background: var(--apv-photos-side); }
  &.is-dev canvas { opacity: 1; filter: none; }
  & .apv-photos-chk {
    position: absolute; top: 6px; left: 6px; z-index: 2; display: grid; place-items: center; width: 22px; height: 22px; border-radius: 50%;
    border: 1.5px solid oklch(1 0 0 / .9); background: oklch(0 0 0 / .18); color: transparent; opacity: 0; transform: scale(.8);
    transition: opacity .2s, transform .3s var(--apv-photos-spring), background .2s; box-shadow: 0 1px 4px oklch(0 0 0 / .3);
  }
  & .apv-photos-chk svg { width: 13px; height: 13px; stroke-width: 2.6; }
  & .apv-photos-fav { position: absolute; left: 6px; bottom: 5px; z-index: 2; width: 16px; height: 16px; color: white; fill: white; filter: drop-shadow(0 1px 3px oklch(0 0 0 / .5)); opacity: 0; transform: scale(.5); transition: opacity .2s, transform .35s var(--apv-photos-spring); }
  &.is-fav .apv-photos-fav { opacity: 1; transform: none; }
  &:hover .apv-photos-chk, &:focus-visible .apv-photos-chk { opacity: 1; transform: none; }
  &:focus-visible { outline-offset: 2px; z-index: 2; }
  &[aria-selected="true"] { background: var(--apv-photos-tint); }
  &[aria-selected="true"] canvas { scale: .9; border-radius: 3px; }
  &[aria-selected="true"] .apv-photos-chk { opacity: 1; transform: none; background: var(--apv-photos-accent); color: white; border-color: white; }
  &.is-lift { visibility: hidden; }
}
.apv-photos[data-selecting="true"] .apv-photos-ph { cursor: pointer; }
.apv-photos[data-selecting="true"] .apv-photos-ph .apv-photos-chk { opacity: 1; transform: none; }
@supports (animation-timeline: view()) {
  .apv-photos .apv-photos-ph.is-dev {
    animation: apv-photos-enter linear both; animation-timeline: view(); animation-range: entry 0% entry 60%;
  }
}
.apv-photos .apv-photos-empty { padding: 60px 20px; text-align: center; color: var(--apv-photos-mute); text-wrap: balance;
  & b { display: block; color: var(--apv-photos-ink); font-size: 15px; margin-bottom: 4px; }
}

/* ── lightbox ── */
.apv-photos .apv-photos-lb {
  position: absolute; inset: 0; z-index: 30; display: grid; grid-template-columns: minmax(0, 1fr) auto; grid-template-rows: auto minmax(0, 1fr); grid-template-areas: "bar bar" "stage info";
  &[hidden] { display: none; }
}
.apv-photos .apv-photos-lbbg { position: absolute; inset: 0; background: oklch(0.13 0.005 260); opacity: 0; transition: opacity .35s; }
.apv-photos .apv-photos-lb.is-open .apv-photos-lbbg { opacity: 1; }
.apv-photos .apv-photos-stage { grid-area: stage; position: relative; min-width: 0; min-height: 0; margin: 8px 64px 24px;
  & canvas { position: absolute; display: block; transform-origin: 0 0; box-shadow: 0 30px 60px -20px oklch(0 0 0 / .6); }
}
.apv-photos .apv-photos-lbbar {
  grid-area: bar; position: relative; z-index: 2; display: flex; align-items: center; gap: 6px; padding: 10px 14px; color: oklch(0.96 0 0);
  opacity: 0; transform: translateY(-6px); transition: opacity .3s .1s, transform .4s .1s var(--apv-photos-ease);
  & > button { display: grid; place-items: center; width: 34px; height: 34px; border-radius: 50%; transition: background .15s; }
  & > button:hover { background: oklch(1 0 0 / .12); }
  & > button[aria-pressed="true"] { color: oklch(0.75 0.16 20); }
  & > button[aria-pressed="true"] svg { fill: currentColor; }
  & > button[data-act="lb-info"][aria-pressed="true"] { color: oklch(0.96 0 0); background: oklch(1 0 0 / .16); }
  & > button[data-act="lb-info"][aria-pressed="true"] svg { fill: none; }
  & .apv-photos-lbt { flex: 1; min-width: 0; display: grid; }
  & b { font-weight: 700; font-size: 13.5px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
  & small { font-size: 11.5px; color: oklch(0.75 0 0); font-variant-numeric: tabular-nums; }
  & output { font: 500 11.5px ui-monospace, Menlo, monospace; color: oklch(0.7 0 0); margin-right: 8px; font-variant-numeric: tabular-nums; }
}
.apv-photos .apv-photos-nav-btn {
  position: absolute; z-index: 3; top: 50%; display: grid; place-items: center; width: 40px; height: 40px; margin-top: -20px; border-radius: 50%; color: white; background: oklch(1 0 0 / .1);
  opacity: 0; transition: opacity .3s .1s, background .15s;
  &[data-dir="-1"] { left: 14px; } &[data-dir="1"] { right: 14px; }
  &:hover { background: oklch(1 0 0 / .22); }
  &:disabled { visibility: hidden; }
}
.apv-photos .apv-photos-lb.is-open {
  & .apv-photos-lbbar { opacity: 1; transform: none; }
  & .apv-photos-nav-btn { opacity: 1; }
}
.apv-photos .apv-photos-lb.is-info .apv-photos-nav-btn[data-dir="1"] { right: 284px; }
.apv-photos .apv-photos-info {
  grid-area: info; position: relative; z-index: 2; width: 0; overflow: hidden; color: oklch(0.94 0 0); transition: width .45s var(--apv-photos-ease);
  & > div { width: 270px; padding: 6px 18px 20px 4px; display: grid; gap: 14px; opacity: 0; transform: translateX(16px); transition: opacity .3s, transform .45s var(--apv-photos-ease); }
  & h3 { font-size: 15px; font-weight: 750; letter-spacing: -.02em; }
  & p { font-size: 12px; color: oklch(0.72 0 0); }
  & dl { display: grid; grid-template-columns: auto 1fr; gap: 6px 12px; font-size: 12px; }
  & dt { color: oklch(0.65 0 0); }
  & dd { font-variant-numeric: tabular-nums; text-align: right; }
  & .apv-photos-exif { display: grid; grid-template-columns: repeat(4, 1fr); border-radius: 9px; overflow: hidden; background: oklch(1 0 0 / .07); }
  & .apv-photos-exif span { display: grid; place-items: center; padding: 8px 2px; font: 600 11.5px ui-monospace, Menlo, monospace; font-variant-numeric: tabular-nums; border-left: 1px solid oklch(1 0 0 / .08); }
  & .apv-photos-exif span:first-child { border: 0; }
  & svg.apv-photos-hist { width: 100%; height: 64px; display: block; stroke: none; }
  & .apv-photos-tags { display: flex; flex-wrap: wrap; gap: 5px; }
  & .apv-photos-tags span { padding: 2px 8px; border-radius: 999px; font-size: 11px; background: oklch(1 0 0 / .09); }
}
.apv-photos .apv-photos-lb.is-info .apv-photos-info { width: 270px; }
.apv-photos .apv-photos-lb.is-info .apv-photos-info > div { opacity: 1; transform: none; }

