  .apv-photos .apv-photos-nav button { justify-content: center; padding: 9px; }
  .apv-photos .apv-photos-selhint { display: none; }
  .apv-photos .apv-photos-lb.is-info .apv-photos-info { width: 240px; }
  .apv-photos .apv-photos-info > div { width: 240px; }
  .apv-photos .apv-photos-lb.is-info .apv-photos-nav-btn[data-dir="1"] { right: 254px; }
}
@container (max-width: 759px) {
  .apv-photos .apv-photos-app { grid-template-columns: minmax(0, 1fr); grid-template-rows: minmax(0, 1fr) auto; grid-template-areas: "main" "side"; }
  .apv-photos .apv-photos-side { flex-direction: row; padding: 6px 8px; border-right: 0; border-top: 1px solid var(--apv-photos-line); overflow-x: auto; }
  .apv-photos .apv-photos-brand { display: none; }
  .apv-photos .apv-photos-nav { display: flex; gap: 6px; }
  .apv-photos .apv-photos-nav button { flex: none; width: auto; padding: 6px 12px; border-radius: 999px; box-shadow: inset 0 0 0 1px var(--apv-photos-line2); }
