  .apv-photos .apv-photos-search { order: 3; width: 100%; }
  .apv-photos .apv-photos-zoom { display: none; }
  .apv-photos .apv-photos-scroll { padding: 0 12px 20px; }
  .apv-photos .apv-photos-sh { margin: 0 -12px; padding-inline: 12px; }
  .apv-photos .apv-photos-selbar { padding: 0 10px; gap: 4px; }
  .apv-photos .apv-photos-selbar button span { display: none; }
