  .apv-photos .apv-photos-info > div { width: auto; padding: 4px 16px 16px; }
  .apv-photos .apv-photos-nav-btn { display: none; }
}

@keyframes apv-photos-shimmer { to { background-position: -300% 0; } }
@keyframes apv-photos-enter { from { opacity: .35; scale: .94; } }

@media (prefers-reduced-motion: reduce) {
  .apv-photos .apv-photos-ph, .apv-photos .apv-photos-ph.is-dev { animation: none; }
