  .apv-photos .apv-photos-selbar, .apv-photos .apv-photos-info, .apv-photos .apv-photos-info > div { transition: none; }
  .apv-photos .apv-photos-lbbar, .apv-photos .apv-photos-toast, .apv-photos .apv-photos-toast.is-on, .apv-photos .apv-photos-menu { transform: none; transition: opacity .2s; }
}

