/* Sunprint photos. Photos are painted procedurally (lake, coast, bokeh,
   flower, table, forest, facade); EXIF is written to agree with the picture
   and the info panel's histogram is measured from the painted pixels.
   The justified layout is computed per section; every relayout (zoom,
   resize, delete) is a FLIP with translate + uniform scale. */
const doc = root.ownerDocument;
const $ = (s, el = root) => el.querySelector(s);
const $$ = (s, el = root) => [...el.querySelectorAll(s)];
const RM = matchMedia('(prefers-reduced-motion: reduce)');
const SPRING = 'linear(0, 0.1 4%, 0.38 10%, 0.74 17%, 0.96 24%, 1.04 30%, 1.05 35%, 1.02 44%, 1 55%, 1)';
const EASE = 'cubic-bezier(.2,.8,.2,1)';
const esc = s => String(s == null ? '' : s).replace(/[&<>"']/g, c => '&#' + c.charCodeAt(0) + ';');
const clamp = (v, a, b) => Math.min(b, Math.max(a, v));
const A = (c, a) => c.replace(')', ' / ' + a + ')');
const ICON = {
  all: '<svg viewBox="0 0 24 24" aria-hidden="true"><rect x="3.5" y="3.5" width="7" height="7" rx="1.5"/><rect x="13.5" y="3.5" width="7" height="7" rx="1.5"/><rect x="3.5" y="13.5" width="7" height="7" rx="1.5"/><rect x="13.5" y="13.5" width="7" height="7" rx="1.5"/></svg>',
  heart: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 19.5s-7.5-4.4-7.5-10A4.2 4.2 0 0 1 12 7.3a4.2 4.2 0 0 1 7.5 2.2c0 5.6-7.5 10-7.5 10Z"/></svg>',
  album: '<svg viewBox="0 0 24 24" aria-hidden="true"><rect x="3.5" y="6" width="17" height="13" rx="2"/><path d="M7 3.5h10M3.5 15l4.5-4 4 3.5 3-2.5 5 4"/></svg>',
  trash: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 7h14M10 7V4.5h4V7M7 7l1 12.5h8L17 7"/></svg>',
  check: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m5 12.5 4.5 4.5L19 7.5"/></svg>',
  pin: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 21s6.5-6 6.5-11a6.5 6.5 0 0 0-13 0c0 5 6.5 11 6.5 11Z"/><circle cx="12" cy="10" r="2.3"/></svg>',
};

/* ── painters ── */
const rng = seed => () => { seed |= 0; seed = seed + 0x6D2B79F5 | 0; let t = Math.imul(seed ^ seed >>> 15, 1 | seed); t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t; return ((t ^ t >>> 14) >>> 0) / 4294967296; };
const O = s => 'oklch(' + s + ')';
const LG = (ctx, x0, y0, x1, y1, stops) => { const g = ctx.createLinearGradient(x0, y0, x1, y1); stops.forEach(([o, c]) => g.addColorStop(o, c)); return g; };
const RG = (ctx, x, y, r0, r1, stops) => { const g = ctx.createRadialGradient(x, y, r0, x, y, r1); stops.forEach(([o, c]) => g.addColorStop(o, c)); return g; };
function ridge(ctx, w, h, R, base, amp, rough, col) {
  const n = 90, ph = [R() * 6, R() * 6, R() * 6, R() * 6], f0 = 2.2 + R() * 1.6;
  ctx.beginPath(); ctx.moveTo(0, h);
  for (let i = 0; i <= n; i++) {
    const u = i / n;
    const y = .5 * Math.abs(Math.sin(u * f0 + ph[0])) + .28 * Math.abs(Math.sin(u * 6.3 + ph[1])) * rough + .12 * Math.abs(Math.sin(u * 15.1 + ph[2])) * rough + .05 * Math.sin(u * 41 + ph[3]) * rough;
    ctx.lineTo(u * w, base - amp * y);
  }
  ctx.lineTo(w, h); ctx.closePath(); ctx.fillStyle = col; ctx.fill();
}
const PAINT = {
  lake(ctx, w, h, R, v) {
    const P = [[O('0.5 0.08 250'), O('0.86 0.09 62'), O('0.96 0.08 88'), O('0.62 0.04 255'), O('0.3 0.03 245')],
               [O('0.36 0.07 262'), O('0.74 0.06 20'), O('0.92 0.04 60'), O('0.5 0.04 270'), O('0.24 0.03 265')],
               [O('0.68 0.1 238'), O('0.9 0.03 220'), O('0.99 0.01 90'), O('0.6 0.05 200'), O('0.36 0.05 160')]][v % 3];
    const hz = h * (.52 + R() * .08), sx = w * (.3 + R() * .4);
    const sky = () => {
      ctx.fillStyle = LG(ctx, 0, 0, 0, hz, [[0, P[0]], [1, P[1]]]); ctx.fillRect(0, 0, w, hz);
      ctx.fillStyle = RG(ctx, sx, hz - h * .06, 0, h * .5, [[0, A(P[2], .9)], [.15, A(P[2], .35)], [1, A(P[2], 0)]]); ctx.fillRect(0, 0, w, hz);
      const R2 = rng(v * 13 + 7);
      ridge(ctx, w, hz, R2, hz, h * .2, 1, P[3]); ridge(ctx, w, hz, R2, hz, h * .11, .6, P[4]);
    };
    sky();
    ctx.save(); ctx.beginPath(); ctx.rect(0, hz, w, h - hz); ctx.clip(); ctx.translate(0, hz * 2); ctx.scale(1, -1); sky(); ctx.restore();
    ctx.fillStyle = LG(ctx, 0, hz, 0, h, [[0, A(P[4], .25)], [1, A(P[4], .75)]]); ctx.fillRect(0, hz, w, h - hz);
    for (let i = 0; i < 22; i++) { const y = hz + 3 + Math.pow(R(), 1.8) * (h - hz) * .85, lw = w * (.03 + R() * .16); ctx.fillStyle = A(P[2], .1 + R() * .16); ctx.fillRect(R() * w - lw / 2, y, lw, Math.max(1, h * .0025)); }
    ctx.fillStyle = P[4]; ctx.beginPath(); ctx.moveTo(0, h); ctx.lineTo(0, h * .9); ctx.quadraticCurveTo(w * .3, h * .86, w * .55, h * .95); ctx.lineTo(w, h * .97); ctx.lineTo(w, h); ctx.fill();
  },
  coast(ctx, w, h, R, v) {
    const P = [[O('0.78 0.06 225'), O('0.92 0.02 210'), O('0.55 0.09 205'), O('0.3 0.06 220'), O('0.42 0.04 60')],
               [O('0.7 0.02 240'), O('0.86 0.01 240'), O('0.5 0.04 215'), O('0.28 0.03 225'), O('0.36 0.02 90')]][v % 2];
    const hz = h * (.38 + R() * .1);
    ctx.fillStyle = LG(ctx, 0, 0, 0, hz, [[0, P[0]], [1, P[1]]]); ctx.fillRect(0, 0, w, hz);
    ctx.fillStyle = LG(ctx, 0, hz, 0, h, [[0, P[2]], [1, P[3]]]); ctx.fillRect(0, hz, w, h - hz);
    for (let i = 0; i < 5; i++) { ctx.fillStyle = A(P[1], .5); ctx.beginPath(); ctx.ellipse(R() * w, hz * (.2 + R() * .5), w * (.08 + R() * .1), h * .02, 0, 0, 7); ctx.fill(); }
    const side = R() < .5, cx = side ? w : 0, dir = side ? -1 : 1;
    ctx.fillStyle = P[4]; ctx.beginPath(); ctx.moveTo(cx, hz - h * .16); ctx.lineTo(cx + dir * w * .18, hz - h * .12); ctx.lineTo(cx + dir * w * .3, hz + h * .1); ctx.lineTo(cx + dir * w * .42, h); ctx.lineTo(cx, h); ctx.fill();
    ctx.fillStyle = A(P[3], .5); ctx.beginPath(); ctx.moveTo(cx + dir * w * .18, hz - h * .12); ctx.lineTo(cx + dir * w * .3, hz + h * .1); ctx.lineTo(cx + dir * w * .42, h); ctx.lineTo(cx + dir * w * .32, h); ctx.fill();
    ctx.strokeStyle = O('0.97 0.01 220 / .55'); ctx.lineWidth = Math.max(1, h * .006);
    for (let k = 0; k < 6; k++) { const y0 = hz + (h - hz) * (.35 + k * .11); ctx.beginPath(); for (let x = 0; x <= w; x += 6) { const y = y0 + Math.sin(x / w * 9 + k * 2 + R()) * h * .008; x ? ctx.lineTo(x, y) : ctx.moveTo(x, y); } ctx.globalAlpha = .3 + k * .1; ctx.stroke(); }
    ctx.globalAlpha = 1;
  },
  bokeh(ctx, w, h, R, v) {
    const pals = [[O('0.82 0.15 70'), O('0.7 0.18 40'), O('0.78 0.12 180'), O('0.9 0.08 95')], [O('0.75 0.18 25'), O('0.85 0.12 80'), O('0.7 0.14 330'), O('0.9 0.05 230')]][v % 2];
    ctx.fillStyle = LG(ctx, 0, 0, 0, h, [[0, O('0.16 0.02 260')], [1, O('0.22 0.03 40')]]); ctx.fillRect(0, 0, w, h);
    ctx.globalCompositeOperation = 'lighter';
    const D = Math.max(w, h);
    for (let i = 0; i < 70; i++) {
      const x = R() * w, y = h * (.15 + R() * .8), r = D * (.015 + Math.pow(R(), 2.2) * .09), c = pals[Math.floor(R() * pals.length)], a = .12 + R() * .3;
      ctx.fillStyle = RG(ctx, x, y, r * .2, r, [[0, A(c, a * .7)], [.85, A(c, a)], [1, A(c, 0)]]); ctx.beginPath(); ctx.arc(x, y, r, 0, 7); ctx.fill();
    }
    for (let i = 0; i < 14; i++) { const x = R() * w, y = h * (.4 + R() * .5); ctx.fillStyle = A(pals[0], .9); ctx.beginPath(); ctx.arc(x, y, Math.max(1, D * .003), 0, 7); ctx.fill(); }
