  },
  flower(ctx, w, h, R, v) {
    const pet = [O('0.78 0.12 350'), O('0.88 0.15 95'), O('0.95 0.02 90'), O('0.72 0.15 40')][v % 4];
    ctx.fillStyle = LG(ctx, 0, 0, w, h, [[0, O('0.55 0.09 135')], [1, O('0.32 0.07 150')]]); ctx.fillRect(0, 0, w, h);
    const D = Math.max(w, h);
