    const cx = w * (.38 + R() * .24), cy = h * (.4 + R() * .2), r = Math.min(w, h) * (.26 + R() * .08), n = 12 + Math.floor(R() * 6);
    for (let layer = 0; layer < 2; layer++) for (let i = 0; i < n; i++) {
      const a = i / n * 6.283 + layer * .26 + R() * .05, len = r * (layer ? .78 : 1);
      ctx.save(); ctx.translate(cx, cy); ctx.rotate(a);
      ctx.fillStyle = LG(ctx, 0, 0, len, 0, [[0, A(pet, .95)], [.7, pet], [1, A(pet, .75)]]);
      ctx.beginPath(); ctx.ellipse(len * .52, 0, len * .52, len * .17, 0, 0, 7); ctx.fill();
      ctx.strokeStyle = O('0.4 0.05 20 / .12'); ctx.lineWidth = 1; ctx.stroke(); ctx.restore();
    }
    ctx.fillStyle = RG(ctx, cx, cy, 0, r * .24, [[0, O('0.62 0.14 70')], [1, O('0.42 0.1 50')]]); ctx.beginPath(); ctx.arc(cx, cy, r * .22, 0, 7); ctx.fill();
    ctx.fillStyle = O('0.85 0.14 90 / .8'); for (let i = 0; i < 40; i++) { const a = R() * 6.28, d = Math.sqrt(R()) * r * .2; ctx.fillRect(cx + Math.cos(a) * d, cy + Math.sin(a) * d, 1.5, 1.5); }
  },
  table(ctx, w, h, R, v) {
    const wood = [O('0.62 0.07 60'), O('0.78 0.03 80'), O('0.42 0.05 50')][v % 3];
    ctx.fillStyle = wood; ctx.fillRect(0, 0, w, h);
    for (let i = 0; i < 40; i++) { ctx.fillStyle = A(O('0.3 0.04 50'), .04 + R() * .06); ctx.fillRect(0, R() * h, w, 1 + R() * 3); }
    const D = Math.min(w, h), px = w * (.42 + R() * .16), py = h * (.45 + R() * .1), pr = D * .3;
    ctx.fillStyle = O('0.2 0.02 60 / .25'); ctx.beginPath(); ctx.arc(px + D * .02, py + D * .03, pr, 0, 7); ctx.fill();
    ctx.fillStyle = O('0.97 0.005 90'); ctx.beginPath(); ctx.arc(px, py, pr, 0, 7); ctx.fill();
    ctx.strokeStyle = O('0.85 0.01 90'); ctx.lineWidth = D * .012; ctx.beginPath(); ctx.arc(px, py, pr * .72, 0, 7); ctx.stroke();
    const food = [O('0.7 0.15 40'), O('0.62 0.15 140'), O('0.85 0.12 95'), O('0.55 0.17 25'), O('0.9 0.04 80')];
    for (let i = 0; i < 9; i++) { const a = R() * 6.28, d = Math.sqrt(R()) * pr * .5, r = pr * (.1 + R() * .14); ctx.fillStyle = food[Math.floor(R() * food.length)]; ctx.beginPath(); ctx.ellipse(px + Math.cos(a) * d, py + Math.sin(a) * d, r, r * (.6 + R() * .4), R() * 3, 0, 7); ctx.fill(); }
    const cr = D * .1, cx = clamp(px + pr * 1.35 * (R() < .5 ? -1 : 1), cr * 1.3, w - cr * 1.3), cy = clamp(py - pr * .7, cr * 1.3, h - cr * 1.3);
    ctx.fillStyle = O('0.2 0.02 60 / .25'); ctx.beginPath(); ctx.arc(cx + D * .015, cy + D * .02, cr, 0, 7); ctx.fill();
    ctx.fillStyle = O('0.95 0.01 90'); ctx.beginPath(); ctx.arc(cx, cy, cr, 0, 7); ctx.fill();
    ctx.fillStyle = O('0.38 0.06 50'); ctx.beginPath(); ctx.arc(cx, cy, cr * .74, 0, 7); ctx.fill();
    ctx.fillStyle = O('0.75 0.05 70 / .7'); ctx.beginPath(); ctx.arc(cx - cr * .15, cy - cr * .1, cr * .3, 0, 7); ctx.fill();
    ctx.fillStyle = LG(ctx, 0, 0, w, h, [[0, O('1 0 0 / .14')], [.5, O('1 0 0 / 0')], [1, O('0 0 0 / .16')]]); ctx.fillRect(0, 0, w, h);
  },
  forest(ctx, w, h, R, v) {
