    '<svg class="apv-photos-hist" viewBox="0 0 240 64" preserveAspectRatio="none" aria-label="Luminance histogram"><path d="' + path + '" fill="oklch(0.9 0 0 / .55)"/></svg>' +
    '<div class="apv-photos-exif" aria-label="Exposure"><span>' + mm + ' mm</span><span>&fnof;/' + f + '</span><span>' + sh + '</span><span>ISO ' + x.iso + '</span></div>' +
    '<dl><dt>Camera</dt><dd>' + esc(cam) + '</dd><dt>Lens</dt><dd>' + esc(lens) + '</dd><dt>Size</dt><dd>' + px + ' &times; ' + py + '</dd><dt>File</dt><dd>' + MB(x).toFixed(1) + ' MB</dd><dt>Albums</dt><dd>' + (x.albums.map(a => ALBUMS.find(b => b.id === a).t).join(', ') || 'None') + '</dd></dl>' +
    '<div class="apv-photos-tags">' + TAGS[x.p].map(t => '<span>' + t + '</span>').join('') + '</div></div>';
}
function stepLB(d) {
  const j = S.lb + d; if (j < 0 || j >= lbList.length) return;
  S.lb = j; const x = PHI[lbList[j]];
  paintBig(x); lbChrome();
