  const done = () => { LB.hidden = true; S.lb = -1; if (thumb) { thumb.classList.remove('is-lift'); focusPh(thumb, false); } };
  if (thumb && !RM.matches) {
    const sc = $('[data-scroll]'), t0 = thumb.getBoundingClientRect(), srect = sc.getBoundingClientRect();
    if (t0.top < srect.top || t0.bottom > srect.bottom) sc.scrollTop += t0.top - srect.top - 60;
