function setInfo(on) { S.info = on; LB.classList.toggle('is-info', on); $('[data-act="lb-info"]').setAttribute('aria-pressed', on); if (on) renderInfo(PHI[lbList[S.lb]]); }

/* ── focus movement across the justified grid ── */
function focusPh(el, reveal = true) {
  $$('.apv-photos-ph').forEach(x => x.tabIndex = -1); el.tabIndex = 0; el.focus({ preventScroll: true });
  if (!reveal) return;
