  if (best) focusPh(best);
}

/* ── events ── */
root.addEventListener('click', e => {
  const b = e.target.closest('button'); if (!b || !root.contains(b)) { closeMenu(); return; }
  if (!b.closest('[data-menu]') && b.dataset.act !== 'album-sel') closeMenu();
  if (b.classList.contains('apv-photos-ph')) {
    const id = b.dataset.id;
    if (S.selecting || e.shiftKey || e.metaKey || e.ctrlKey || e.target.closest('[data-chk]')) { clickSelect(b, e); focusPh(b, false); }
    else openLB(id);
    return;
  }
  if (b.dataset.view) { S.view = b.dataset.view; S.sel.clear(); setSelecting(false); renderNav(); $('[data-scroll]').scrollTop = 0; render(); return; }
  if (b.dataset.selsec) { $$('.apv-photos-sec[data-sec="' + b.dataset.selsec + '"] .apv-photos-ph').forEach(el => S.sel.add(el.dataset.id)); syncSel(); return; }
  if (b.dataset.album) {
    const a = b.dataset.album, ids = [...S.sel], added = ids.filter(id => !PHI[id].albums.includes(a));
    added.forEach(id => PHI[id].albums.push(a)); closeMenu(); renderNav();
    toast(added.length ? 'Added ' + added.length + ' to ' + ALBUMS.find(x => x.id === a).t : 'Already in ' + ALBUMS.find(x => x.id === a).t, added.length ? () => { added.forEach(id => PHI[id].albums = PHI[id].albums.filter(x => x !== a)); renderNav(); if (S.view === 'album:' + a) render(); } : null);
    return;
  }
  switch (b.dataset.act) {
    case 'select': setSelecting(!S.selecting); break;
    case 'clear-sel': setSelecting(false); break;
    case 'fav-sel': favIds([...S.sel]); break;
    case 'del-sel': removeIds([...S.sel], S.view === 'deleted'); break;
    case 'album-sel': if (menuBtn === b) closeMenu(true); else openMenu(b, ALBUMS.map(a => '<button type="button" role="menuitem" data-album="' + a.id + '">' + ICON.album + esc(a.t) + '<output>' + PH.filter(x => x.albums.includes(a.id) && !S.deleted.includes(x.id)).length + '</output></button>').join('')); break;
    case 'lb-close': closeLB(); break;
    case 'lb-prev': stepLB(-1); break;
    case 'lb-next': stepLB(1); break;
    case 'lb-fav': favIds([lbList[S.lb]]); break;
    case 'lb-info': setInfo(!S.info); break;
    case 'lb-del': { const id = lbList[S.lb]; const restore = S.view === 'deleted'; lbList.splice(S.lb, 1); removeIds([id], restore); if (!lbList.length) { LB.classList.remove('is-open'); LB.hidden = true; S.lb = -1; } else { S.lb = Math.min(S.lb, lbList.length - 1); paintBig(PHI[lbList[S.lb]]); lbChrome(); } break; }
    case 'undo': if (undoFn) { const f = undoFn; undoFn = null; f(); $('[data-toast]').classList.remove('is-on'); } break;
  }
});
$('[data-lbbg]').addEventListener('click', closeLB);
$('[data-stage]').addEventListener('click', e => { if (e.target === e.currentTarget) closeLB(); });

const zoom = $('[data-zoom]');
let zt = 0;
const setZoom = (v, anim) => { S.zoom = clamp(Math.round(v), 88, 280); zoom.value = S.zoom; clearTimeout(zt); if (anim) layout(true); else zt = setTimeout(() => layout(true), 0); };
zoom.addEventListener('input', () => { S.zoom = +zoom.value; layout(false); });
zoom.addEventListener('change', () => layout(false));
$('[data-scroll]').addEventListener('wheel', e => { if (!e.ctrlKey) return; e.preventDefault(); S.zoom = clamp(S.zoom * (1 - e.deltaY * .01), 88, 280); zoom.value = S.zoom; layout(false); }, { passive: false });
const q = $('[data-q]');
q.addEventListener('input', () => { S.q = q.value.trim(); render(); });

root.addEventListener('keydown', e => {
  const k = e.key, tg = e.target, mod = e.metaKey || e.ctrlKey;
  const M = $('[data-menu]');
  if (!M.hidden) { const items = $$('button', M), i = items.indexOf(doc.activeElement); if (k === 'Escape') { e.preventDefault(); closeMenu(true); } else if (k === 'ArrowDown' || k === 'ArrowUp') { e.preventDefault(); items[(i + (k === 'ArrowDown' ? 1 : -1) + items.length) % items.length].focus(); } return; }
  if (S.lb > -1) {
    if (k === 'Escape') { e.preventDefault(); closeLB(); }
    else if (k === 'ArrowLeft' || k === 'ArrowRight') { e.preventDefault(); stepLB(k === 'ArrowRight' ? 1 : -1); }
    else if (k === 'f' || k === 'F') favIds([lbList[S.lb]]);
    else if (k === 'i' || k === 'I') setInfo(!S.info);
    else if (k === 'Delete' || k === 'Backspace') $('[data-act="lb-del"]').click();
    else if (k === ' ') { e.preventDefault(); closeLB(); }
    else if (k === 'Tab') { const f = $$('button:not(:disabled)', LB); const i = f.indexOf(doc.activeElement); if (e.shiftKey && i <= 0) { e.preventDefault(); f[f.length - 1].focus(); } else if (!e.shiftKey && i === f.length - 1) { e.preventDefault(); f[0].focus(); } }
    return;
  }
  if (tg === q) { if (k === 'Escape') { e.preventDefault(); q.value = ''; S.q = ''; render(); root.focus(); } else if (k === 'ArrowDown') { const f = $('.apv-photos-ph'); if (f) { e.preventDefault(); focusPh(f); } } return; }
  if (tg === zoom) return;
  if (mod && (k === 'a' || k === 'A')) { e.preventDefault(); $$('.apv-photos-ph').forEach(el => S.sel.add(el.dataset.id)); syncSel(); return; }
  if (mod && (k === 'z' || k === 'Z')) { if (undoFn) { e.preventDefault(); $('[data-act="undo"]').click(); } return; }
  if (k === 'Escape') { if (S.selecting) { e.preventDefault(); setSelecting(false); } return; }
  if (k === '/') { e.preventDefault(); q.focus(); return; }
