  if (k === '-' || k === '_') { setZoom(S.zoom / 1.2, true); return; }
  const ph = tg.closest && tg.closest('.apv-photos-ph');
  if (!ph) { if (k.startsWith('Arrow')) { const f = $('.apv-photos-ph'); if (f) { e.preventDefault(); focusPh(f); } } return; }
