  if (k === 'x' || k === 'X') { clickSelect(ph, e); return; }
  if (k === 'f' || k === 'F') { favIds(S.sel.size ? [...S.sel] : [ph.dataset.id]); return; }
  if (k === 'Delete' || k === 'Backspace') { e.preventDefault(); const ids = S.sel.size ? [...S.sel] : [ph.dataset.id]; const all = $$('.apv-photos-ph'), i = all.indexOf(ph); removeIds(ids, S.view === 'deleted'); setTimeout(() => { const n = $$('.apv-photos-ph'); if (n.length) focusPh(n[Math.min(i, n.length - 1)]); }, 260); }
