/* Splice: a non-linear editor. Clip bodies (filmstrips, waveforms) are drawn
   on one canvas sized to the visible part of the timeline; the DOM on top of
   it carries labels, selection, trim handles and hit-testing. */
.apv-edit {
  /* re-theme: bg, ink, accent */
  --apv-edit-bg: oklch(0.19 0.006 255);
  --apv-edit-ink: oklch(0.93 0.006 255);
  --apv-edit-accent: oklch(0.87 0.17 96);
  --apv-edit-panel: color-mix(in oklch, var(--apv-edit-bg) 92%, var(--apv-edit-ink));
  --apv-edit-deep: color-mix(in oklch, var(--apv-edit-bg) 70%, black);
  --apv-edit-line: color-mix(in oklch, var(--apv-edit-ink) 10%, transparent);
  --apv-edit-line2: color-mix(in oklch, var(--apv-edit-ink) 18%, transparent);
  --apv-edit-mute: color-mix(in oklch, var(--apv-edit-ink) 62%, var(--apv-edit-bg));
  --apv-edit-faint: color-mix(in oklch, var(--apv-edit-ink) 38%, var(--apv-edit-bg));
  --apv-edit-ease: cubic-bezier(.2, .8, .2, 1);
  --apv-edit-spring: linear(0, 0.1 4%, 0.38 10%, 0.74 17%, 0.96 24%, 1.04 30%, 1.05 35%, 1.02 44%, 1 55%, 1);

  position: relative; width: 100%; height: var(--apv-edit-h, 680px);
  container-type: inline-size; overflow: clip; isolation: isolate; box-sizing: border-box;
  background: var(--apv-edit-bg); color: var(--apv-edit-ink); color-scheme: dark; accent-color: var(--apv-edit-accent);
  border-radius: 12px; font: 12.5px/1.4 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-tap-highlight-color: transparent; user-select: none;

  & *, & *::before, & *::after { box-sizing: border-box; }
  &:focus { outline: none; }
  & :focus-visible { outline: 2px solid var(--apv-edit-accent); outline-offset: 1px; }
  & button, & input { font: inherit; color: inherit; }
  & button { cursor: pointer; background: none; border: 0; padding: 0; }
  & h3, & p, & ul, & dl, & dd { margin: 0; padding: 0; }
  & ul { list-style: none; }
  & svg { width: 17px; height: 17px; fill: none; stroke: currentColor; stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; flex: none; }
  & .apv-edit-fill { fill: currentColor; stroke: none; }
  & kbd { font: 600 9.5px/1 ui-monospace, Menlo, monospace; padding: 2px 4px; min-width: 16px; display: inline-block; text-align: center; border-radius: 3px; background: color-mix(in oklch, var(--apv-edit-ink) 10%, transparent); color: var(--apv-edit-mute); }
  & output { font-variant-numeric: tabular-nums; }
}
.apv-edit .apv-edit-app {
  height: 100%; display: grid; grid-template-columns: 210px minmax(0, 1fr) 240px; grid-template-rows: auto minmax(0, 1fr) auto;
  grid-template-areas: "bar bar bar" "bin mon insp" "tl tl tl";
}

/* ── top bar ── */
.apv-edit .apv-edit-bar { grid-area: bar; display: flex; align-items: center; gap: 12px; padding: 8px 12px; border-bottom: 1px solid var(--apv-edit-line); background: var(--apv-edit-deep); }
.apv-edit .apv-edit-proj { display: flex; align-items: center; gap: 9px; min-width: 0; margin-right: auto;
  & .apv-edit-logo { display: grid; place-items: center; width: 28px; height: 28px; border-radius: 7px; background: var(--apv-edit-accent); color: var(--apv-edit-deep); }
  & .apv-edit-logo svg { width: 16px; height: 16px; stroke-width: 2.4; }
  & > span:last-child { display: grid; min-width: 0; }
  & b { font-weight: 700; font-size: 13px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & small { font-size: 11px; color: var(--apv-edit-faint); }
}
.apv-edit .apv-edit-tools {
  display: flex; align-items: center; gap: 2px;
  & button { display: flex; align-items: center; gap: 5px; height: 30px; padding: 0 8px; border-radius: 6px; color: var(--apv-edit-mute); font-size: 12px; font-weight: 600; transition: background .15s, color .15s; }
  & button:hover { background: var(--apv-edit-line); color: var(--apv-edit-ink); }
  & button[aria-pressed="true"] { background: color-mix(in oklch, var(--apv-edit-accent) 18%, transparent); color: var(--apv-edit-accent); }
  & button:disabled { opacity: .35; pointer-events: none; }
  & .apv-edit-sep { width: 1px; height: 18px; margin: 0 4px; background: var(--apv-edit-line2); }
}
.apv-edit .apv-edit-tc { font: 600 15px ui-monospace, Menlo, monospace; letter-spacing: .02em; color: var(--apv-edit-accent); padding: 4px 10px; border-radius: 6px; background: oklch(0 0 0 / .35); }
.apv-edit .apv-edit-export { height: 30px; padding: 0 14px; border-radius: 7px; font-weight: 700; background: var(--apv-edit-ink); color: var(--apv-edit-bg); transition: transform .3s var(--apv-edit-spring);
  &:active { transform: scale(.95); }
}

/* ── media bin ── */
.apv-edit .apv-edit-bin { grid-area: bin; min-height: 0; display: grid; grid-template-rows: auto minmax(0, 1fr); border-right: 1px solid var(--apv-edit-line); background: var(--apv-edit-panel);
  & header { display: flex; align-items: baseline; gap: 8px; padding: 10px 12px 6px; }
  & h3, .apv-edit-insp h3 { font-size: 10.5px; font-weight: 750; letter-spacing: .14em; text-transform: uppercase; color: var(--apv-edit-mute); }
  & small { font-size: 11px; color: var(--apv-edit-faint); }
}
.apv-edit .apv-edit-media { overflow: auto; padding: 2px 8px 10px; scrollbar-width: thin; scrollbar-color: var(--apv-edit-line2) transparent; }
.apv-edit .apv-edit-src {
  display: grid; grid-template-columns: 64px minmax(0, 1fr); gap: 2px 10px; align-items: center; padding: 6px; border-radius: 7px; cursor: grab; touch-action: none;
  transition: background .15s;
  & canvas { grid-row: 1 / 3; width: 64px; height: 36px; border-radius: 4px; display: block; background: oklch(0 0 0 / .4); }
  & b { font-weight: 600; font-size: 12px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & small { font: 500 10.5px ui-monospace, Menlo, monospace; color: var(--apv-edit-faint); display: flex; gap: 6px; align-items: center; }
  & small i { width: 7px; height: 7px; border-radius: 2px; background: var(--c); }
  &:hover, &:focus-visible { background: var(--apv-edit-line); }
  &:focus-visible { outline-offset: -2px; }
  &.is-used b::after { content: " \2022"; color: var(--apv-edit-accent); }
}
.apv-edit .apv-edit-ghost { position: absolute; z-index: 40; pointer-events: none; height: 30px; border-radius: 4px; background: color-mix(in oklch, var(--c) 70%, transparent); outline: 1.5px solid var(--apv-edit-accent); font-size: 11px; font-weight: 650; padding: 6px 8px; white-space: nowrap; overflow: hidden; }

/* ── monitor ── */
.apv-edit .apv-edit-mon { grid-area: mon; min-width: 0; min-height: 0; display: grid; grid-template-rows: minmax(0, 1fr) auto; padding: 10px 14px 6px; gap: 6px; }
.apv-edit .apv-edit-screen {
  position: relative; min-height: 0; display: grid; place-items: center; container-type: size;
  & canvas { width: min(100cqw, 100cqh * 16 / 9); aspect-ratio: 16 / 9; display: block; background: black; border-radius: 3px; box-shadow: 0 0 0 1px var(--apv-edit-line); }
}
.apv-edit .apv-edit-shuttle { position: absolute; top: 10px; left: 50%; translate: -50% 0; padding: 3px 9px; border-radius: 5px; background: oklch(0 0 0 / .6); color: var(--apv-edit-accent); font: 700 11px ui-monospace, Menlo, monospace; opacity: 0; transition: opacity .2s;
  &:not(:empty) { opacity: 1; }
}
.apv-edit .apv-edit-meter {
  position: absolute; right: 0; top: 0; bottom: 0; width: 12px; display: flex; gap: 2px;
  & i { flex: 1; border-radius: 2px; background: linear-gradient(to top, oklch(0.72 0.17 145) 0 60%, var(--apv-edit-accent) 60% 85%, oklch(0.65 0.21 28) 85%); transform-origin: bottom; transform: scaleY(var(--v, 0)); transition: transform .08s linear; }
}
.apv-edit .apv-edit-transport {
  display: grid; grid-template-columns: 1fr auto 1fr; align-items: center; gap: 10px;
  & > output { font: 500 12px ui-monospace, Menlo, monospace; color: var(--apv-edit-mute); }
  & > output:last-child { text-align: right; color: var(--apv-edit-faint); }
}
.apv-edit .apv-edit-tbtns { display: flex; align-items: center; gap: 2px;
  & button { position: relative; display: grid; place-items: center; width: 32px; height: 32px; border-radius: 50%; color: var(--apv-edit-mute); transition: background .15s, color .15s, transform .3s var(--apv-edit-spring); }
  & button:hover { background: var(--apv-edit-line); color: var(--apv-edit-ink); }
  & button:active { transform: scale(.9); }
  & button kbd { position: absolute; bottom: -4px; right: -2px; font-size: 8px; padding: 1px 3px; min-width: 0; }
  & .apv-edit-play { width: 38px; height: 38px; background: var(--apv-edit-ink); color: var(--apv-edit-bg); }
  & .apv-edit-play:hover { background: var(--apv-edit-accent); color: var(--apv-edit-bg); }
  & .apv-edit-play svg { position: absolute; transition: opacity .15s, transform .3s var(--apv-edit-spring); }
  & .apv-edit-ipa { opacity: 0; transform: scale(.5); }
}
.apv-edit[data-playing="true"] .apv-edit-play {
  & .apv-edit-ipl { opacity: 0; transform: scale(.5); }
  & .apv-edit-ipa { opacity: 1; transform: none; }
}

/* ── inspector ── */
.apv-edit .apv-edit-insp { grid-area: insp; min-height: 0; overflow: auto; padding: 10px 14px 14px; border-left: 1px solid var(--apv-edit-line); background: var(--apv-edit-panel); display: grid; align-content: start; gap: 12px; scrollbar-width: thin; scrollbar-color: var(--apv-edit-line2) transparent;
  & .apv-edit-ititle { display: flex; align-items: center; gap: 8px; }
  & .apv-edit-ititle i { width: 10px; height: 10px; border-radius: 3px; background: var(--c); }
  & .apv-edit-ititle b { font-size: 14px; font-weight: 700; letter-spacing: -.01em; }
  & dl { display: grid; grid-template-columns: auto 1fr; gap: 5px 10px; font-size: 11.5px; }
  & dt { color: var(--apv-edit-faint); }
  & dd { text-align: right; font: 500 11.5px ui-monospace, Menlo, monospace; font-variant-numeric: tabular-nums; }
  & label { display: grid; gap: 4px; font-size: 11.5px; color: var(--apv-edit-mute); }
  & label span { display: flex; justify-content: space-between; }
  & label output { font: 500 11px ui-monospace, Menlo, monospace; color: var(--apv-edit-ink); }
  & input[type="range"] { width: 100%; }
  & .apv-edit-sw { display: flex; gap: 6px; }
  & .apv-edit-sw button { width: 20px; height: 20px; border-radius: 6px; background: var(--c); box-shadow: inset 0 0 0 1px oklch(1 0 0 / .15); transition: transform .3s var(--apv-edit-spring); }
  & .apv-edit-sw button[aria-pressed="true"] { box-shadow: 0 0 0 2px var(--apv-edit-bg), 0 0 0 3.5px var(--apv-edit-ink); }
  & .apv-edit-sw button:hover { transform: scale(1.15); }
  & .apv-edit-acts { display: flex; gap: 6px; flex-wrap: wrap; }
  & .apv-edit-acts button { height: 28px; padding: 0 10px; border-radius: 6px; font-size: 12px; font-weight: 600; box-shadow: inset 0 0 0 1px var(--apv-edit-line2); }
  & .apv-edit-acts button:hover { background: var(--apv-edit-line); }
  & .apv-edit-mk { display: grid; gap: 2px; }
  & .apv-edit-mk button { display: flex; justify-content: space-between; padding: 4px 6px; border-radius: 5px; font-size: 11.5px; }
  & .apv-edit-mk button:hover { background: var(--apv-edit-line); }
  & .apv-edit-mk output { font: 500 11px ui-monospace, Menlo, monospace; color: var(--apv-edit-accent); }
