  border-top: 1px solid var(--apv-edit-line2); background: var(--apv-edit-deep);
}
.apv-edit .apv-edit-corner { grid-column: 1; grid-row: 1; display: flex; align-items: center; gap: 2px; padding: 0 6px; border-right: 1px solid var(--apv-edit-line); border-bottom: 1px solid var(--apv-edit-line);
  & button { display: grid; place-items: center; width: 20px; height: 20px; border-radius: 4px; color: var(--apv-edit-mute); }
  & button:hover { background: var(--apv-edit-line); color: var(--apv-edit-ink); }
  & svg { width: 13px; height: 13px; }
  & input { flex: 1; min-width: 0; height: 14px; }
