  & small { flex: 1; font-size: 10.5px; color: var(--apv-edit-faint); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & button { display: grid; place-items: center; width: 22px; height: 22px; border-radius: 4px; color: var(--apv-edit-faint); }
  & button svg { width: 13px; height: 13px; }
  & button:hover { background: var(--apv-edit-line); color: var(--apv-edit-ink); }
  & button[aria-pressed="true"] { color: var(--apv-edit-accent); }
}
.apv-edit .apv-edit-lanecv { position: absolute; left: 0; top: 0; width: 0; height: 0; display: block; pointer-events: none; z-index: 0; }
.apv-edit .apv-edit-scroller { grid-column: 2; grid-row: 1 / 3; position: relative; z-index: 1; overflow-x: auto; overflow-y: hidden; overscroll-behavior-x: contain; scrollbar-width: thin; scrollbar-color: var(--apv-edit-line2) transparent; }
.apv-edit .apv-edit-area { position: relative; min-width: 100%; }
.apv-edit .apv-edit-ruler {
  position: relative; height: 26px; cursor: ew-resize; border-bottom: 1px solid var(--apv-edit-line);
