  & .apv-edit-io { position: absolute; top: 0; bottom: 0; background: color-mix(in oklch, var(--apv-edit-accent) 16%, transparent); border-inline: 1.5px solid var(--apv-edit-accent); pointer-events: none; }
  & .apv-edit-mark { position: absolute; top: 0; width: 10px; height: 12px; margin-left: -5px; background: oklch(0.7 0.15 160); clip-path: polygon(0 0, 100% 0, 100% 60%, 50% 100%, 0 60%); cursor: pointer; pointer-events: auto; }
}
