/* ── mid: one side panel with tabs ── */
@container (max-width: 1019px) {
  .apv-edit .apv-edit-app { grid-template-columns: minmax(0, 1fr) 230px; grid-template-rows: auto auto minmax(0, 1fr) auto; grid-template-areas: "bar bar" "mon tabs" "mon side" "tl tl"; }
