  }
  .apv-edit .apv-edit-proj small, .apv-edit .apv-edit-tools button span { display: none; }
}
/* ── narrow: monitor on top, one panel below ── */
@container (max-width: 759px) {
  .apv-edit .apv-edit-app { grid-template-columns: minmax(0, 1fr); grid-template-rows: auto auto minmax(0, 1fr) auto; grid-template-areas: "bar" "mon" "tl" "tabs"; }
  .apv-edit .apv-edit-bar { flex-wrap: wrap; gap: 6px 8px; padding: 8px 10px; }
  .apv-edit .apv-edit-proj { flex: 1 1 100%; }
  .apv-edit .apv-edit-tools { order: 3; flex: 1; overflow-x: auto; scrollbar-width: none; }
  .apv-edit .apv-edit-tools kbd { display: none; }
  .apv-edit .apv-edit-tc { font-size: 12.5px; order: 2; position: absolute; top: 10px; right: 76px; }
  .apv-edit .apv-edit-export { position: absolute; top: 8px; right: 10px; height: 28px; padding: 0 10px; }
  .apv-edit .apv-edit-mon { padding: 6px 10px 4px; }
  .apv-edit .apv-edit-screen { height: min(56cqi, 250px); }
  .apv-edit .apv-edit-tbtns kbd { display: none; }
  .apv-edit .apv-edit-bin, .apv-edit .apv-edit-insp { grid-area: tl; border: 0; }
  .apv-edit .apv-edit-tl { align-content: start; }
  .apv-edit:not([data-panel="timeline"]) .apv-edit-tl, .apv-edit:not([data-panel="media"]) .apv-edit-bin, .apv-edit:not([data-panel="insp"]) .apv-edit-insp { display: none; }
  .apv-edit[data-panel="media"] .apv-edit-bin, .apv-edit[data-panel="insp"] .apv-edit-insp { display: grid; }
  .apv-edit .apv-edit-tl { grid-template-columns: 64px minmax(0, 1fr); }
  .apv-edit .apv-edit-head small, .apv-edit .apv-edit-corner input { display: none; }
  .apv-edit .apv-edit-head { padding: 0 2px 0 6px; }
  .apv-edit .apv-edit-keys { display: none; }
  .apv-edit .apv-edit-tabs { grid-area: tabs; display: grid; grid-template-columns: repeat(3, 1fr); border-top: 1px solid var(--apv-edit-line); background: var(--apv-edit-panel); padding: 0;
    & button { padding: 10px 0; font-size: 12px; font-weight: 650; color: var(--apv-edit-faint); border-radius: 0; }
    & button[aria-selected="true"] { color: var(--apv-edit-ink); box-shadow: inset 0 2px 0 var(--apv-edit-accent); }
    & [data-panel-btn="timeline"] { display: block; }
  }
  .apv-edit .apv-edit-toast { bottom: 58px; max-width: calc(100% - 20px); }
}

@keyframes apv-edit-drop { from { transform: translateY(-8px) scale(1.04); opacity: .4; } }

@media (prefers-reduced-motion: reduce) {
  .apv-edit .apv-edit-clip.is-new { animation: none; }
  .apv-edit .apv-edit-meter i { transition: none; }
  .apv-edit .apv-edit-toast, .apv-edit .apv-edit-toast.is-on { transform: none; transition: opacity .2s; }
  .apv-edit .apv-edit-tbtns button, .apv-edit .apv-edit-export { transition: background .15s; }
}

