/* Splice. The edit model is a list of clips {src, track, start, in, dur}.
   Every edit goes through the same overwrite rule a real NLE uses (whatever
   a clip lands on is trimmed, split or removed), every change is undoable,
   and time is quantised to frames at 24 fps. */
const doc = root.ownerDocument;
const $ = (s, el = root) => el.querySelector(s);
const $$ = (s, el = root) => [...el.querySelectorAll(s)];
const RM = matchMedia('(prefers-reduced-motion: reduce)');
const esc = s => String(s == null ? '' : s).replace(/[&<>"']/g, c => '&#' + c.charCodeAt(0) + ';');
const clamp = (v, a, b) => Math.min(b, Math.max(a, v));
const FPS = 24, FR = 1 / FPS;
const q = s => Math.round(s * FPS) / FPS;
const tc = s => { const f = Math.round(Math.max(0, s) * FPS); return [Math.floor(f / FPS / 3600), Math.floor(f / FPS / 60) % 60, Math.floor(f / FPS) % 60, f % FPS].map(n => String(n).padStart(2, '0')).join(':'); };
const A = (c, a) => c.replace(')', ' / ' + a + ')');

/* ── sources ── */
const SRC = [
  { id: 'workshop', name: 'Workshop, morning', kind: 'video', dur: 18, look: 'workshop', c: 'oklch(0.56 0.07 70)' },
  { id: 'hands', name: 'Hands in clay', kind: 'video', dur: 22, look: 'hands', c: 'oklch(0.55 0.1 40)' },
  { id: 'interview', name: 'Interview: Ama, cam A', kind: 'video', dur: 40, look: 'interview', c: 'oklch(0.52 0.06 225)' },
  { id: 'wheel', name: 'Wheel, overhead', kind: 'video', dur: 26, look: 'wheel', c: 'oklch(0.55 0.08 20)' },
  { id: 'fire', name: 'Kiln firing', kind: 'video', dur: 20, look: 'fire', c: 'oklch(0.6 0.15 55)' },
  { id: 'coast', name: 'Drone, coastline', kind: 'video', dur: 24, look: 'coast', c: 'oklch(0.55 0.08 200)' },
  { id: 't-open', name: 'Title: Kiln & Co.', kind: 'title', dur: 30, text: ['Kiln & Co.'], style: 'open', c: 'oklch(0.66 0.12 90)' },
  { id: 't-lower', name: 'Lower third: Ama Boateng', kind: 'title', dur: 30, text: ['Ama Boateng', 'Potter and founder'], style: 'lower', c: 'oklch(0.66 0.12 90)' },
  { id: 't-end', name: 'End card', kind: 'title', dur: 30, text: ['Made slowly.', 'Since 1987.'], style: 'end', c: 'oklch(0.66 0.12 90)' },
  { id: 'vo', name: 'Interview audio, lav mic', kind: 'audio', dur: 40, look: 'speech', c: 'oklch(0.6 0.12 150)' },
  { id: 'music', name: 'Music: Slow Fire', kind: 'audio', dur: 75, look: 'music', c: 'oklch(0.58 0.1 25)' },
  { id: 'room', name: 'Room tone, workshop', kind: 'audio', dur: 30, look: 'room', c: 'oklch(0.55 0.05 160)' },
];
const SR = Object.fromEntries(SRC.map(s => [s.id, s]));
const TRACKS = [
  { id: 'V2', kinds: ['title', 'video'], h: 34, name: 'Titles' },
  { id: 'V1', kinds: ['video'], h: 58, name: 'Picture' },
  { id: 'A1', kinds: ['audio'], h: 44, name: 'Dialogue' },
  { id: 'A2', kinds: ['audio'], h: 44, name: 'Music' },
];
const TK = Object.fromEntries(TRACKS.map(t => [t.id, t]));
const LABELS = ['oklch(0.56 0.07 70)', 'oklch(0.55 0.1 40)', 'oklch(0.52 0.06 225)', 'oklch(0.55 0.08 200)', 'oklch(0.6 0.12 150)', 'oklch(0.66 0.12 90)'];
let nid = 0;
const C = (src, track, start, inn, dur, o) => Object.assign({ id: 'c' + (++nid), src, track, start, in: inn, dur, op: 100, vol: 100, c: SR[src].c }, o || {});
let clips = [
  C('t-open', 'V2', 1.5, 0, 4), C('t-lower', 'V2', 14, 0, 5), C('t-end', 'V2', 52, 0, 6),
  C('workshop', 'V1', 0, 2, 8), C('hands', 'V1', 8, 5, 8), C('interview', 'V1', 16, 12, 14), C('wheel', 'V1', 30, 6, 11), C('fire', 'V1', 41, 4, 8), C('coast', 'V1', 49, 7, 11),
  C('vo', 'A1', 14, 10, 30), C('music', 'A2', 0, 0, 60, { vol: 70 }),
];
const S = { t: 0, rate: 0, pps: 20, sel: null, tool: 'select', snap: true, markers: [8, 30, 49], io: [null, null], hide: {}, lock: {} };
const seqEnd = () => clips.reduce((m, c) => Math.max(m, c.start + c.dur), 0);

/* ── undo ── */
const hist = [], fut = [];
const snap = () => JSON.stringify({ clips, markers: S.markers, io: S.io, nid });
function save() { hist.push(snap()); if (hist.length > 80) hist.shift(); fut.length = 0; dirty(); }
function restore(j) { const o = JSON.parse(j); clips = o.clips; S.markers = o.markers; S.io = o.io; nid = Math.max(nid, o.nid); if (S.sel && !clips.find(c => c.id === S.sel)) S.sel = null; renderAll(); }
function undo() { if (!hist.length) return; fut.push(snap()); restore(hist.pop()); toast('Undo'); dirty(); }
function redo() { if (!fut.length) return; hist.push(snap()); restore(fut.pop()); toast('Redo'); dirty(); }
function dirty() { $('[data-act="undo"]').disabled = !hist.length; $('[data-act="redo"]').disabled = !fut.length; $('[data-saved]').textContent = 'Cut 4 · ' + (hist.length ? hist.length + (hist.length === 1 ? ' edit' : ' edits') + ' since open' : 'saved'); }

/* ── footage: procedural "camera" looks, shared by monitor, bin and filmstrips ── */
const hash = (i, s) => { const x = Math.sin(i * 127.1 + s * 311.7) * 43758.5453; return x - Math.floor(x); };
function foot(ctx, w, h, look, t) {
  ctx.save(); ctx.globalAlpha = 1;
  let g;
  if (look === 'workshop') {
    g = ctx.createLinearGradient(0, 0, w, h); g.addColorStop(0, 'oklch(0.42 0.04 60)'); g.addColorStop(1, 'oklch(0.2 0.03 50)'); ctx.fillStyle = g; ctx.fillRect(0, 0, w, h);
    ctx.fillStyle = 'oklch(0.93 0.06 85)'; ctx.fillRect(w * .62, h * .12, w * .22, h * .38);
    ctx.fillStyle = 'oklch(0.3 0.03 60)'; ctx.fillRect(w * .725, h * .12, w * .01, h * .38); ctx.fillRect(w * .62, h * .3, w * .22, h * .012);
    ctx.globalCompositeOperation = 'lighter';
    g = ctx.createLinearGradient(w * .7, h * .2, w * .2, h); g.addColorStop(0, 'oklch(0.9 0.08 85 / .28)'); g.addColorStop(1, 'oklch(0.9 0.08 85 / 0)');
    ctx.fillStyle = g; ctx.beginPath(); ctx.moveTo(w * .62, h * .12); ctx.lineTo(w * .84, h * .12); ctx.lineTo(w * .55 + Math.sin(t * .3) * w * .02, h); ctx.lineTo(w * .05, h); ctx.fill();
    for (let i = 0; i < 40; i++) { const x = (hash(i, 1) * w + t * w * .01 * (hash(i, 2) - .3)) % w, y = (hash(i, 3) * h + t * h * .02) % h; ctx.fillStyle = 'oklch(0.95 0.05 85 / ' + (.15 + .4 * hash(i, 4)) + ')'; ctx.fillRect(x, y, Math.max(1, w / 300), Math.max(1, w / 300)); }
    ctx.globalCompositeOperation = 'source-over';
    ctx.fillStyle = 'oklch(0.16 0.02 50)'; ctx.fillRect(0, h * .74, w, h * .26);
    for (let i = 0; i < 5; i++) { ctx.fillStyle = 'oklch(0.5 0.08 45)'; const x = w * (.12 + i * .1), r = h * (.05 + hash(i, 9) * .04); ctx.beginPath(); ctx.ellipse(x, h * .74 - r * .9, r * .8, r, 0, 0, 7); ctx.fill(); }
  } else if (look === 'hands') {
    g = ctx.createRadialGradient(w * .5, h * .55, 0, w * .5, h * .55, w * .7); g.addColorStop(0, 'oklch(0.55 0.1 45)'); g.addColorStop(1, 'oklch(0.22 0.05 40)'); ctx.fillStyle = g; ctx.fillRect(0, 0, w, h);
    ctx.translate(w * .5, h * .58); const a = t * 1.8;
    for (let k = 9; k > 0; k--) { ctx.fillStyle = 'oklch(' + (0.42 + k * .025) + ' 0.1 45)'; ctx.beginPath(); ctx.ellipse(Math.cos(a + k) * w * .004 * k, 0, w * .045 * k, h * .045 * k * .55, 0, 0, 7); ctx.fill(); }
    ctx.strokeStyle = 'oklch(0.85 0.06 60 / .35)'; ctx.lineWidth = Math.max(1, w / 260);
    for (let k = 1; k < 8; k++) { ctx.beginPath(); ctx.ellipse(0, 0, w * .045 * k, h * .045 * k * .55, 0, a + k, a + k + 1.4); ctx.stroke(); }
    ctx.fillStyle = 'oklch(0.62 0.07 50)'; ctx.beginPath(); ctx.ellipse(-w * .3, -h * .05 + Math.sin(t * 2) * h * .01, w * .16, h * .09, .5, 0, 7); ctx.fill();
    ctx.beginPath(); ctx.ellipse(w * .3, -h * .02 + Math.cos(t * 2) * h * .01, w * .16, h * .09, -.5, 0, 7); ctx.fill();
