  $('[data-bincount]').textContent = SRC.length + ' items';
  $$('[data-thumb]').forEach(cv => {
    const s = SR[cv.dataset.thumb], ctx = cv.getContext('2d');
    if (s.kind === 'video') foot(ctx, 128, 72, s.look, s.dur / 3);
    else if (s.kind === 'title') { ctx.fillStyle = 'oklch(0.16 0.01 60)'; ctx.fillRect(0, 0, 128, 72); ctx.fillStyle = s.c; ctx.font = '700 15px system-ui'; ctx.textAlign = 'center'; ctx.fillText('Aa', 64, 42); }
    else { ctx.fillStyle = 'oklch(0.16 0.01 150)'; ctx.fillRect(0, 0, 128, 72); ctx.fillStyle = s.c; for (let x = 0; x < 128; x += 2) { const a = amp(s.id, x / 128 * s.dur) * 50; ctx.fillRect(x, 36 - a / 2, 1.4, a); } }
  });
}

/* ── edit operations ── */
function clearRange(track, s, e, except) {
  const out = [];
  clips.forEach(c => {
    if (c.track !== track || c.id === except) { out.push(c); return; }
    const ce = c.start + c.dur;
    if (ce <= s + 1e-6 || c.start >= e - 1e-6) { out.push(c); return; }
    if (c.start >= s - 1e-6 && ce <= e + 1e-6) return;
    if (c.start < s && ce > e) { out.push(Object.assign({}, c, { dur: q(s - c.start) }), Object.assign({}, c, { id: 'c' + (++nid), start: e, in: q(c.in + (e - c.start)), dur: q(ce - e) })); return; }
    if (c.start < s) out.push(Object.assign({}, c, { dur: q(s - c.start) }));
    else out.push(Object.assign({}, c, { in: q(c.in + (e - c.start)), dur: q(ce - e), start: e }));
  });
