  const b = Object.assign({}, c, { id: 'c' + (++nid), start: t, in: q(c.in + (t - c.start)), dur: q(c.start + c.dur - t) });
  c.dur = q(t - c.start); clips.push(b); return b;
}
function splitPlayhead() {
