  const targets = sel ? [sel] : clips.filter(c => !S.lock[c.track] && S.t > c.start + FR && S.t < c.start + c.dur - FR);
  if (!targets.length) { toast('Nothing under the playhead to split'); return; }
  save(); const made = targets.map(c => splitAt(c, S.t)).filter(Boolean);
  renderAll(made.map(c => c.id)); toast('Split ' + made.length + (made.length === 1 ? ' clip' : ' clips') + ' at ' + tc(S.t), undo);
}
function deleteSel(ripple) {
  const c = clips.find(x => x.id === S.sel); if (!c) { toast('Select a clip first'); return; }
  if (S.lock[c.track]) { toast(c.track + ' is locked'); return; }
  save(); clips = clips.filter(x => x !== c);
  if (ripple) clips.forEach(x => { if (x.track === c.track && x.start >= c.start + c.dur - 1e-6) x.start = q(x.start - c.dur); });
  S.sel = null; renderAll(); toast((ripple ? 'Ripple deleted ' : 'Deleted ') + SR[c.src].name + (ripple ? ', closed a ' + c.dur.toFixed(1) + 's gap' : ''), undo);
}
function insertSrc(srcId, track, start) {
  const s = SR[srcId], dur = q(s.kind === 'title' ? 4 : s.kind === 'video' ? Math.min(s.dur, 6) : Math.min(s.dur, 12)), inn = s.kind === 'video' ? q(Math.min(2, s.dur - dur)) : 0;
  save(); clearRange(track, start, start + dur);
  const c = C(srcId, track, q(start), inn, dur); clips.push(c); S.sel = c.id;
  renderAll([c.id]); toast('Placed ' + s.name + ' on ' + track + ' at ' + tc(start), undo);
}
function firstTrack(kind) { return TRACKS.find(t => t.kinds[0] === kind && !S.lock[t.id]) || TRACKS.find(t => t.kinds.includes(kind) && !S.lock[t.id]); }
function editPoints() { const p = new Set([0, seqEnd()]); clips.forEach(c => { p.add(q(c.start)); p.add(q(c.start + c.dur)); }); return [...p].sort((a, b) => a - b); }
function snapTo(times, exceptId) {
  if (!S.snap) return { t: null };
  const pts = [S.t, 0, ...S.markers]; clips.forEach(c => { if (c.id !== exceptId) pts.push(c.start, c.start + c.dur); });
  const thr = 9 / S.pps; let best = null;
  times.forEach((t, i) => pts.forEach(p => { const d = Math.abs(p - t); if (d < thr && (!best || d < best.d)) best = { d, off: p - t, at: p, i }; }));
