}
function showSnap(at) { const l = $('[data-snapline]'); if (at == null) { l.classList.remove('is-on'); return; } l.style.left = at * S.pps + 'px'; l.classList.add('is-on'); }

/* ── pointer: scrub, move, trim, blade, bin drag ── */
let bladeX = null;
const tAtX = cx => (cx - scroller.getBoundingClientRect().left + scroller.scrollLeft) / S.pps;
const laneTop = id => { let y = 0; for (const t of TRACKS) { if (t.id === id) return y; y += t.h; } return 0; };
function laneAtY(cy) { let y = lanesEl.getBoundingClientRect().top; for (const t of TRACKS) { if (cy >= y && cy < y + t.h) return t.id; y += t.h; } return null; }
ruler.addEventListener('pointerdown', e => {
  const mk = e.target.closest('[data-mark]'); if (mk) { stop(); setT(+mk.dataset.mark); return; }
  ruler.setPointerCapture(e.pointerId); stop(); setT(tAtX(e.clientX));
  const mv = ev => setT(tAtX(ev.clientX)); const up = () => { ruler.removeEventListener('pointermove', mv); ruler.removeEventListener('pointerup', up); };
  ruler.addEventListener('pointermove', mv); ruler.addEventListener('pointerup', up);
});
lanesEl.addEventListener('pointermove', e => { if (S.tool !== 'blade') return; bladeX = q(tAtX(e.clientX)) * S.pps; drawLanes(); });
lanesEl.addEventListener('pointerleave', () => { if (bladeX != null) { bladeX = null; drawLanes(); } });
lanesEl.addEventListener('pointerdown', e => {
  const el = e.target.closest('[data-clip]');
  if (!el) { S.sel = null; renderAll(); return; }
  const c = clips.find(x => x.id === el.dataset.clip), s = SR[c.src];
  S.sel = c.id; $$('[data-clip]').forEach(x => x.setAttribute('aria-selected', x === el)); renderInsp();
  root.focus({ preventScroll: true });
  if (S.tool === 'blade') { if (S.lock[c.track]) return; save(); const b = splitAt(c, tAtX(e.clientX)); if (b) { renderAll([b.id]); toast('Split ' + s.name, undo); } else hist.pop(); return; }
