scroller.addEventListener('scroll', () => drawLanes(), { passive: true });
scroller.addEventListener('wheel', e => { if (!(e.ctrlKey || e.metaKey)) return; e.preventDefault(); zoomTo(S.pps * (1 - e.deltaY * .01), e.clientX); }, { passive: false });

/* drag a source from the bin onto a track */
$('[data-bin]').addEventListener('pointerdown', e => {
