$('[data-bin]').addEventListener('dblclick', e => { const li = e.target.closest('.apv-edit-src'); if (li) { const s = SR[li.dataset.src], t = firstTrack(s.kind); if (t) insertSrc(s.id, t.id, S.t); } });

/* ── zoom ── */
function zoomTo(pps, cx) {
  const old = S.pps; S.pps = clamp(pps, 6, 160); $('[data-zoom]').value = Math.round(S.pps);
  const anchorX = cx != null ? cx - scroller.getBoundingClientRect().left : S.t * old - scroller.scrollLeft;
  const tAnchor = (scroller.scrollLeft + anchorX) / old;
  renderClips(); scroller.scrollLeft = tAnchor * S.pps - anchorX; drawLanes();
}
$('[data-zoom]').addEventListener('input', e => zoomTo(+e.target.value));

/* ── playback (J/K/L shuttle) ── */
let raf = 0, last = 0, onScreen = true;
function frame(now) {
  if (!root.isConnected) return;
  raf = 0;
  if (!S.rate || doc.hidden || !onScreen) { last = 0; return; }
  const dt = last ? Math.min(.1, (now - last) / 1000) : 0; last = now;
  let t = S.t + dt * S.rate; const end = seqEnd();
  if (t >= end || t <= 0) { t = clamp(t, 0, end); S.t = t; stop(); setT(t, true); return; }
  S.t = t; placePH(); drawMonitor();
  const x = S.t * S.pps, l = scroller.scrollLeft, w = scroller.clientWidth; if (x > l + w - 30) scroller.scrollLeft = x - 40; else if (x < l) scroller.scrollLeft = x - w + 40;
  raf = requestAnimationFrame(frame);
}
function setRate(r) {
  S.rate = r; root.dataset.playing = r !== 0;
  $('[data-shuttle]').textContent = r === 0 || r === 1 ? '' : (r < 0 ? '◀◀ ' : '▶▶ ') + Math.abs(r) + '×';
  $('[data-act="play"]').setAttribute('aria-label', (r ? 'Pause' : 'Play') + ' (Space)');
  if (r && !raf && root.isConnected) { last = 0; raf = requestAnimationFrame(frame); }
  if (!r) { S.t = q(S.t); setT(S.t); }
}
const stop = () => { if (S.rate) setRate(0); };
const io = new IntersectionObserver(es => { onScreen = es[es.length - 1].isIntersecting; if (onScreen && S.rate && !raf) raf = requestAnimationFrame(frame); });
io.observe(root);
const onVis = () => { if (!root.isConnected) { doc.removeEventListener('visibilitychange', onVis); io.disconnect(); return; } if (!doc.hidden && S.rate && !raf) raf = requestAnimationFrame(frame); };
doc.addEventListener('visibilitychange', onVis);

/* ── toast ── */
let toastT = 0, toastUndo = null;
function toast(msg, u) {
  const t = $('[data-toast]'); $('[data-msg]', t).textContent = msg; toastUndo = u || null; $('[data-act="toast-undo"]', t).hidden = !u;
  t.classList.add('is-on'); clearTimeout(toastT); toastT = setTimeout(() => t.classList.remove('is-on'), u ? 4000 : 1600);
}

function renderAll(newIds) { renderClips(newIds); renderInsp(); drawMonitor(); dirty(); }
function setTool(t) { S.tool = t; root.dataset.tool = t; $('[data-act="tool-select"]').setAttribute('aria-pressed', t === 'select'); $('[data-act="tool-blade"]').setAttribute('aria-pressed', t === 'blade'); bladeX = null; drawLanes(); }
function setPanel(p) { root.dataset.panel = p; $$('[data-panel-btn]').forEach(b => b.setAttribute('aria-selected', b.dataset.panelBtn === p)); requestAnimationFrame(() => { if (!root.isConnected) return; drawLanes(); }); }

root.addEventListener('click', e => {
  const b = e.target.closest('button'); if (!b || !root.contains(b)) return;
  if (b.dataset.hide) { S.hide[b.dataset.hide] = !S.hide[b.dataset.hide]; renderHeads(); drawMonitor(); return; }
  if (b.dataset.lock) { S.lock[b.dataset.lock] = !S.lock[b.dataset.lock]; renderHeads(); renderClips(); toast(b.dataset.lock + (S.lock[b.dataset.lock] ? ' locked' : ' unlocked')); return; }
  if (b.dataset.goto) { stop(); setT(+b.dataset.goto, true); return; }
  if (b.dataset.label) { const c = clips.find(x => x.id === S.sel); if (c) { save(); c.c = b.dataset.label; renderAll(); } return; }
  if (b.dataset.panelBtn) { setPanel(b.dataset.panelBtn); return; }
  switch (b.dataset.act) {
    case 'tool-select': setTool('select'); break;
    case 'tool-blade': setTool('blade'); break;
    case 'split': splitPlayhead(); break;
    case 'ripple': deleteSel(true); break;
    case 'del': deleteSel(false); break;
    case 'snap': S.snap = !S.snap; b.setAttribute('aria-pressed', S.snap); toast('Snapping ' + (S.snap ? 'on' : 'off')); break;
    case 'undo': undo(); break;
    case 'redo': redo(); break;
    case 'toast-undo': $('[data-toast]').classList.remove('is-on'); if (toastUndo) { toastUndo = null; undo(); } break;
    case 'play': setRate(S.rate ? 0 : 1); break;
    case 'j': setRate(S.rate >= 0 ? -1 : Math.max(-8, S.rate * 2)); break;
    case 'l': setRate(S.rate <= 0 ? 1 : Math.min(8, S.rate * 2)); break;
    case 'home': stop(); setT(0, true); break;
    case 'end': stop(); setT(seqEnd(), true); break;
    case 'zoom-in': zoomTo(S.pps * 1.4); break;
    case 'zoom-out': zoomTo(S.pps / 1.4); break;
    case 'export': { const a = S.io[0] ?? 0, z = S.io[1] ?? seqEnd(), d = Math.max(0, z - a); toast('Queued export: ' + tc(d) + ' at 1080p24, H.264 10 Mbps, about ' + Math.round(d * 1.25) + ' MB'); break; }
  }
});
root.addEventListener('input', e => {
  const r = e.target.closest('[data-prop]'); if (!r) return;
  const c = clips.find(x => x.id === S.sel); if (!c) return;
  if (!r.dataset.saved) { save(); r.dataset.saved = '1'; }
  c[r.dataset.prop] = +r.value; $('[data-propout]').textContent = r.value + '%'; drawLanes(); drawMonitor();
});

root.addEventListener('keydown', e => {
  const k = e.key, mod = e.metaKey || e.ctrlKey, tg = e.target;
