  if (mod && (k === 'y' || k === 'Y')) { e.preventDefault(); redo(); return; }
  if (mod && (k === 'k' || k === 'K' || k === 'b' || k === 'B')) { e.preventDefault(); splitPlayhead(); return; }
  if (mod) return;
  const src = tg.closest && tg.closest('.apv-edit-src');
  if (src && (k === 'ArrowDown' || k === 'ArrowUp')) { e.preventDefault(); const l = $$('.apv-edit-src'), i = l.indexOf(src), n = l[clamp(i + (k === 'ArrowDown' ? 1 : -1), 0, l.length - 1)]; l.forEach(x => x.tabIndex = -1); n.tabIndex = 0; n.focus(); return; }
  if (src && k === 'Enter') { e.preventDefault(); const s = SR[src.dataset.src], t = firstTrack(s.kind); if (t) insertSrc(s.id, t.id, S.t); return; }
  if (tg.tagName === 'BUTTON' && (k === 'Enter' || k === ' ')) return;
  switch (k) {
    case ' ': e.preventDefault(); setRate(S.rate ? 0 : 1); break;
    case 'k': case 'K': setRate(0); break;
    case 'l': case 'L': setRate(S.rate <= 0 ? 1 : Math.min(8, S.rate * 2)); break;
    case 'j': case 'J': setRate(S.rate >= 0 ? -1 : Math.max(-8, S.rate * 2)); break;
    case 'ArrowLeft': case 'ArrowRight': e.preventDefault(); stop(); setT(S.t + (k === 'ArrowRight' ? 1 : -1) * (e.shiftKey ? 1 : FR), true); break;
    case 'ArrowUp': case 'ArrowDown': { e.preventDefault(); stop(); const pts = editPoints(); const n = k === 'ArrowDown' ? pts.find(p => p > S.t + 1e-6) : [...pts].reverse().find(p => p < S.t - 1e-6); if (n != null) setT(n, true); break; }
    case 'Home': e.preventDefault(); stop(); setT(0, true); break;
    case 'End': e.preventDefault(); stop(); setT(seqEnd(), true); break;
    case 'i': case 'I': save(); S.io[0] = S.t; if (S.io[1] != null && S.io[1] <= S.t) S.io[1] = null; renderRuler(); renderInsp(); toast('In point ' + tc(S.t)); break;
    case 'o': case 'O': save(); S.io[1] = S.t; if (S.io[0] != null && S.io[0] >= S.t) S.io[0] = null; renderRuler(); renderInsp(); toast('Out point ' + tc(S.t)); break;
    case 'x': case 'X': if (S.io[0] != null || S.io[1] != null) { save(); S.io = [null, null]; renderRuler(); renderInsp(); toast('Cleared in and out'); } break;
    case 'm': case 'M': { save(); const ex = S.markers.findIndex(m => Math.abs(m - S.t) < FR * 1.5); if (ex > -1) { S.markers.splice(ex, 1); toast('Marker removed'); } else { S.markers.push(S.t); toast('Marker at ' + tc(S.t), undo); } renderRuler(); renderInsp(); break; }
    case 'v': case 'V': setTool('select'); break;
    case 'b': case 'B': setTool('blade'); break;
    case 'n': case 'N': $('[data-act="snap"]').click(); break;
    case 'Delete': case 'Backspace': e.preventDefault(); deleteSel(e.shiftKey); break;
    case '+': case '=': zoomTo(S.pps * 1.4); break;
    case '-': case '_': zoomTo(S.pps / 1.4); break;
    case '\\': zoomTo((scroller.clientWidth - 40) / Math.max(1, seqEnd())); scroller.scrollLeft = 0; break;
    case 'Escape': if (S.tool !== 'select') setTool('select'); else if (S.sel) { S.sel = null; renderAll(); } break;
  }
});

/* ── sizing ── */
const ro = new ResizeObserver(() => {
  const dpr = Math.min(2, doc.defaultView.devicePixelRatio || 1);
  const w = Math.round(mon.clientWidth * dpr), h = Math.round(mon.clientHeight * dpr);
  if (w && (mon.width !== w || mon.height !== h)) { mon.width = w; mon.height = h; }
  drawMonitor(); renderClips();
  const mode = root.clientWidth < 760 ? 'narrow' : root.clientWidth < 1020 ? 'mid' : 'wide';
  if (mode !== root.dataset.mode) { root.dataset.mode = mode; if (mode === 'mid' && root.dataset.panel === 'timeline') setPanel('insp'); if (mode === 'wide') setPanel('timeline'); if (mode === 'narrow') setPanel('timeline'); }
});
ro.observe(root); ro.observe(mon);

/* ── boot ── */
renderHeads(); renderBin(); S.t = 15.5; renderAll(); dirty();
requestAnimationFrame(() => { if (!root.isConnected) return; setT(S.t, true); drawLanes(); });

css:
/* Earmark: the chapter is a dial. One full turn of the arm is one chapter;
   pass twelve o'clock and you are in the next one. */
@property --apv-book-p { syntax: '<number>'; inherits: true; initial-value: 0; }
@property --apv-book-glow { syntax: '<percentage>'; inherits: true; initial-value: 0%; }
@keyframes apv-book-vox { 0%, 100% { scale: 1 .18; } 50% { scale: 1 var(--a, .6); } }
@keyframes apv-book-breathe { 50% { --apv-book-glow: 34%; } }
@keyframes apv-book-in { from { opacity: 0; translate: 0 10px; } }
@keyframes apv-book-pop { 40% { scale: 1.18; } }

.apv-book {
  /* re-theme with these four */
  --apv-book-bg: oklch(0.2 0.024 28);
  --apv-book-ink: oklch(0.93 0.02 78);
  --apv-book-accent: oklch(0.8 0.115 76);
  --apv-book-ember: oklch(0.68 0.15 38);

  --apv-book-panel: color-mix(in oklch, var(--apv-book-bg), black 18%);
  --apv-book-raise: color-mix(in oklch, var(--apv-book-bg), var(--apv-book-ink) 7%);
  --apv-book-raise2: color-mix(in oklch, var(--apv-book-bg), var(--apv-book-ink) 12%);
  --apv-book-line: color-mix(in oklch, var(--apv-book-ink) 10%, transparent);
  --apv-book-line2: color-mix(in oklch, var(--apv-book-ink) 18%, transparent);
  --apv-book-mute: color-mix(in oklch, var(--apv-book-ink) 64%, var(--apv-book-bg));
  --apv-book-faint: color-mix(in oklch, var(--apv-book-ink) 40%, var(--apv-book-bg));
  --apv-book-tint: color-mix(in oklch, var(--apv-book-accent) 16%, var(--apv-book-bg));
  --apv-book-track: color-mix(in oklch, var(--apv-book-ink) 11%, var(--apv-book-bg));
  --apv-book-ease: cubic-bezier(.2, .8, .2, 1);
  --apv-book-spring: linear(0, 0.08 4%, 0.32 9%, 0.66 15%, 0.92 21%, 1.04 27%, 1.06 32%, 1.03 40%, 1.005 52%, 1);
  --apv-book-serif: ui-serif, "Iowan Old Style", "Palatino Linotype", Georgia, serif;
  --apv-book-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;

  position: relative; width: 100%; height: var(--apv-book-h, 680px);
  container-type: inline-size; overflow: clip; isolation: isolate; box-sizing: border-box;
  background: var(--apv-book-bg); color: var(--apv-book-ink); color-scheme: dark; accent-color: var(--apv-book-accent);
  border-radius: 14px; font: 13px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-tap-highlight-color: transparent;

  & *, & *::before, & *::after { box-sizing: border-box; }
  &:focus { outline: none; }
  & :focus-visible { outline: 2px solid var(--apv-book-accent); outline-offset: 2px; border-radius: 6px; }
  & button, & input { font: inherit; color: inherit; }
  & button { cursor: pointer; background: none; border: 0; padding: 0; }
  & h2, & h3, & p, & ol, & ul { margin: 0; padding: 0; }
  & ol, & ul { list-style: none; }
  & svg { width: 18px; height: 18px; fill: none; stroke: currentColor; stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; flex: none; }
  & svg text { fill: currentColor; stroke: none; font: 700 7.4px system-ui, sans-serif; letter-spacing: -.03em; }
  & .apv-book-fill { fill: currentColor; stroke: none; }
  & kbd { font: 600 10px/1 var(--apv-book-mono); padding: 3px 5px 2px; min-width: 18px; display: inline-block; text-align: center; border: 1px solid var(--apv-book-line2); border-bottom-width: 2px; border-radius: 4px; color: var(--apv-book-mute); background: var(--apv-book-raise); }
  & output { font-variant-numeric: tabular-nums; }
}

.apv-book .apv-book-app {
  height: 100%; display: grid;
  grid-template-columns: 252px minmax(0, 1fr) 300px;
  grid-template-rows: minmax(0, 1fr) auto;
  grid-template-areas: "shelf player side" "nav nav nav";
}

/* ── pattern covers: one recipe per book, two colours each ── */
.apv-book .apv-book-cov {
  position: relative; display: block; aspect-ratio: 2 / 3; border-radius: 3px 5px 5px 3px; overflow: hidden; container-type: inline-size; flex: none;
  background: var(--b); color: var(--f);
  box-shadow: inset 3px 0 0 color-mix(in oklch, black 22%, transparent), inset 4px 0 0 color-mix(in oklch, white 10%, transparent), 0 6px 14px -6px oklch(0 0 0 / .6);
  &[data-k="arch"] { background: radial-gradient(circle at 50% 100%, var(--f) 0 28%, transparent 28.5%) 0 0 / 100% 100% no-repeat, radial-gradient(circle at 50% 100%, transparent 0 36%, color-mix(in oklch, var(--f) 45%, transparent) 36.5% 38%, transparent 38.5%), var(--b); }
  &[data-k="stripes"] { background: repeating-linear-gradient(-58deg, transparent 0 7cqi, color-mix(in oklch, var(--f) 26%, transparent) 7cqi 8.5cqi), var(--b); }
  &[data-k="circle"] { background: radial-gradient(circle at 50% 58%, var(--f) 0 9%, color-mix(in oklch, var(--f) 30%, transparent) 9.5% 18%, transparent 18.5% 26%, color-mix(in oklch, var(--f) 16%, transparent) 26.5% 34%, transparent 34.5%), var(--b); }
  &[data-k="grid"] { background: linear-gradient(90deg, color-mix(in oklch, var(--f) 20%, transparent) 1px, transparent 1px) 0 0 / 16.66% 100%, linear-gradient(color-mix(in oklch, var(--f) 20%, transparent) 1px, transparent 1px) 0 0 / 100% 11.1%, var(--b); }
  &[data-k="grid"]::after { content: ""; position: absolute; width: 28%; aspect-ratio: 1; right: 16%; bottom: 22%; border-radius: 50%; border: 1.5px solid var(--f); background: conic-gradient(from 0deg, var(--f) 0 8%, transparent 8%); }
  &[data-k="wave"] { background: radial-gradient(ellipse 60% 18% at 50% 100%, transparent 70%, var(--f) 71% 76%, transparent 77%) 0 70% / 50% 30% repeat-x, radial-gradient(ellipse 60% 18% at 50% 0, transparent 70%, var(--f) 71% 76%, transparent 77%) 25% 85% / 50% 30% repeat-x, var(--b); }
  &[data-k="pane"] { background: linear-gradient(90deg, transparent 47%, var(--f) 47% 53%, transparent 53%), linear-gradient(transparent 46%, var(--f) 46% 50%, transparent 50%), radial-gradient(circle at 28% 26%, color-mix(in oklch, white 55%, transparent), transparent 42%), var(--b); }
  &[data-k="pane"]::after { content: ""; position: absolute; inset: 12% 14%; border: 2.5px solid var(--f); border-radius: 40% 40% 2px 2px / 22% 22% 2px 2px; }
  &[data-k="pane"] { background-clip: padding-box; }
}

/* ── shelf ── */
.apv-book .apv-book-shelf {
  grid-area: shelf; min-height: 0; display: flex; flex-direction: column; gap: 14px; padding: 18px 12px 12px;
  background: var(--apv-book-panel); border-right: 1px solid var(--apv-book-line);
}
.apv-book .apv-book-brand {
  display: flex; align-items: center; gap: 9px; padding: 0 8px;
  & svg { width: 20px; height: 20px; color: var(--apv-book-accent); stroke-width: 1.9; }
  & b { font: 600 19px/1 var(--apv-book-serif); letter-spacing: -.01em; font-style: italic; }
}
.apv-book .apv-book-find {
  display: flex; align-items: center; gap: 7px; height: 34px; padding: 0 7px 0 10px; border-radius: 9px; background: var(--apv-book-raise); box-shadow: inset 0 0 0 1px var(--apv-book-line);
  & svg { width: 15px; height: 15px; color: var(--apv-book-faint); }
  & input { flex: 1; min-width: 0; border: 0; outline: 0; background: none; font-size: 12.5px; }
  & input::placeholder { color: var(--apv-book-faint); }
  & input::-webkit-search-cancel-button { display: none; }
  & kbd { transition: opacity .2s; }
  &:focus-within { box-shadow: inset 0 0 0 1.5px var(--apv-book-accent); }
  &:focus-within kbd { opacity: 0; }
}
.apv-book .apv-book-seg {
  display: flex; gap: 2px; padding: 3px; border-radius: 9px; background: var(--apv-book-raise); box-shadow: inset 0 0 0 1px var(--apv-book-line);
  & button { flex: 1 1 0; min-width: 0; height: 26px; border-radius: 7px; font-size: 11.5px; font-weight: 600; color: var(--apv-book-mute); white-space: nowrap; transition: background .2s, color .2s; }
  & button:hover { color: var(--apv-book-ink); }
  & button[aria-checked="true"] { background: var(--apv-book-raise2); color: var(--apv-book-ink); box-shadow: 0 1px 2px oklch(0 0 0 / .35), inset 0 1px 0 color-mix(in oklch, var(--apv-book-ink) 8%, transparent); }
}
.apv-book .apv-book-books {
  flex: 1; min-height: 0; overflow: auto; display: grid; align-content: start; gap: 2px; margin: 0 -4px; padding: 0 4px; scrollbar-width: thin; scrollbar-color: var(--apv-book-line2) transparent;
  & li { animation: apv-book-in .4s var(--apv-book-ease) both; animation-delay: calc(var(--i, 0) * 40ms); }
  & button {
    width: 100%; display: grid; grid-template-columns: 40px minmax(0, 1fr); gap: 11px; align-items: center; padding: 8px; border-radius: 10px; text-align: left;
    transition: background .18s;
  }
  & button:hover { background: var(--apv-book-line); }
  & button[aria-current="true"] { background: var(--apv-book-tint); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--apv-book-accent) 26%, transparent); }
  & .apv-book-cov { width: 40px; transition: translate .3s var(--apv-book-spring); }
  & button:hover .apv-book-cov { translate: 0 -2px; }
  & .apv-book-meta { display: block; min-width: 0; }
  & strong { display: block; font-weight: 650; font-size: 12.5px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & .apv-book-by { display: block; font-size: 11.5px; color: var(--apv-book-mute); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & .apv-book-bar { display: flex; align-items: center; gap: 7px; margin-top: 5px; font-size: 10.5px; color: var(--apv-book-faint); font-variant-numeric: tabular-nums; }
  & .apv-book-bar i { flex: 1; height: 3px; border-radius: 2px; background: linear-gradient(90deg, var(--apv-book-accent) var(--v), var(--apv-book-track) var(--v)); }
  & .is-done .apv-book-bar { color: var(--apv-book-accent); }
  & .apv-book-bar svg { width: 12px; height: 12px; stroke-width: 2.4; }
}
.apv-book .apv-book-empty { padding: 26px 10px; text-align: center; color: var(--apv-book-faint); font-size: 12px; text-wrap: pretty; }

/* ── player ── */
.apv-book .apv-book-player {
  grid-area: player; min-height: 0; min-width: 0; display: flex; flex-direction: column; align-items: center; gap: 10px; padding: 22px clamp(14px, 3cqi, 34px) 14px; position: relative;
  background: radial-gradient(ellipse 70% 60% at 50% 46%, color-mix(in oklch, var(--apv-book-accent) var(--apv-book-glow), transparent), transparent 70%);
}
.apv-book[data-playing="true"] .apv-book-player { animation: apv-book-breathe 5.2s ease-in-out infinite; }
.apv-book .apv-book-head {
  width: 100%; display: grid; grid-template-columns: auto minmax(0, 1fr); gap: 14px; align-items: center;
  & .apv-book-cov { width: 46px; }
  & small { display: block; font-size: 10.5px; font-weight: 700; letter-spacing: .14em; text-transform: uppercase; color: var(--apv-book-accent); font-variant-numeric: tabular-nums; }
  & h2 { font: 600 clamp(18px, 2.1cqi, 24px)/1.12 var(--apv-book-serif); letter-spacing: -.01em; text-wrap: balance; margin: 2px 0 2px; }
  & p { font-size: 12px; color: var(--apv-book-mute); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
}
.apv-book .apv-book-dialwrap { flex: 1 1 0; min-height: 0; width: 100%; container-type: size; display: grid; place-items: center; position: relative; }
.apv-book .apv-book-dial {
  --s: min(100cqw, 100cqh, 400px);
  position: relative; width: var(--s); height: var(--s); border-radius: 50%; touch-action: none; cursor: grab; user-select: none;
  &:active { cursor: grabbing; }
  &:focus-visible { outline-offset: 6px; border-radius: 50%; }
  &.is-glide { transition: --apv-book-p .55s var(--apv-book-ease); }
}
.apv-book .apv-book-outer {
  position: absolute; inset: 0; width: 100%; height: 100%; overflow: visible; stroke-width: 2.4; stroke-linecap: butt;
  & path { stroke: var(--apv-book-line2); transition: stroke .4s; }
  & path.is-done { stroke: color-mix(in oklch, var(--apv-book-accent) 50%, var(--apv-book-bg)); }
  & path.is-cur { stroke: var(--apv-book-line2); }
  & path.apv-book-curp { stroke: var(--apv-book-accent); }
  & circle { fill: var(--apv-book-ember); stroke: var(--apv-book-bg); stroke-width: 1.5; }
  & text { font: 600 6px var(--apv-book-mono); fill: var(--apv-book-faint); text-anchor: middle; dominant-baseline: middle; }
}
.apv-book .apv-book-ring {
  position: absolute; inset: 8%; border-radius: 50%;
  background: conic-gradient(var(--apv-book-accent) calc(var(--apv-book-p) * 1turn), var(--apv-book-track) 0);
  -webkit-mask: radial-gradient(farthest-side, transparent calc(100% - 9px), #000 calc(100% - 8px));
          mask: radial-gradient(farthest-side, transparent calc(100% - 9px), #000 calc(100% - 8px));
}
.apv-book .apv-book-vox {
  position: absolute; inset: 15%; border-radius: 50%; pointer-events: none; opacity: calc(.35 + var(--apv-book-vol, 1) * .65); transition: opacity .6s;
  & i { position: absolute; inset: 0; rotate: calc(var(--i) * 5deg); }
  & i::before {
    content: ""; position: absolute; left: calc(50% - 1px); top: 0; width: 2px; height: 11%; border-radius: 1px; transform-origin: 50% 100%;
    background: color-mix(in oklch, var(--apv-book-accent) 55%, transparent); scale: 1 .18;
    animation: apv-book-vox var(--d, 900ms) ease-in-out calc(var(--i) * -97ms) infinite; animation-play-state: paused;
  }
  & i.is-past::before { background: var(--apv-book-accent); }
}
.apv-book[data-playing="true"] .apv-book-vox i::before { animation-play-state: running; }
.apv-book .apv-book-arm {
  position: absolute; inset: 8%; rotate: calc(var(--apv-book-p) * 1turn); pointer-events: none;
  & i {
    position: absolute; left: 50%; top: 4px; width: 22px; height: 22px; margin: -11px 0 0 -11px; border-radius: 50%;
    background: var(--apv-book-ink); box-shadow: 0 0 0 5px color-mix(in oklch, var(--apv-book-accent) 30%, transparent), 0 4px 10px oklch(0 0 0 / .5);
    transition: scale .35s var(--apv-book-spring), box-shadow .3s;
  }
}
.apv-book .apv-book-dial:hover .apv-book-arm i,
.apv-book .apv-book-dial.is-drag .apv-book-arm i { scale: 1.15; box-shadow: 0 0 0 8px color-mix(in oklch, var(--apv-book-accent) 26%, transparent), 0 4px 10px oklch(0 0 0 / .5); }
.apv-book .apv-book-center {
  position: absolute; inset: 27%; border-radius: 50%; display: grid; place-content: center; text-align: center; gap: 4px; container-type: inline-size;
  background: radial-gradient(circle at 50% 35%, var(--apv-book-raise), var(--apv-book-bg) 75%);
  box-shadow: inset 0 1px 0 color-mix(in oklch, var(--apv-book-ink) 8%, transparent), 0 18px 40px -18px oklch(0 0 0 / .7);
  & small { font-size: clamp(9px, 7cqi, 11px); font-weight: 700; letter-spacing: .14em; text-transform: uppercase; color: var(--apv-book-accent); }
  & strong { font: 300 clamp(26px, 24cqi, 54px)/1 system-ui, sans-serif; letter-spacing: -.04em; font-variant-numeric: tabular-nums; }
  & span { font: italic 500 clamp(11px, 8cqi, 14px)/1.2 var(--apv-book-serif); color: var(--apv-book-mute); max-width: 82cqi; margin: 0 auto; text-wrap: balance; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }
  & em { font: 500 clamp(10px, 7.5cqi, 12px)/1 var(--apv-book-mono); font-style: normal; color: var(--apv-book-faint); font-variant-numeric: tabular-nums; }
}
.apv-book .apv-book-tip {
  position: absolute; left: 0; top: 0; padding: 5px 9px; border-radius: 7px; pointer-events: none; white-space: nowrap;
  background: var(--apv-book-ink); color: var(--apv-book-bg); font: 600 11.5px/1.2 system-ui, sans-serif; font-variant-numeric: tabular-nums;
  translate: -50% calc(-100% - 16px); opacity: 0; scale: .9; transition: opacity .15s, scale .2s var(--apv-book-spring);
  &.is-on { opacity: 1; scale: 1; }
  &.is-lap { animation: apv-book-pop .4s var(--apv-book-ease); }
}

.apv-book .apv-book-ctl {
  display: flex; align-items: center; justify-content: center; gap: clamp(8px, 2cqi, 18px);
  & > button:not(.apv-book-play, .apv-book-speed) { width: 44px; height: 44px; border-radius: 50%; display: grid; place-items: center; color: var(--apv-book-mute); transition: background .18s, color .18s, scale .3s var(--apv-book-spring); }
  & > button:not(.apv-book-play, .apv-book-speed):hover { background: var(--apv-book-raise); color: var(--apv-book-ink); }
  & > button:active { scale: .92; }
  & svg { width: 24px; height: 24px; }
  & .apv-book-speed { height: 34px; min-width: 54px; padding: 0 10px; border-radius: 17px; font: 650 13px/1 system-ui, sans-serif; font-variant-numeric: tabular-nums; box-shadow: inset 0 0 0 1px var(--apv-book-line2); transition: background .18s, box-shadow .18s; }
  & .apv-book-speed:hover { background: var(--apv-book-raise); }
  & .apv-book-speed.is-fast { color: var(--apv-book-accent); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--apv-book-accent) 50%, transparent); }
  & .apv-book-mark.is-pop svg { animation: apv-book-pop .45s var(--apv-book-ease); color: var(--apv-book-ember); }
}
.apv-book .apv-book-play {
  width: 64px; height: 64px; border-radius: 50%; display: grid; place-items: center; position: relative;
  background: var(--apv-book-accent); color: var(--apv-book-bg);
  box-shadow: 0 10px 26px -10px color-mix(in oklch, var(--apv-book-accent) 70%, transparent), inset 0 1px 0 color-mix(in oklch, white 40%, transparent);
  transition: scale .35s var(--apv-book-spring), box-shadow .3s;
  &:hover { scale: 1.05; }
  & svg { position: absolute; width: 28px; height: 28px; transition: opacity .2s, scale .35s var(--apv-book-spring), rotate .35s var(--apv-book-ease); }
  & .apv-book-ipa { opacity: 0; scale: .5; rotate: -45deg; }
}
.apv-book[data-playing="true"] .apv-book-play {
  & .apv-book-ipl { opacity: 0; scale: .5; rotate: 45deg; }
  & .apv-book-ipa { opacity: 1; scale: 1; rotate: 0deg; }
}
.apv-book .apv-book-left { font-size: 12px; color: var(--apv-book-mute); text-align: center; font-variant-numeric: tabular-nums; text-wrap: balance; min-height: 1.45em; & b { color: var(--apv-book-ink); font-weight: 600; } }
.apv-book .apv-book-hint { display: flex; flex-wrap: wrap; justify-content: center; align-items: center; gap: 4px 6px; font-size: 11px; color: var(--apv-book-faint); & kbd + kbd { margin-left: -3px; } }

/* ── side ── */
.apv-book .apv-book-side { grid-area: side; min-height: 0; display: flex; flex-direction: column; border-left: 1px solid var(--apv-book-line); background: var(--apv-book-panel); }
.apv-book .apv-book-tabs {
  display: flex; gap: 4px; padding: 14px 14px 0; border-bottom: 1px solid var(--apv-book-line);
  & button { position: relative; padding: 8px 6px 11px; font-weight: 650; font-size: 12.5px; color: var(--apv-book-faint); transition: color .2s; display: flex; gap: 6px; align-items: center; }
  & button:hover { color: var(--apv-book-mute); }
  & button[aria-selected="true"] { color: var(--apv-book-ink); }
  & button::after { content: ""; position: absolute; left: 6px; right: 6px; bottom: -1px; height: 2px; border-radius: 2px; background: var(--apv-book-accent); scale: 0 1; transition: scale .35s var(--apv-book-spring); }
  & button[aria-selected="true"]::after { scale: 1 1; }
  & output { min-width: 18px; padding: 1px 5px; border-radius: 9px; background: var(--apv-book-raise2); font-size: 10.5px; color: var(--apv-book-mute); }
}
.apv-book .apv-book-list { flex: 1; min-height: 0; overflow: auto; padding: 8px; scrollbar-width: thin; scrollbar-color: var(--apv-book-line2) transparent; }
.apv-book .apv-book-chs {
  display: grid; gap: 1px;
  & button {
    width: 100%; display: grid; grid-template-columns: 26px minmax(0, 1fr) auto; gap: 8px; align-items: center; padding: 8px 8px; border-radius: 8px; text-align: left; transition: background .18s;
    animation: apv-book-in .38s var(--apv-book-ease) both; animation-delay: calc(var(--i, 0) * 22ms);
  }
  & button:hover { background: var(--apv-book-line); }
  & .apv-book-n { font: 600 11px/1 var(--apv-book-mono); color: var(--apv-book-faint); text-align: center; font-variant-numeric: tabular-nums; }
  & .apv-book-n svg { width: 14px; height: 14px; color: var(--apv-book-accent); stroke-width: 2.2; }
