const BOOKS = [
  { id: 'weather', title: 'Weather of the Interior', author: 'Odile Marchetti', narr: 'Sam Achebe-Lowe', k: 'arch', b: 'oklch(0.4 0.09 24)', f: 'oklch(0.86 0.09 74)',
    ch: mk([['The House at Vell', 31, 12], ['A Barometer in the Hall', 42, 5], ['Isobars', 38, 40], ['Letters from Calder Point', 45, 18], ['The Ferryman’s Ledger', 40, 2], ['Fog Year', 36, 55], ['What the Glass Remembered', 44, 30], ['Low Pressure', 39, 14], ['The Inventory', 33, 48], ['Second Winter', 47, 20], ['Clearing', 35, 6], ['Weather of the Interior', 28, 44]]),
    pos: { c: 6, t: 751 } },
  { id: 'linden', title: 'Under the Linden Clock', author: 'Maeve Orsolya', narr: 'Ruth Delacroix', k: 'grid', b: 'oklch(0.46 0.07 150)', f: 'oklch(0.9 0.045 100)',
    ch: mk([['The Clock Stops', 29, 5], ['Linden Street', 35, 40], ['Apprentice', 41, 22], ['Escapement', 37, 18], ['The Burgomaster’s Watch', 44, 2], ['Winding', 30, 30], ['A Second Hand', 33, 47], ['Fusee', 39, 55], ['The Night the Bells Ran Fast', 46, 12], ['Repair', 31, 28], ['Linden Time', 25, 10]]),
    pos: { c: 1, t: 1520 } },
  { id: 'slow', title: 'Slow Glass', author: 'Annika Bergström-Hale', narr: 'Jonah Pell-Ward', k: 'pane', b: 'oklch(0.84 0.035 205)', f: 'oklch(0.32 0.045 230)',
    ch: mk([['Pane', 24, 40], ['The Glazier’s Boy', 31, 15], ['Ten Years in a Window', 38, 50], ['Delivery', 27, 22], ['The Lake House', 35, 8], ['Exposure', 42, 30], ['What the Sheet Saw', 33, 44], ['Breakage', 29, 16], ['Slow Glass', 21, 55]]),
    pos: { c: 8, t: 1180 } },
  { id: 'rope', title: 'A Short History of Rope', author: 'Henrik Vasquez', narr: 'the author', k: 'stripes', b: 'oklch(0.79 0.075 80)', f: 'oklch(0.36 0.07 50)',
    ch: mk([['Introduction: Twist', 18, 20], ['Flax and Fibre', 34, 10], ['The Ropewalk', 41, 45], ['Knots at Sea', 38, 2], ['Hemp Fever', 29, 58], ['Wire', 26, 40], ['Nylon, 1938', 31, 15], ['Climbing', 36, 22], ['Afterword: Lay', 12, 48]]),
    pos: { c: 0, t: 0 } },
  { id: 'bridges', title: 'Thirty Bridges', author: 'Kofi Arden', narr: 'Daniel Mirza', k: 'wave', b: 'oklch(0.6 0.13 45)', f: 'oklch(0.95 0.025 80)',
    ch: mk([['Upstream', 22, 15], ['Iron', 39, 40], ['The Span at Kumasi Road', 43, 5], ['Suspension', 37, 30], ['Toll', 28, 18], ['Collapse, 1981', 45, 44], ['Thirty', 34, 2], ['Downstream', 19, 26]]),
    pos: { c: 0, t: 0 } },
  { id: 'lamp', title: 'The Lamplighter’s Almanac', author: 'Priya Venkataraman', narr: 'Clara Oduya', k: 'circle', b: 'oklch(0.28 0.045 255)', f: 'oklch(0.85 0.13 85)',
    ch: mk([['Dusk Rounds', 27, 30], ['Whale Oil', 33, 12], ['The Gas Company', 39, 48], ['A Strike in Lent', 35, 5], ['Mantles', 30, 44], ['The Night Census', 41, 10], ['Lamp Black', 28, 36], ['Mrs Okonedo’s Ledger', 37, 52], ['Electric', 44, 18], ['Dawn Rounds', 22, 40]]),
    pos: { c: 9, t: 1360 }, done: true },
];
const byId = id => BOOKS.find(b => b.id === id);
let uid = 0;
const MARKS = {
  weather: [{ c: 2, t: 845, note: 'Isobars as the family map' }, { c: 4, t: 1360, note: 'Ledger: “the Alder, 3 March, unreported”' }, { c: 5, t: 192, note: '' }],
  linden: [{ c: 0, t: 1215, note: 'The stopped clock reads 4:17' }],
  lamp: [{ c: 7, t: 655, note: 'Census figures for Gin Lane' }],
};
Object.values(MARKS).forEach(list => list.forEach(m => { m.id = 'm' + (++uid); }));
BOOKS.forEach(b => { MARKS[b.id] = MARKS[b.id] || []; });

const SPEEDS = [0.8, 1, 1.2, 1.5, 1.75, 2];
const SLEEPS = [['off', 'Off'], [15, '15m'], [30, '30m'], [45, '45m'], ['ch', 'Chapter']];
const FILTERS = [['all', 'All'], ['now', 'Listening'], ['done', 'Finished']];
const S = { book: 'weather', playing: false, si: 2, filter: 'all', q: '', tab: 'chapters', sleep: 'off', sleepLeft: 0, undo: [] };

const el = {
  books: $('[data-books]'), filters: $('[data-filters]'), q: $('[data-q]'), head: $('[data-head]'),
  dial: $('[data-dial]'), outer: $('[data-outer]'), center: $('[data-center]'), tip: $('[data-tip]'),
  left: $('[data-left]'), list: $('[data-list]'), markn: $('[data-markn]'), sleep: $('[data-sleep]'), sleepout: $('[data-sleepout]'),
  toast: $('[data-toast]'), msg: $('[data-msg]'), speed: $('[data-act="speed"]'), play: $('[data-act="play"]'), mark: $('[data-act="mark"]'),
  wrap: $('.apv-book-dialwrap'),
};

/* ── time ── */
const pad = n => String(n).padStart(2, '0');
const fmt = s => { s = Math.max(0, Math.floor(s)); const h = Math.floor(s / 3600), m = Math.floor(s % 3600 / 60), x = s % 60; return h ? h + ':' + pad(m) + ':' + pad(x) : m + ':' + pad(x); };
const human = s => { s = Math.max(0, Math.round(s / 60)); if (s < 1) return 'under a minute'; const h = Math.floor(s / 60), m = s % 60; return h ? h + ' h' + (m ? ' ' + m + ' min' : '') : m + ' min'; };
const speech = s => { s = Math.floor(s); const m = Math.floor(s / 60), x = s % 60; return m + ' minute' + (m === 1 ? '' : 's') + ' ' + x + ' second' + (x === 1 ? '' : 's'); };
const total = b => b.ch.reduce((a, c) => a + c.d, 0);
const before = (b, c) => { let a = 0; for (let i = 0; i < c; i++) a += b.ch[i].d; return a; };
const elapsed = b => before(b, b.pos.c) + b.pos.t;
const status = b => b.done ? 'done' : elapsed(b) > 0 ? 'now' : 'new';
const cur = () => byId(S.book);
const speed = () => SPEEDS[S.si];
const where = (c, t) => 'Ch ' + (c + 1) + ' · ' + fmt(t);

/* ── icons ── */
const I = {
  check: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m5 12.5 4.5 4.5L19 7.5"/></svg>',
  x: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M6 6l12 12M18 6 6 18"/></svg>',
  eq: '<span class="apv-book-eq" aria-hidden="true"><i></i><i></i><i></i></span>',
};
const cover = b => '<span class="apv-book-cov" data-k="' + b.k + '" style="--b:' + b.b + ';--f:' + b.f + '" aria-hidden="true"></span>';

/* ── shelf ── */
function renderFilters() {
  el.filters.innerHTML = FILTERS.map(([v, l]) => '<button type="button" role="radio" data-filter="' + v + '" aria-checked="' + (S.filter === v) + '" tabindex="' + (S.filter === v ? 0 : -1) + '">' + l + '</button>').join('');
}
function renderShelf() {
  const q = S.q.trim().toLowerCase();
  const list = BOOKS.filter(b => (S.filter === 'all' || status(b) === S.filter) && (!q || (b.title + ' ' + b.author + ' ' + b.narr).toLowerCase().includes(q)));
  if (!list.length) {
    el.books.innerHTML = '<li class="apv-book-empty">' + (q ? 'Nothing on your shelf matches “' + esc(S.q.trim()) + '”.' : 'No books here yet.') + '</li>';
    return;
  }
  el.books.innerHTML = list.map((b, i) => {
    const st = status(b), tot = total(b), v = st === 'done' ? 100 : elapsed(b) / tot * 100;
    const info = st === 'done' ? I.check + 'Finished' : st === 'new' ? human(tot) : human(tot - elapsed(b)) + ' left';
    return '<li style="--i:' + i + '"><button type="button" data-book="' + b.id + '" class="' + (st === 'done' ? 'is-done' : '') + '" aria-current="' + (b.id === S.book) + '" tabindex="' + (b.id === S.book ? 0 : -1) + '">' + cover(b) +
      '<span class="apv-book-meta"><strong>' + esc(b.title) + '</strong><span class="apv-book-by">' + esc(b.author) + '</span>' +
      '<span class="apv-book-bar"><i style="--v:' + v.toFixed(1) + '%"></i>' + info + '</span></span></button></li>';
  }).join('');
  if (!el.books.querySelector('[tabindex="0"]')) el.books.querySelector('button').tabIndex = 0;
}

/* ── player ── */
function renderHead() {
  const b = cur();
  el.head.innerHTML = cover(b) + '<div><small>' + (b.done ? 'Finished' : 'Chapter ' + (b.pos.c + 1) + ' of ' + b.ch.length) + '</small><h2>' + esc(b.title) + '</h2><p>' + esc(b.author) + ' · read by ' + esc(b.narr) + '</p></div>';
}
const R = 97;
const pt = a => { const r = a * Math.PI * 2; return [100 + R * Math.sin(r), 100 - R * Math.cos(r)]; };
const arc = (a0, a1) => { const [x0, y0] = pt(a0), [x1, y1] = pt(a1); return 'M' + x0.toFixed(2) + ' ' + y0.toFixed(2) + 'A' + R + ' ' + R + ' 0 ' + (a1 - a0 > .5 ? 1 : 0) + ' 1 ' + x1.toFixed(2) + ' ' + y1.toFixed(2); };
function renderOuter() {
  const b = cur(), tot = total(b), gap = .0045;
  let acc = 0, h = '';
  b.ch.forEach((c, i) => {
    const a0 = acc / tot, a1 = (acc + c.d) / tot; acc += c.d;
    const cls = b.done || i < b.pos.c ? 'is-done' : i === b.pos.c ? 'is-cur' : '';
    h += '<path class="' + cls + '" d="' + arc(a0 + gap, a1 - gap) + '"/>';
  });
  h += '<path class="apv-book-curp" d=""/>';
  MARKS[b.id].forEach(m => { const [x, y] = pt((before(b, m.c) + m.t) / tot); h += '<circle cx="' + x.toFixed(2) + '" cy="' + y.toFixed(2) + '" r="3"/>'; });
  el.outer.innerHTML = h;
  updateCurArc();
}
function updateCurArc() {
  const b = cur(), tot = total(b), p = el.outer.querySelector('.apv-book-curp');
  if (!p) return;
  if (b.done) { p.setAttribute('d', ''); return; }
  const a0 = before(b, b.pos.c) / tot + .0045, a1 = a0 + Math.max(0, b.pos.t / tot - .0045);
  p.setAttribute('d', b.pos.t > 1 ? arc(a0, Math.max(a0 + .0005, a1)) : '');
}
/* the voice ring: 72 bars, each with its own amplitude and tempo */
const vox = document.createElement('div');
vox.className = 'apv-book-vox'; vox.setAttribute('aria-hidden', 'true');
let seed = 7;
const rnd = () => (seed = (seed * 16807) % 2147483647) / 2147483647;
vox.innerHTML = Array.from({ length: 72 }, (_, i) => '<i style="--i:' + i + ';--a:' + (.35 + rnd() * .65).toFixed(2) + ';--d:' + Math.round(620 + rnd() * 680) + 'ms"></i>').join('');
el.dial.insertBefore(vox, el.dial.querySelector('.apv-book-arm'));
const bars = [...vox.children];
let lastPast = -1, lastSec = -1;

function updateDial(force) {
  const b = cur(), c = b.ch[b.pos.c], p = Math.min(.99999, b.pos.t / c.d);
  el.dial.style.setProperty('--apv-book-p', p.toFixed(5));
  const past = Math.floor(p * 72);
  if (past !== lastPast) { bars.forEach((x, i) => x.classList.toggle('is-past', i < past)); lastPast = past; }
  const sec = Math.floor(b.pos.t);
  if (sec === lastSec && !force) return;
  lastSec = sec;
  el.center.innerHTML = '<small>Chapter ' + (b.pos.c + 1) + '</small><strong>' + fmt(b.pos.t) + '</strong><span>' + esc(c.t) + '</span><em>−' + fmt(c.d - b.pos.t) + '</em>';
  el.dial.setAttribute('aria-valuemin', '0');
  el.dial.setAttribute('aria-valuemax', String(c.d));
