  el.left.innerHTML = b.done ? 'You finished this book. Press play to start it again.' :
    'Chapter ends in <b>' + fmt((c.d - b.pos.t) / sp) + '</b> · <b>' + human(left / sp) + '</b> left in book' + (sp !== 1 ? ' at ' + sp + '×' : '');
  updateCurArc();
  const row = el.list.querySelector('.apv-book-cp');
  if (row) row.style.setProperty('--v', (b.pos.t / c.d * 100).toFixed(1) + '%');
  if (S.sleep !== 'off') renderSleepOut();
}
function glide() {
  if (RM.matches) return;
  el.dial.classList.add('is-glide');
  clearTimeout(glide.t); glide.t = setTimeout(() => el.dial.classList.remove('is-glide'), 560);
}

/* ── side: chapters and bookmarks ── */
function renderList() {
  const b = cur();
  root.querySelectorAll('[data-tab]').forEach(t => { const on = t.dataset.tab === S.tab; t.setAttribute('aria-selected', on); t.tabIndex = on ? 0 : -1; });
  el.markn.textContent = MARKS[b.id].length;
  if (S.tab === 'chapters') {
    el.list.setAttribute('aria-label', 'Chapters');
    el.list.innerHTML = '<ol class="apv-book-chs">' + b.ch.map((c, i) => {
