css:
/* Tidewater Live: a stargazing stream. The sky is a canvas, chat reacts to
   what the live feed shows, and red-light mode filters the whole app the way
   observatories do to protect night vision. */
@property --apv-live-cd { syntax: '<number>'; inherits: true; initial-value: 0; }
@keyframes apv-live-pulse { 0% { box-shadow: 0 0 0 0 color-mix(in oklch, white 70%, transparent); } 70%, 100% { box-shadow: 0 0 0 6px transparent; } }
@keyframes apv-live-cool { from { --apv-live-cd: 1; } to { --apv-live-cd: 0; } }
@keyframes apv-live-shake { 20%, 60% { translate: -3px 0; } 40%, 80% { translate: 3px 0; } }
@keyframes apv-live-in { from { opacity: 0; translate: 0 8px; } }

.apv-live {
  /* re-theme with these four */
  --apv-live-bg: oklch(0.175 0.008 70);
  --apv-live-ink: oklch(0.94 0.008 85);
  --apv-live-accent: oklch(0.83 0.12 168);
  --apv-live-live: oklch(0.62 0.22 25);

  --apv-live-panel: color-mix(in oklch, var(--apv-live-bg), black 22%);
  --apv-live-raise: color-mix(in oklch, var(--apv-live-bg), var(--apv-live-ink) 7%);
  --apv-live-raise2: color-mix(in oklch, var(--apv-live-bg), var(--apv-live-ink) 12%);
  --apv-live-line: color-mix(in oklch, var(--apv-live-ink) 9%, transparent);
  --apv-live-line2: color-mix(in oklch, var(--apv-live-ink) 16%, transparent);
  --apv-live-mute: color-mix(in oklch, var(--apv-live-ink) 64%, var(--apv-live-bg));
  --apv-live-faint: color-mix(in oklch, var(--apv-live-ink) 40%, var(--apv-live-bg));
  --apv-live-tint: color-mix(in oklch, var(--apv-live-accent) 14%, var(--apv-live-bg));
  --apv-live-ease: cubic-bezier(.2, .8, .2, 1);
  --apv-live-spring: linear(0, 0.09 4%, 0.35 9%, 0.7 15%, 0.95 21%, 1.06 27%, 1.07 32%, 1.03 40%, 1.005 52%, 1);
  --apv-live-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;

  position: relative; width: 100%; height: var(--apv-live-h, 680px);
  container-type: inline-size; overflow: clip; isolation: isolate; box-sizing: border-box;
  background: var(--apv-live-bg); color: var(--apv-live-ink); color-scheme: dark; accent-color: var(--apv-live-accent);
  border-radius: 14px; font: 13px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-tap-highlight-color: transparent;
  filter: none;
  transition: filter .7s var(--apv-live-ease);

  & *, & *::before, & *::after { box-sizing: border-box; }
  &:focus { outline: none; }
  & :focus-visible { outline: 2px solid var(--apv-live-accent); outline-offset: 2px; border-radius: 6px; }
  & button, & input { font: inherit; color: inherit; }
  & button { cursor: pointer; background: none; border: 0; padding: 0; }
  & h2, & p, & ol, & ul { margin: 0; padding: 0; }
  & ol, & ul { list-style: none; }
  & svg { width: 18px; height: 18px; fill: none; stroke: currentColor; stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; flex: none; }
  & .apv-live-fill { fill: currentColor; stroke: none; }
  & kbd { font: 600 10px/1 var(--apv-live-mono); padding: 3px 5px 2px; min-width: 18px; display: inline-block; text-align: center; border: 1px solid var(--apv-live-line2); border-bottom-width: 2px; border-radius: 4px; color: var(--apv-live-mute); background: var(--apv-live-raise); }
  & output { font-variant-numeric: tabular-nums; }
}
/* red light: one filter over everything, like an observatory's night mode */
.apv-live[data-red="true"] { filter: grayscale(1) sepia(1) saturate(5.5) hue-rotate(-38deg) brightness(.82); }

.apv-live .apv-live-app {
  height: 100%; display: grid;
  grid-template-columns: minmax(0, 1fr) 340px;
  grid-template-rows: auto minmax(0, 1fr);
  grid-template-areas: "video chat" "info chat";
}

/* ── video ── */
.apv-live .apv-live-video {
  grid-area: video; position: relative; aspect-ratio: 16 / 9; overflow: hidden; background: oklch(0.12 0.02 255);
  & canvas { position: absolute; inset: 0; width: 100%; height: 100%; display: block; }
}
.apv-live .apv-live-rx { position: absolute; inset: 0; pointer-events: none; overflow: hidden; z-index: 1;
  & svg { position: absolute; right: 64px; bottom: 64px; width: 26px; height: 26px; color: oklch(0.72 0.19 15); fill: currentColor; stroke: none; }
}
.apv-live .apv-live-top {
  position: absolute; left: 12px; right: 12px; top: 12px; z-index: 2; display: flex; align-items: center; gap: 6px; pointer-events: none;
}
.apv-live .apv-live-badge {
  display: inline-flex; align-items: center; gap: 6px; height: 24px; padding: 0 9px 0 8px; border-radius: 6px;
  background: var(--apv-live-live); color: white; font: 800 11px/1 system-ui, sans-serif; letter-spacing: .1em; text-transform: uppercase; font-variant-numeric: tabular-nums;
  transition: background .3s;
  & i { width: 7px; height: 7px; border-radius: 50%; background: white; animation: apv-live-pulse 1.6s ease-out infinite; }
}
.apv-live[data-behind="true"] .apv-live-badge { background: oklch(0.35 0.01 70 / .85); letter-spacing: .02em; & i { animation: none; background: var(--apv-live-faint); } }
.apv-live .apv-live-pill {
  display: inline-flex; align-items: center; gap: 5px; height: 24px; padding: 0 8px; border-radius: 6px;
  background: oklch(0.1 0.01 255 / .55); color: oklch(0.96 0.01 85); font-size: 12px; font-weight: 600; backdrop-filter: blur(6px);
  & svg { width: 14px; height: 14px; }
  & span { font-weight: 500; opacity: .75; }
}
.apv-live .apv-live-mcount { transition: background .3s; &.is-hit { background: color-mix(in oklch, var(--apv-live-accent) 45%, oklch(0.1 0.01 255 / .55)); } }
.apv-live .apv-live-cam { margin-left: auto; font: 600 10px/1 var(--apv-live-mono); letter-spacing: .08em; color: oklch(1 0 0 / .55); }
.apv-live .apv-live-big {
  position: absolute; left: 50%; top: 50%; z-index: 2; width: 72px; height: 72px; margin: -36px 0 0 -36px; border-radius: 50%; display: grid; place-items: center;
  background: oklch(0.1 0.01 255 / .6); color: white; backdrop-filter: blur(8px); box-shadow: inset 0 0 0 1px oklch(1 0 0 / .2);
  opacity: 0; scale: .7; pointer-events: none; transition: opacity .25s, scale .45s var(--apv-live-spring);
  & svg { width: 30px; height: 30px; }
}
.apv-live[data-playing="false"] .apv-live-big { opacity: 1; scale: 1; pointer-events: auto; }
.apv-live .apv-live-ctl {
  position: absolute; left: 0; right: 0; bottom: 0; z-index: 2; padding: 26px 10px 8px;
  background: linear-gradient(transparent, oklch(0.08 0.01 255 / .78));
  transition: opacity .35s, translate .45s var(--apv-live-ease);
}
.apv-live .apv-live-video.is-idle:not(:focus-within) .apv-live-ctl { opacity: 0; translate: 0 8px; }
.apv-live .apv-live-video.is-idle:not(:focus-within) { cursor: none; }
.apv-live .apv-live-dvr {
  position: relative; height: 16px; display: grid; align-items: center; cursor: pointer; touch-action: none; margin: 0 4px;
  &:focus-visible { outline-offset: 0; }
}
.apv-live .apv-live-dvr-track {
  position: relative; height: 4px; border-radius: 2px; background: oklch(1 0 0 / .22); transition: height .2s var(--apv-live-ease);
  & .apv-live-dvr-fill { position: absolute; inset: 0; border-radius: inherit; background: var(--apv-live-live); transform-origin: left; scale: var(--pos, 1) 1; }
  & .apv-live-dvr-knob { position: absolute; top: 50%; left: calc(var(--pos, 1) * 100%); width: 13px; height: 13px; margin: -6.5px 0 0 -6.5px; border-radius: 50%; background: white; scale: 0; transition: scale .25s var(--apv-live-spring); }
  & [data-ticks] i { position: absolute; top: -3px; bottom: -3px; width: 3px; margin-left: -1.5px; border-radius: 2px; background: var(--apv-live-accent); opacity: .9; }
}
.apv-live .apv-live-dvr:hover .apv-live-dvr-track, .apv-live .apv-live-dvr:focus-visible .apv-live-dvr-track, .apv-live .apv-live-dvr.is-drag .apv-live-dvr-track { height: 6px; }
.apv-live .apv-live-dvr:hover .apv-live-dvr-knob, .apv-live .apv-live-dvr:focus-visible .apv-live-dvr-knob, .apv-live .apv-live-dvr.is-drag .apv-live-dvr-knob { scale: 1; }
.apv-live .apv-live-dvr-tip {
  position: absolute; bottom: 18px; left: 0; translate: -50% 0; padding: 4px 7px; border-radius: 6px; white-space: nowrap; pointer-events: none;
  background: oklch(0.1 0.01 255 / .9); color: white; font: 600 11px/1 var(--apv-live-mono); font-variant-numeric: tabular-nums;
  opacity: 0; transition: opacity .15s;
}
.apv-live .apv-live-dvr:hover .apv-live-dvr-tip, .apv-live .apv-live-dvr.is-drag .apv-live-dvr-tip { opacity: 1; }
.apv-live .apv-live-row {
  display: flex; align-items: center; gap: 2px; margin-top: 4px; color: oklch(0.97 0.005 85);
  & .apv-live-sp { flex: 1; }
  & > button { height: 34px; min-width: 34px; border-radius: 8px; display: grid; place-items: center; position: relative; transition: background .18s, scale .3s var(--apv-live-spring); }
  & > button:hover { background: oklch(1 0 0 / .12); }
  & > button:active { scale: .9; }
  & > button[aria-pressed="true"] { color: var(--apv-live-accent); }
}
.apv-live .apv-live-pp {
  & svg { grid-area: 1 / 1; width: 22px; height: 22px; transition: opacity .18s, scale .3s var(--apv-live-spring); }
  & .apv-live-ipl { opacity: 0; scale: .6; }
}
.apv-live[data-playing="false"] .apv-live-pp { & .apv-live-ipa { opacity: 0; scale: .6; } & .apv-live-ipl { opacity: 1; scale: 1; } }
.apv-live .apv-live-time { font: 600 12px/1 var(--apv-live-mono); padding: 0 8px; opacity: .9; }
.apv-live .apv-live-row > .apv-live-golive {
  display: none; grid-auto-flow: column; gap: 6px; padding: 0 10px; font-size: 12px; font-weight: 700; background: oklch(1 0 0 / .14);
  & i { width: 7px; height: 7px; border-radius: 50%; background: var(--apv-live-live); }
}
.apv-live[data-behind="true"] .apv-live-row > .apv-live-golive { display: grid; }
.apv-live .apv-live-tt {
  position: absolute; bottom: calc(100% + 8px); left: 50%; translate: -50% 4px; display: flex; gap: 6px; align-items: center; padding: 5px 6px 5px 9px; border-radius: 7px; white-space: nowrap;
  background: oklch(0.1 0.01 255 / .92); font-size: 11.5px; font-weight: 600; color: white; pointer-events: none; opacity: 0; transition: opacity .15s, translate .2s var(--apv-live-ease);
  & kbd { background: oklch(1 0 0 / .1); color: white; border-color: oklch(1 0 0 / .2); }
}
.apv-live .apv-live-ib:hover .apv-live-tt, .apv-live .apv-live-ib:focus-visible .apv-live-tt { opacity: 1; translate: -50% 0; }
.apv-live .apv-live-ib:last-child .apv-live-tt { left: auto; right: 0; translate: 0 4px; }
.apv-live .apv-live-ib:last-child:hover .apv-live-tt, .apv-live .apv-live-ib:last-child:focus-visible .apv-live-tt { translate: 0 0; }

/* ── info ── */
.apv-live .apv-live-tabs { display: none; }
.apv-live .apv-live-info {
  grid-area: info; min-height: 0; overflow: auto; padding: 16px 18px 14px; display: grid; align-content: start; gap: 14px;
  container: apv-live-info / inline-size; scrollbar-width: thin; scrollbar-color: var(--apv-live-line2) transparent;
}
.apv-live .apv-live-chan {
  display: grid; grid-template-columns: auto minmax(0, 1fr) auto; gap: 12px; align-items: start;
  & h2 { font-size: clamp(15px, 1.5cqi, 18px); line-height: 1.25; font-weight: 700; letter-spacing: -.015em; text-wrap: balance; }
  & p { display: flex; flex-wrap: wrap; align-items: center; gap: 4px 6px; margin-top: 4px; font-size: 12.5px; color: var(--apv-live-mute); }
  & p b { color: var(--apv-live-accent); font-weight: 650; }
  & p span { color: var(--apv-live-faint); font-variant-numeric: tabular-nums; }
  & p span::before { content: "\00b7"; margin-right: 6px; }
}
.apv-live .apv-live-ver { width: 14px; height: 14px; color: var(--apv-live-accent); }
.apv-live .apv-live-ava {
  width: 44px; height: 44px; border-radius: 50%; display: grid; place-items: center; font-weight: 800; font-size: 14px; letter-spacing: -.02em;
  background: radial-gradient(circle at 70% 30%, oklch(0.95 0.05 95) 0 10%, transparent 11%), linear-gradient(160deg, oklch(0.4 0.08 250), oklch(0.2 0.04 270));
  color: oklch(0.95 0.02 85); box-shadow: 0 0 0 2px var(--apv-live-bg), 0 0 0 4px var(--apv-live-live);
}
.apv-live .apv-live-tags { display: flex; flex-wrap: wrap; gap: 5px; margin-top: 8px;
  & li { padding: 3px 8px; border-radius: 20px; background: var(--apv-live-raise); font-size: 11px; font-weight: 600; color: var(--apv-live-mute); }
}
.apv-live .apv-live-follow {
  display: inline-flex; align-items: center; gap: 7px; height: 34px; padding: 0 12px; border-radius: 9px; font-weight: 700; font-size: 12.5px;
  background: var(--apv-live-accent); color: var(--apv-live-bg); transition: background .2s, color .2s, scale .3s var(--apv-live-spring);
  & output { font-weight: 600; opacity: .7; font-size: 11.5px; }
  & svg { width: 16px; height: 16px; transition: scale .4s var(--apv-live-spring); }
  &:active { scale: .95; }
  &[aria-pressed="true"] { background: var(--apv-live-raise2); color: var(--apv-live-ink); }
  &[aria-pressed="true"] svg { fill: var(--apv-live-live); stroke: var(--apv-live-live); scale: 1.12; }
}
.apv-live .apv-live-cards { display: grid; gap: 12px; }
@container apv-live-info (min-width: 600px) { .apv-live .apv-live-cards { grid-template-columns: 1.1fr 1fr; align-items: start; } }
.apv-live .apv-live-poll, .apv-live .apv-live-log {
  border-radius: 12px; padding: 12px; background: var(--apv-live-raise); box-shadow: inset 0 0 0 1px var(--apv-live-line);
  & header { display: flex; flex-wrap: wrap; align-items: baseline; gap: 2px 8px; margin-bottom: 10px; }
  & header b { font-size: 10.5px; font-weight: 800; letter-spacing: .14em; text-transform: uppercase; color: var(--apv-live-accent); }
  & header span { flex-basis: 100%; font-size: 13px; font-weight: 600; text-wrap: balance; }
  & header output { margin-left: auto; font: 600 11px/1 var(--apv-live-mono); color: var(--apv-live-mute); }
}
.apv-live .apv-live-log header span { font-size: 11.5px; font-weight: 500; color: var(--apv-live-faint); }
.apv-live .apv-live-opts { display: grid; gap: 6px; }
.apv-live .apv-live-opt {
  position: relative; width: 100%; display: grid; grid-template-columns: auto minmax(0, 1fr) auto; gap: 8px; align-items: center; padding: 8px 10px; border-radius: 8px; text-align: left; overflow: hidden;
  background: var(--apv-live-bg); box-shadow: inset 0 0 0 1px var(--apv-live-line); transition: box-shadow .2s;
  & .apv-live-bar { position: absolute; inset: 0; background: color-mix(in oklch, var(--apv-live-ink) 9%, transparent); transform-origin: left; scale: var(--v, 0) 1; transition: scale .8s var(--apv-live-ease), background .3s; z-index: 0; }
  & > :not(.apv-live-bar) { position: relative; z-index: 1; }
  & kbd { min-width: 20px; }
  & .apv-live-ol { font-size: 12.5px; font-weight: 600; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & .apv-live-pct { font: 650 12px/1 var(--apv-live-mono); font-variant-numeric: tabular-nums; }
  &:hover:not(:disabled) { box-shadow: inset 0 0 0 1px var(--apv-live-line2); }
  &[aria-pressed="true"] { box-shadow: inset 0 0 0 1.5px var(--apv-live-accent); }
  &[aria-pressed="true"] .apv-live-bar { background: color-mix(in oklch, var(--apv-live-accent) 26%, transparent); }
  &.is-win .apv-live-bar { background: color-mix(in oklch, var(--apv-live-accent) 34%, transparent); }
  &:disabled { cursor: default; }
}
.apv-live .apv-live-pollf { margin-top: 9px; font-size: 11.5px; color: var(--apv-live-faint); font-variant-numeric: tabular-nums; & b { color: var(--apv-live-mute); font-weight: 600; } }
.apv-live .apv-live-log ol { display: grid; gap: 2px; max-height: 210px; overflow: auto; scrollbar-width: thin; }
.apv-live .apv-live-mo {
  width: 100%; display: grid; grid-template-columns: 22px minmax(0, 1fr) auto; gap: 8px; align-items: center; padding: 6px 6px; border-radius: 7px; text-align: left; transition: background .18s;
  & svg { width: 16px; height: 16px; color: var(--apv-live-accent); }
  & span { font-size: 12.5px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & time { font: 600 11px/1 var(--apv-live-mono); color: var(--apv-live-mute); font-variant-numeric: tabular-nums; }
  &:hover:not(:disabled) { background: var(--apv-live-line); }
  &:disabled { cursor: not-allowed; opacity: .45; }
  &.is-new { animation: apv-live-in .45s var(--apv-live-ease); }
  &.is-clip svg { color: var(--apv-live-ink); }
}
.apv-live .apv-live-keys { display: flex; flex-wrap: wrap; align-items: center; gap: 4px 6px; font-size: 11px; color: var(--apv-live-faint); & kbd + kbd { margin-left: -3px; } }

/* ── chat ── */
.apv-live .apv-live-chat { grid-area: chat; position: relative; min-height: 0; display: flex; flex-direction: column; background: var(--apv-live-panel); border-left: 1px solid var(--apv-live-line); }
.apv-live .apv-live-chathead {
  display: flex; align-items: center; gap: 8px; padding: 12px 14px; border-bottom: 1px solid var(--apv-live-line);
  & > b { font-size: 13px; font-weight: 700; margin-right: auto; }
  & svg { width: 14px; height: 14px; }
}
.apv-live .apv-live-slow, .apv-live .apv-live-ppl { display: inline-flex; align-items: center; gap: 4px; font-size: 11px; font-weight: 600; color: var(--apv-live-mute); }
.apv-live .apv-live-slow { padding: 3px 7px; border-radius: 20px; background: var(--apv-live-raise); }
.apv-live .apv-live-pin {
  display: grid; grid-template-columns: auto minmax(0, 1fr) auto; gap: 8px; align-items: start; margin: 10px 10px 0; padding: 9px 8px 9px 10px; border-radius: 10px;
  background: var(--apv-live-tint); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--apv-live-accent) 22%, transparent); font-size: 12px; line-height: 1.4;
  & > svg { width: 15px; height: 15px; color: var(--apv-live-accent); margin-top: 1px; }
  & b { color: var(--apv-live-accent); margin-right: 4px; }
  & button { width: 22px; height: 22px; border-radius: 6px; display: grid; place-items: center; color: var(--apv-live-faint); }
  & button:hover { background: var(--apv-live-line); color: var(--apv-live-ink); }
  & button svg { width: 13px; height: 13px; }
  &[hidden] { display: none; }
}
.apv-live .apv-live-msgs {
  flex: 1; min-height: 0; overflow: auto; padding: 8px 6px 10px; overscroll-behavior: contain; scrollbar-width: thin; scrollbar-color: var(--apv-live-line2) transparent;
}
.apv-live .apv-live-m {
  padding: 3px 8px; border-radius: 6px; font-size: 13px; line-height: 1.45; overflow-wrap: anywhere; text-wrap: pretty;
  transition: opacity .3s, translate .35s var(--apv-live-ease);
  @starting-style { opacity: 0; translate: 0 6px; }
  & .apv-live-u { font-weight: 700; color: oklch(0.8 0.13 var(--h, 200)); border-radius: 4px; padding: 0 1px; }
  & .apv-live-u:hover { text-decoration: underline; text-underline-offset: 2px; }
  & .apv-live-u::after { content: ":"; color: var(--apv-live-mute); font-weight: 400; }
  & .apv-live-bdg { display: inline-grid; place-items: center; width: 16px; height: 16px; border-radius: 4px; vertical-align: -3px; margin-right: 4px; }
  & .apv-live-bdg svg { width: 12px; height: 12px; stroke-width: 2; }
  & .apv-live-bdg.is-mod { background: oklch(0.55 0.13 150); color: white; }
  & .apv-live-bdg.is-sub { background: color-mix(in oklch, var(--apv-live-accent) 24%, var(--apv-live-bg)); color: var(--apv-live-accent); }
  & .apv-live-at { font-weight: 650; color: var(--apv-live-ink); background: var(--apv-live-raise2); border-radius: 4px; padding: 0 3px; }
  &.is-mention { background: color-mix(in oklch, var(--apv-live-live) 16%, transparent); box-shadow: inset 2px 0 0 var(--apv-live-live); }
  &.is-me .apv-live-u { color: var(--apv-live-accent); }
  &.is-sys { color: var(--apv-live-mute); font-size: 12px; font-style: italic; text-align: center; padding: 6px 8px; }
  &.is-sys b { font-style: normal; color: var(--apv-live-ink); }
}
.apv-live .apv-live-e { display: inline-block; width: 19px; height: 19px; vertical-align: -5px; margin: 0 1px; color: oklch(0.82 0.15 var(--eh, 80)); }
.apv-live .apv-live-more {
  position: absolute; left: 50%; bottom: 112px; z-index: 3; display: inline-flex; align-items: center; gap: 6px; padding: 7px 12px 7px 9px; border-radius: 20px;
  background: var(--apv-live-accent); color: var(--apv-live-bg); font-size: 12px; font-weight: 700; box-shadow: 0 8px 20px -6px oklch(0 0 0 / .6);
  translate: -50% 0; transition: translate .35s var(--apv-live-spring), opacity .2s;
  @starting-style { translate: -50% 10px; opacity: 0; }
  & svg { width: 14px; height: 14px; stroke-width: 2.2; }
  &[hidden] { display: none; }
}
.apv-live .apv-live-compose { position: relative; padding: 10px; border-top: 1px solid var(--apv-live-line); display: grid; gap: 8px; }
.apv-live .apv-live-field {
  display: flex; align-items: center; gap: 4px; padding: 0 4px 0 11px; height: 38px; border-radius: 10px; background: var(--apv-live-raise); box-shadow: inset 0 0 0 1px var(--apv-live-line2); transition: box-shadow .2s;
  & input { flex: 1; min-width: 0; height: 100%; border: 0; outline: 0; background: none; font-size: 13px; }
  & input::placeholder { color: var(--apv-live-faint); }
  &:focus-within { box-shadow: inset 0 0 0 1.5px var(--apv-live-accent); }
  &.is-shake { animation: apv-live-shake .35s; }
}
.apv-live .apv-live-emob { width: 30px; height: 30px; border-radius: 7px; display: grid; place-items: center; color: var(--apv-live-mute); &:hover, &[aria-expanded="true"] { background: var(--apv-live-raise2); color: var(--apv-live-ink); } }
.apv-live .apv-live-send-row { display: flex; align-items: center; gap: 8px; }
.apv-live .apv-live-hint { flex: 1; min-width: 0; font-size: 11.5px; color: var(--apv-live-faint); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; & b { color: var(--apv-live-accent); } &.is-warn { color: var(--apv-live-live); } }
.apv-live .apv-live-send {
  position: relative; height: 30px; padding: 0 14px; border-radius: 8px; font-weight: 700; font-size: 12.5px; background: var(--apv-live-accent); color: var(--apv-live-bg); overflow: hidden;
  transition: scale .3s var(--apv-live-spring), opacity .2s;
  &::before { content: ""; position: absolute; inset: 0; background: conic-gradient(oklch(0 0 0 / .35) calc(var(--apv-live-cd) * 1turn), transparent 0); }
  & span { position: relative; }
  &:active { scale: .94; }
  &.is-cool { animation: apv-live-cool 3s linear both; }
}
.apv-live .apv-live-ac, .apv-live .apv-live-emo {
  position: absolute; left: 10px; right: 10px; bottom: calc(100% - 4px); z-index: 4; padding: 5px; border-radius: 11px;
  background: var(--apv-live-raise2); box-shadow: 0 16px 36px -10px oklch(0 0 0 / .7), inset 0 0 0 1px var(--apv-live-line2);
  transition: opacity .18s, translate .3s var(--apv-live-spring);
  @starting-style { opacity: 0; translate: 0 6px; }
  &[hidden] { display: none; }
}
.apv-live .apv-live-ac li {
  display: flex; align-items: center; gap: 8px; padding: 6px 8px; border-radius: 7px; font-size: 12.5px; font-weight: 650; cursor: pointer; color: oklch(0.8 0.13 var(--h, 200));
  & small { margin-left: auto; font-weight: 500; font-size: 11px; color: var(--apv-live-faint); }
  &[aria-selected="true"] { background: var(--apv-live-line2); }
}
.apv-live .apv-live-emo {
  display: grid; grid-template-columns: repeat(4, 1fr); gap: 2px;
  & button { display: grid; justify-items: center; gap: 2px; padding: 7px 2px; border-radius: 8px; font: 500 10px/1 var(--apv-live-mono); color: var(--apv-live-mute); transition: background .15s; }
  & button:hover, & button:focus-visible { background: var(--apv-live-line2); }
  & .apv-live-e { width: 24px; height: 24px; }
}
.apv-live .apv-live-card {
  position: absolute; z-index: 6; width: 236px; padding: 12px; border-radius: 13px; background: var(--apv-live-raise2);
  box-shadow: 0 22px 46px -12px oklch(0 0 0 / .75), inset 0 0 0 1px var(--apv-live-line2);
  transition: opacity .18s, scale .3s var(--apv-live-spring); transform-origin: top left;
  @starting-style { opacity: 0; scale: .94; }
  &[hidden] { display: none; }
  & header { display: flex; gap: 10px; align-items: center; margin-bottom: 10px; }
  & .apv-live-cava { width: 38px; height: 38px; border-radius: 50%; display: grid; place-items: center; font-weight: 800; color: var(--apv-live-bg); background: oklch(0.8 0.13 var(--h, 200)); }
  & strong { display: block; font-size: 13.5px; }
  & small { display: block; font-size: 11.5px; color: var(--apv-live-mute); }
  & .apv-live-cact { display: grid; grid-template-columns: 1fr 1fr; gap: 6px; }
  & .apv-live-cact button { height: 30px; border-radius: 8px; font-size: 12px; font-weight: 650; background: var(--apv-live-raise); box-shadow: inset 0 0 0 1px var(--apv-live-line2); }
  & .apv-live-cact button:hover { background: var(--apv-live-line2); }
}
.apv-live .apv-live-toast {
  position: absolute; left: 50%; bottom: 18px; z-index: 7; display: flex; align-items: center; gap: 12px; max-width: calc(100% - 32px);
  padding: 9px 9px 9px 14px; border-radius: 11px; background: var(--apv-live-ink); color: var(--apv-live-bg); font-size: 12.5px; font-weight: 500;
  box-shadow: 0 14px 34px -10px oklch(0 0 0 / .6);
  translate: -50% 16px; opacity: 0; pointer-events: none; transition: translate .4s var(--apv-live-spring), opacity .25s;
  & span { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; font-variant-numeric: tabular-nums; }
  & button { padding: 5px 10px; border-radius: 7px; font-weight: 700; background: color-mix(in oklch, var(--apv-live-accent) 45%, var(--apv-live-ink)); color: var(--apv-live-bg); }
  & button[hidden] { display: none; }
  &.is-on { translate: -50% 0; opacity: 1; pointer-events: auto; }
}

/* ── theater: the sky takes the whole app ── */
.apv-live[data-theater="true"] .apv-live-app { grid-template-columns: minmax(0, 1fr); grid-template-rows: minmax(0, 1fr); grid-template-areas: "video"; }
.apv-live[data-theater="true"] .apv-live-video { aspect-ratio: auto; }
.apv-live[data-theater="true"] :is(.apv-live-info, .apv-live-chat, .apv-live-tabs) { display: none; }

