  .apv-live .apv-live-info, .apv-live .apv-live-chat { grid-area: view; border-left: 0; }
  .apv-live[data-view="chat"] .apv-live-info, .apv-live[data-view="info"] .apv-live-chat { display: none; }
  .apv-live .apv-live-tabs {
    grid-area: tabs; display: flex; gap: 4px; padding: 6px 10px 0; border-bottom: 1px solid var(--apv-live-line); background: var(--apv-live-panel);
    & button { position: relative; padding: 8px 8px 10px; font-weight: 650; font-size: 12.5px; color: var(--apv-live-faint); display: inline-flex; gap: 6px; align-items: center; }
    & button[aria-selected="true"] { color: var(--apv-live-ink); }
    & button::after { content: ""; position: absolute; left: 8px; right: 8px; bottom: -1px; height: 2px; border-radius: 2px; background: var(--apv-live-accent); scale: 0 1; transition: scale .35s var(--apv-live-spring); }
    & button[aria-selected="true"]::after { scale: 1 1; }
    & output:not(:empty) { padding: 1px 6px; border-radius: 9px; background: var(--apv-live-live); color: white; font-size: 10.5px; }
  }
  .apv-live .apv-live-chathead { display: none; }
