  .apv-live .apv-live-time { padding: 0 4px; font-size: 11px; }
  .apv-live .apv-live-chan { grid-template-columns: auto minmax(0, 1fr); }
  .apv-live .apv-live-follow { grid-column: 1 / -1; justify-self: start; }
  .apv-live .apv-live-info { padding: 12px; }
  .apv-live .apv-live-row > .apv-live-golive { padding: 0 7px; }
}

@media (prefers-reduced-motion: reduce) {
  .apv-live { transition: none; }
  .apv-live .apv-live-badge i { animation: none; }
