  .apv-live .apv-live-mo.is-new { animation: none; }
  .apv-live .apv-live-field.is-shake { animation: none; }
  .apv-live .apv-live-opt .apv-live-bar { transition: scale .2s linear; }
  .apv-live .apv-live-ctl, .apv-live .apv-live-big, .apv-live .apv-live-toast { transition: opacity .2s; translate: none; }
  .apv-live .apv-live-toast { translate: -50% 0; }
  .apv-live .apv-live-video.is-idle:not(:focus-within) .apv-live-ctl { translate: none; }
}

