/* ── floating hearts ── */
function heart(mine) {
  if (RM.matches) { if (mine) $('[data-act="heart"]').animate([{ color: 'oklch(0.72 0.19 15)' }, { color: 'currentColor' }], { duration: 700 }); return; }
  if (el.rx.childElementCount > 24) return;
  const h = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
  h.setAttribute('viewBox', '0 0 24 24');
  h.innerHTML = '<path d="M12 19.5s-7.5-4.4-7.5-10A4.2 4.2 0 0 1 12 7a4.2 4.2 0 0 1 7.5 2.5c0 5.6-7.5 10-7.5 10Z"/>';
  if (!mine) h.style.color = 'oklch(0.8 0.12 ' + Math.round(rnd() * 360) + ')';
  el.rx.appendChild(h);
  const dx = (rnd() - .5) * 60, up = 150 + rnd() * 90, d = 1700 + rnd() * 700;
  h.animate([
    { transform: 'translate(0,0) scale(.4)', opacity: 0 },
    { transform: 'translate(' + (dx * .3) + 'px,-30px) scale(1.05)', opacity: 1, offset: .15 },
    { transform: 'translate(' + (-dx * .4) + 'px,' + (-up * .55) + 'px) scale(.95)', opacity: .9, offset: .55 },
    { transform: 'translate(' + dx + 'px,' + (-up) + 'px) scale(.8)', opacity: 0 },
  ], { duration: d, easing: 'cubic-bezier(.25,.6,.35,1)' }).onfinish = () => h.remove();
}

