    S.following = !S.following; S.followers += S.following ? 1 : -1;
    b.setAttribute('aria-pressed', S.following); b.querySelector('span').textContent = S.following ? 'Following' : 'Follow';
    el.followers.textContent = nf.format(S.followers);
  }
  else if (a === 'send') send();
  else if (a === 'emotes') emoToggle(el.emo.hidden);
  else if (a === 'more') { el.msgs.scrollTo({ top: el.msgs.scrollHeight, behavior: RM.matches ? 'auto' : 'smooth' }); unseen = 0; syncMore(); }
  else if (a === 'unpin') el.pin.hidden = true;
  else if (a === 'undo') undo();
  else if (b.dataset.emo) emoInsert(b.dataset.emo);
  else if (b.dataset.vote) vote(+b.dataset.vote);
  else if (b.dataset.mt) { seekTo(+b.dataset.mt - 3); if (!S.playing) setPlaying(true); toast('Rewound to ' + clock(+b.dataset.mt - 3), false); }
  else if (b.dataset.tab) setView(b.dataset.tab);
  else if (b.dataset.user) { if (cardFor === b && !el.card.hidden) closeCard(true); else openCard(b); }
  else if (b.dataset.cact) {
    const n = cardFor && cardFor.dataset.user;
    if (b.dataset.cact === 'mention') { closeCard(false); el.input.value = (el.input.value ? el.input.value.replace(/\s*$/, ' ') : '') + '@' + n + ' '; el.input.focus(); }
    else { closeCard(false); setMute(n, true); S.undo.push({ label: 'mute', undo: () => { setMute(n, false); toast('Showing ' + n + ' again', false); } }); toast('Hiding messages from ' + n, true); }
  }
});

/* ── keyboard ── */
function rove(box, e, sel, cols) {
  const items = [...box.querySelectorAll(sel)], i = items.indexOf(e.target.closest(sel));
  if (i < 0) return false;
  const step = { ArrowLeft: -1, ArrowRight: 1, ArrowUp: -cols, ArrowDown: cols }[e.key];
  if (step === undefined) return false;
  if (cols === 1 && (e.key === 'ArrowUp' || e.key === 'ArrowDown')) return false;
  e.preventDefault();
  const j = Math.max(0, Math.min(items.length - 1, i + step));
  items.forEach((x, k) => { x.tabIndex = k === j ? 0 : -1; }); items[j].focus();
  return true;
}
el.input.addEventListener('keydown', e => {
  if (ac && (e.key === 'ArrowDown' || e.key === 'ArrowUp')) { e.preventDefault(); ac.i = (ac.i + (e.key === 'ArrowDown' ? 1 : -1) + ac.names.length) % ac.names.length; acRender(); return; }
  if (ac && (e.key === 'Enter' || e.key === 'Tab')) { e.preventDefault(); acPick(ac.i); return; }
  if (e.key === 'Escape') { e.preventDefault(); e.stopPropagation(); if (ac) acClose(); else el.input.blur(), root.focus({ preventScroll: true }); return; }
  if (e.key === 'Enter') { e.preventDefault(); send(); }
});
root.addEventListener('keydown', e => {
  const t = e.target;
  if (t === el.input) return;
  if (e.key === 'Escape') {
    if (!el.card.hidden) closeCard(true);
    else if (!el.emo.hidden) { emoToggle(false); el.emob.focus(); }
    else if (S.theater) setTheater(false);
    return;
  }
  if (t.closest('[data-emo]') && rove(el.emo, e, 'button', 4)) return;
  if (t.closest('[role="tablist"]') && rove(t.closest('[role="tablist"]'), e, '[role="tab"]', 1)) { setView(root.querySelector('[role="tab"][tabindex="0"]').dataset.tab); return; }
  if ((e.metaKey || e.ctrlKey) && !e.altKey && e.key.toLowerCase() === 'z') { e.preventDefault(); undo(); return; }
  if (e.metaKey || e.ctrlKey || e.altKey) return;
  const k = e.key.length === 1 ? e.key.toLowerCase() : e.key;
  if ((k === ' ' && t.tagName !== 'BUTTON') || k === 'k') { e.preventDefault(); setPlaying(!S.playing); }
  else if (k === 'ArrowLeft' || k === 'ArrowRight') { e.preventDefault(); seekTo(playNow() + (k === 'ArrowLeft' ? -10 : 10)); }
  else if (k === 'l' || (k === 'End' && t === el.dvr)) goLive();
  else if (k === 'c') clip();
  else if (k === 'h') heart(true);
  else if (k === 't') setTheater(!S.theater);
  else if (k === 'r') setRed(!S.red);
  else if (k >= '1' && k <= '4') vote(+k - 1);
  else if (k === 'Enter' && t.tagName !== 'BUTTON') { e.preventDefault(); if (S.theater) setTheater(false); setView('chat'); el.input.focus(); }
  else return;
});

/* ── the loop: sky, chat, poll and counters ── */
let raf = 0, visible = true, lastTick = 0, lastPoll = 0, lastView = 0, lastMin = -1;
function loop(now) {
  if (!root.isConnected) { stop(); return; }
  raf = 0;
  if (!visible || document.hidden) return;
  const live = liveNow();
  /* every new live second: count meteors, and let chat react to the bright ones */
  const upto = Math.floor(live);
  if (upto - countedTo > 30) { for (let s = countedTo; s < upto - 30; s++) if (meteor(s)) counted++; countedTo = upto - 30; }
  for (; countedTo < upto; countedTo++) {
    const m = meteor(countedTo);
    if (!m) continue;
    counted++;
    el.meteors.textContent = nf.format(counted);
    el.mcount.classList.add('is-hit'); clearTimeout(lastTick); lastTick = setTimeout(() => el.mcount.classList.remove('is-hit'), 700);
    if (m.fire) {
      for (let i = 0; i < 5; i++) say(500 + i * 380 + rnd() * 500, pick(USERS.slice(1)), pick(FIRE));
      MOMENTS.push({ t: Math.floor(m.t0), label: m.green ? 'Fireball, green flash' : 'Fireball, long trail', ic: 'meteor', fresh: true });
      renderMoments();
      S.viewers += 20 + Math.round(rnd() * 40);
      for (let i = 0; i < 6; i++) setTimeout(() => { if (root.isConnected) heart(false); }, 300 + i * 160);
    } else if (m.mag > .62) {
      const n = 1 + Math.floor(rnd() * 2.4);
      for (let i = 0; i < n; i++) say(600 + i * 420 + rnd() * 700, pick(USERS.slice(1)), pick(BURST));
    }
  }
  if (now > nextChat) { addMsg(pick(USERS), pick(LINES)); nextChat = now + 700 + rnd() * 2100; }
  for (let i = 0; i < queue.length;) { if (queue[i].at <= now) { const q = queue.splice(i, 1)[0]; addMsg(q.u, q.text); } else i++; }
  if (now - lastPoll > 700) {
    lastPoll = now;
    if (!POLL.closed) {
      const add = Math.floor(rnd() * 4);
      for (let i = 0; i < add; i++) { let r = rnd(), j = 0; while (j < 3 && r > POLL.w[j]) { r -= POLL.w[j]; j++; } POLL.opts[j][1]++; }
      if (now >= POLL.ends) {
        POLL.closed = true;
        const { p } = pcts(), w = p.indexOf(Math.max(...p));
        sysMsg('<b>Poll closed</b> · ' + POLL.opts[w][0] + ' wins with ' + p[w] + '%. Big Esther moves after the peak.');
      }
      renderPoll();
    }
    if (rnd() < .25) heart(false);
  }
  if (now - lastView > 3000) {
    lastView = now;
    S.viewers = Math.max(2900, S.viewers + Math.round((rnd() - .47) * 16));
    el.viewers.textContent = nf.format(S.viewers);
    const min = Math.floor(live / 60);
    if (min !== lastMin) { lastMin = min; el.since.textContent = 'Started ' + Math.floor(live / 3600) + ' h ' + (min % 60) + ' min ago'; renderMoments(); }
    else renderTicks();
  }
  /* the rewind buffer only holds thirty minutes */
  if (S.frozen != null && live - S.frozen > WINDOW) { S.frozen = live - WINDOW; dirty = true; }
  if (S.playing || dirty) { draw(playNow()); dirty = false; }
  overlay();
  raf = requestAnimationFrame(loop);
}
function kick() { if (!raf && visible && !document.hidden) { nextChat = Math.max(nextChat, performance.now() + 400); raf = requestAnimationFrame(loop); } }
const io = new IntersectionObserver(es => { visible = es[es.length - 1].isIntersecting; if (visible) kick(); });
io.observe(root);
const ro = new ResizeObserver(() => { if (!root.isConnected) { stop(); return; } resize(); if (!raf) draw(playNow()); });
ro.observe(el.video);
function onVis() { if (!root.isConnected) { stop(); return; } if (!document.hidden) kick(); }
document.addEventListener('visibilitychange', onVis);
function stop() { io.disconnect(); ro.disconnect(); document.removeEventListener('visibilitychange', onVis); cancelAnimationFrame(raf); raf = 0; clearTimeout(idleT); }

el.meteors.textContent = nf.format(counted);
el.followers.textContent = nf.format(S.followers);
resize(); draw(playNow()); renderPoll(true); renderMoments(); overlay(true); setView('chat');
el.since.textContent = 'Started 2 h 14 min ago';
kick();

css:
/* Booth: a light, hardware-honest two-deck console. Warm white plastic,
   graphite print, one orange and one petrol deck. Everything moves from
   one clock: platters, waveforms, meters and the phase bar. */
@property --apv-dj-glow { syntax: '<number>'; inherits: false; initial-value: 0; }
@keyframes apv-dj-onair { 50% { --apv-dj-glow: 1; } }
@keyframes apv-dj-load { from { opacity: 0; translate: 0 -6px; filter: blur(3px); } }
@keyframes apv-dj-spinup { from { rotate: -200deg; } }

.apv-dj {
  /* re-theme with these four */
  --apv-dj-bg: oklch(0.955 0.006 95);
  --apv-dj-ink: oklch(0.26 0.01 80);
  --apv-dj-a: oklch(0.67 0.19 42);
  --apv-dj-b: oklch(0.56 0.095 222);

  --apv-dj-panel: color-mix(in oklch, var(--apv-dj-bg), var(--apv-dj-ink) 4%);
  --apv-dj-well: color-mix(in oklch, var(--apv-dj-bg), var(--apv-dj-ink) 9%);
  --apv-dj-raise: color-mix(in oklch, var(--apv-dj-bg), white 65%);
  --apv-dj-line: color-mix(in oklch, var(--apv-dj-ink) 11%, transparent);
  --apv-dj-line2: color-mix(in oklch, var(--apv-dj-ink) 19%, transparent);
  --apv-dj-mute: color-mix(in oklch, var(--apv-dj-ink) 60%, var(--apv-dj-bg));
  --apv-dj-faint: color-mix(in oklch, var(--apv-dj-ink) 38%, var(--apv-dj-bg));
  --apv-dj-vinyl: color-mix(in oklch, var(--apv-dj-ink) 30%, oklch(0.16 0.004 80));
  --apv-dj-ease: cubic-bezier(.2, .8, .2, 1);
  --apv-dj-spring: linear(0, 0.09 4%, 0.35 9%, 0.7 15%, 0.95 21%, 1.06 27%, 1.07 32%, 1.03 40%, 1.005 52%, 1);
  --apv-dj-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --apv-dj-cap: linear-gradient(color-mix(in oklch, var(--apv-dj-bg), white 80%), color-mix(in oklch, var(--apv-dj-bg), var(--apv-dj-ink) 12%));

  position: relative; width: 100%; height: var(--apv-dj-h, 680px);
  container: apv-dj / inline-size; overflow: clip; isolation: isolate; box-sizing: border-box;
  background: var(--apv-dj-bg); color: var(--apv-dj-ink); color-scheme: light; accent-color: var(--apv-dj-a);
  border-radius: 14px; font: 13px/1.4 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-tap-highlight-color: transparent;

  & *, & *::before, & *::after { box-sizing: border-box; }
  &:focus { outline: none; }
  & :focus-visible { outline: 2px solid var(--apv-dj-ink); outline-offset: 2px; border-radius: 5px; }
  & button, & input { font: inherit; color: inherit; }
  & button { cursor: pointer; background: none; border: 0; padding: 0; }
  & h3, & p { margin: 0; }
  & svg { width: 18px; height: 18px; fill: none; stroke: currentColor; stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; flex: none; }
  & .apv-dj-fill { fill: currentColor; stroke: none; }
  & kbd { font: 600 10px/1 var(--apv-dj-mono); padding: 3px 4px 2px; min-width: 17px; display: inline-block; text-align: center; border: 1px solid var(--apv-dj-line2); border-bottom-width: 2px; border-radius: 4px; color: var(--apv-dj-mute); background: var(--apv-dj-raise); }
  & output { font-variant-numeric: tabular-nums; }
  & small { font-size: 9.5px; font-weight: 750; letter-spacing: .14em; text-transform: uppercase; color: var(--apv-dj-faint); }
}

.apv-dj .apv-dj-app {
  height: 100%; display: grid;
  grid-template-columns: minmax(0, 1fr) 232px minmax(0, 1fr);
  grid-template-rows: auto auto auto minmax(0, 1fr) auto;
  grid-template-areas: "top top top" "waves waves waves" "a mix b" "lib lib lib" "nav nav nav";
}

/* ── top bar ── */
.apv-dj .apv-dj-top {
  grid-area: top; display: flex; align-items: center; gap: 18px; padding: 10px 16px; border-bottom: 1px solid var(--apv-dj-line);
  & > :is(.apv-dj-master, .apv-dj-set) { display: flex; align-items: baseline; gap: 6px; }
  & > :is(.apv-dj-brand, .apv-dj-phase, .apv-dj-q) { display: flex; align-items: center; gap: 6px; }
}
.apv-dj .apv-dj-brand { margin-right: auto;
  & svg { width: 20px; height: 20px; color: var(--apv-dj-a); stroke-width: 2; }
  & b { font-size: 16px; font-weight: 800; letter-spacing: -.03em; }
}
.apv-dj .apv-dj-master {
  & output { font: 650 18px/1 var(--apv-dj-mono); letter-spacing: -.02em; }
  & span { font-size: 11px; color: var(--apv-dj-mute); }
  & em { font-style: normal; font: 800 10px/1 system-ui, sans-serif; padding: 3px 5px; border-radius: 4px; color: white; background: var(--apv-dj-a); align-self: center; transition: background .3s; }
  & em.is-b { background: var(--apv-dj-b); }
}
.apv-dj .apv-dj-phbar {
  position: relative; width: 120px; height: 10px; border-radius: 5px; background: var(--apv-dj-well); box-shadow: inset 0 1px 2px color-mix(in oklch, var(--apv-dj-ink) 15%, transparent);
  &::before { content: ""; position: absolute; left: 50%; top: -2px; bottom: -2px; width: 1px; background: var(--apv-dj-line2); }
  & i { position: absolute; top: 1px; left: calc(50% + var(--ph, 0) * 100%); width: 14px; height: 8px; margin-left: -7px; border-radius: 4px; background: var(--apv-dj-b); transition: background .25s; }
  & i.is-lock { background: oklch(0.6 0.13 150); }
  & i.is-off { opacity: .25; }
}
.apv-dj .apv-dj-q { cursor: pointer; font-size: 12px; font-weight: 600; & input { margin: 0; } }
.apv-dj .apv-dj-set output { font: 600 13px/1 var(--apv-dj-mono); }

/* ── waveforms ── */
.apv-dj .apv-dj-waves {
  grid-area: waves; position: relative; height: 124px; margin: 10px 12px 0; border-radius: 10px; overflow: hidden;
  background: color-mix(in oklch, var(--apv-dj-bg), var(--apv-dj-ink) 6%); box-shadow: inset 0 1px 3px color-mix(in oklch, var(--apv-dj-ink) 16%, transparent);
  & canvas { position: absolute; inset: 0; width: 100%; height: 100%; display: block; cursor: ew-resize; touch-action: none; }
}
.apv-dj .apv-dj-zoom {
  position: absolute; right: 8px; top: 50%; translate: 0 -50%; display: grid; gap: 2px; padding: 2px; border-radius: 8px; background: color-mix(in oklch, var(--apv-dj-raise) 85%, transparent); backdrop-filter: blur(4px); box-shadow: 0 1px 3px color-mix(in oklch, var(--apv-dj-ink) 20%, transparent);
  & button { width: 24px; height: 22px; border-radius: 6px; display: grid; place-items: center; color: var(--apv-dj-mute); }
  & button:hover { background: var(--apv-dj-well); color: var(--apv-dj-ink); }
  & svg { width: 14px; height: 14px; stroke-width: 2; }
}

/* ── decks ── */
.apv-dj .apv-dj-deck {
  --c: var(--apv-dj-a);
  container-type: inline-size; min-width: 0; display: grid; gap: 7px 12px; padding: 12px 14px;
  grid-template-columns: auto minmax(0, 1fr) 30px; grid-template-rows: auto auto auto auto;
  grid-template-areas: "plat head pitch" "plat ov pitch" "plat pads pitch" "plat trans pitch";
  &[data-deck="0"] { grid-area: a; }
  &[data-deck="1"] { grid-area: b; --c: var(--apv-dj-b); grid-template-columns: 30px minmax(0, 1fr) auto; grid-template-areas: "pitch head plat" "pitch ov plat" "pitch pads plat" "pitch trans plat"; }
}
.apv-dj .apv-dj-head {
  grid-area: head; display: grid; grid-template-columns: auto minmax(0, 1fr) auto auto; gap: 9px; align-items: center;
  & .apv-dj-letter { width: 24px; height: 24px; border-radius: 6px; display: grid; place-items: center; font-weight: 800; font-size: 12px; color: white; background: var(--c); }
  & .apv-dj-meta { min-width: 0; }
  & strong { display: block; font-size: 13.5px; font-weight: 700; letter-spacing: -.01em; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & .apv-dj-meta span { display: block; font-size: 11.5px; color: var(--apv-dj-mute); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & .apv-dj-meta.is-in { animation: apv-dj-load .45s var(--apv-dj-ease); }
}
.apv-dj .apv-dj-read { display: grid; justify-items: end; gap: 2px;
  & output { font: 650 15px/1 var(--apv-dj-mono); letter-spacing: -.02em; }
  & .apv-dj-key { font: 700 11px/1 var(--apv-dj-mono); padding: 3px 5px; border-radius: 4px; background: color-mix(in oklch, var(--c) 16%, var(--apv-dj-bg)); color: color-mix(in oklch, var(--c) 70%, var(--apv-dj-ink)); }
}
.apv-dj .apv-dj-ovw { grid-area: ov; display: grid; gap: 3px; }
.apv-dj .apv-dj-ov { position: relative; height: 30px; border-radius: 5px; overflow: hidden; background: var(--apv-dj-panel); box-shadow: inset 0 0 0 1px var(--apv-dj-line); cursor: pointer;
  & canvas { position: absolute; inset: 0; width: 100%; height: 100%; display: block; }
}
.apv-dj .apv-dj-times { display: flex; justify-content: space-between; font: 600 11px/1 var(--apv-dj-mono); color: var(--apv-dj-mute);
  & .is-warn { color: var(--apv-dj-a); animation: apv-dj-onair .9s steps(1) infinite; }
}
.apv-dj .apv-dj-platw {
  grid-area: plat; align-self: center; width: clamp(92px, 29cqi, 150px); aspect-ratio: 1; border-radius: 50%; padding: 5%; position: relative;
  background: conic-gradient(from 20deg, oklch(0.93 0.004 95), oklch(0.82 0.004 95), oklch(0.96 0.003 95), oklch(0.8 0.004 95), oklch(0.94 0.004 95), oklch(0.83 0.004 95), oklch(0.93 0.004 95));
  box-shadow: inset 0 1px 3px color-mix(in oklch, var(--apv-dj-ink) 30%, transparent), 0 1px 0 white;
  &::after { content: ""; position: absolute; inset: 5%; border-radius: 50%; pointer-events: none; background: conic-gradient(from 300deg, transparent 0 8%, oklch(1 0 0 / .14) 13%, transparent 20% 52%, oklch(1 0 0 / .08) 58%, transparent 66%); }
}
.apv-dj .apv-dj-plat {
  width: 100%; height: 100%; border-radius: 50%; position: relative; touch-action: none; cursor: grab;
  background: repeating-radial-gradient(circle, var(--apv-dj-vinyl) 0 1.4px, color-mix(in oklch, var(--apv-dj-vinyl), white 6%) 1.4px 2.8px);
  box-shadow: 0 6px 14px -6px oklch(0 0 0 / .55);
  &:active { cursor: grabbing; }
  &:focus-visible { outline-offset: 4px; border-radius: 50%; }
  & .apv-dj-lbl {
    position: absolute; inset: 31%; border-radius: 50%; display: grid; place-items: center; background: var(--c); color: white;
    font: 800 clamp(9px, 3.2cqi, 13px)/1 system-ui, sans-serif; letter-spacing: .04em;
    box-shadow: inset 0 0 0 2px color-mix(in oklch, var(--c), black 15%);
  }
  & .apv-dj-lbl::after { content: ""; position: absolute; width: 9%; aspect-ratio: 1; border-radius: 50%; background: var(--apv-dj-bg); }
  & .apv-dj-lbl b { translate: 0 -95%; }
  & .apv-dj-mk { position: absolute; left: calc(50% - 1.5px); top: 3%; width: 3px; height: 24%; border-radius: 2px; background: oklch(0.97 0.01 95); }
  &.is-new { animation: apv-dj-spinup .7s var(--apv-dj-ease); }
}
.apv-dj .apv-dj-pads { grid-area: pads; display: grid; grid-template-columns: repeat(4, 1fr); gap: 5px;
  & button {
    position: relative; height: 28px; border-radius: 6px; font: 700 11px/1 var(--apv-dj-mono); color: var(--apv-dj-faint);
    background: var(--apv-dj-raise); box-shadow: inset 0 0 0 1px var(--apv-dj-line2), 0 1px 0 color-mix(in oklch, var(--apv-dj-ink) 10%, transparent);
    transition: background .15s, color .15s, scale .25s var(--apv-dj-spring), box-shadow .2s;
  }
  & button:hover { box-shadow: inset 0 0 0 1px var(--apv-dj-faint); }
  & button:active, & button.is-hit { scale: .93; }
  & button.is-set { background: var(--pc); color: white; box-shadow: inset 0 -2px 0 oklch(0 0 0 / .18); }
  & button span { position: absolute; right: 5px; bottom: 4px; font: 500 8.5px/1 var(--apv-dj-mono); opacity: .75; }
}
.apv-dj .apv-dj-trans { grid-area: trans; display: grid; grid-template-columns: 1fr 1.3fr 1fr 1fr; gap: 5px;
  & button {
    height: 32px; border-radius: 7px; display: flex; align-items: center; justify-content: center; gap: 5px; font: 750 10.5px/1 system-ui, sans-serif; letter-spacing: .1em;
    background: var(--apv-dj-raise); box-shadow: inset 0 0 0 1px var(--apv-dj-line2), 0 1px 0 color-mix(in oklch, var(--apv-dj-ink) 10%, transparent);
    transition: background .2s, color .2s, scale .25s var(--apv-dj-spring);
  }
  & button:active { scale: .95; }
  & button svg { width: 16px; height: 16px; }
  & [data-act="play"] { color: var(--c); }
  & [data-act="play"][aria-pressed="true"] { background: var(--c); color: white; box-shadow: 0 0 calc(var(--apv-dj-glow) * 12px) color-mix(in oklch, var(--c) 60%, transparent); animation: apv-dj-onair 1s ease-in-out infinite; }
  & [aria-pressed="true"]:not([data-act="play"]) { background: color-mix(in oklch, var(--c) 18%, var(--apv-dj-bg)); color: color-mix(in oklch, var(--c) 75%, var(--apv-dj-ink)); box-shadow: inset 0 0 0 1.5px var(--c); }
  & .apv-dj-ipa { display: none; }
  & [aria-pressed="true"] .apv-dj-ipa { display: block; }
